['Here is a basic C implementation of the task using POSIX threads (pthreads). It uses mutexes to ensure thread safety. The memory allocation and deallocation is optimized for reducing fragmentation.

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

void* allocate_and_init(size_t num_records, size_t range) {
    // Allocate memory for arrays and mutex
    long *offsets = malloc(num_records * sizeof(*offsets));
    if (offsets == NULL) return NULL;  // check allocation success

    int *keys = calloc(num_records, sizeof(*keys));  // initialize to zero
    if (keys == NULL) {
        free(offsets);
        return NULL;  // check allocation success
    }

    Record* records = malloc(num_records * sizeof(*records));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL;  // check allocation success
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    srand(time(NULL));  // seed random number generator

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);

        offsets[i] = rand() % range;  // set random value within the range
        keys[i] = rand();  // set random int value

        records[i].value = rand();  // initialize record field with random value

        pthread_mutex_unlock(&mutex);
    }

    // Return allocated memory and mutex as an opaque pointer. 
    // Note: In a real-world application, you would likely wrap these in a struct for better encapsulation and safety.
    return records;
}
```
This function allocates memory dynamically using malloc() and calloc(), which can be efficient for larger datasets due to their ability to allocate large chunks of contiguous memory at once, reducing the need for many small allocations. It also uses a mutex to ensure thread safety during allocation and initialization.
']

