        char buffer[256];
        while(fgets(buffer, sizeof(buffer), stdin)) {
            // skip comments
            if (buffer[0] != '#') {
                printf("%s", buffer);
            }
        }
    } else {
        for (int i = 1; i < argc; ++i) {
            FILE *file = fopen(argv[i], "r");

            // If the file cannot be opened, log the error and skip to the next file
