```C
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>

void get_ip(char *hostname, char* ip) {
    struct hostent *he;
    struct in_addr **addr_list;

    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname");
        return;
    }

    addr_list = (struct in_addr **) he->h_addr_list;

    for(int i = 0; addr_list[i] != NULL; i++) {
        strcpy(ip , inet_ntoa(*addr_list[i]) );
        return;
    }
}

void processFile(char *fileName){
    FILE *file = fopen ( fileName, "r" );

    if ( file == NULL ){
        printf ( "Could not open file\n" );
        return; 
    }

    char line[256];

    while (fgets(line, sizeof(line), file)) {

        // Assuming comma-separated fields with last two as numbers to find average
        char *token = strtok(line, ",");
        int i = 0; 
        double sum = 0.0;

        while (token != NULL) {
            if (i >= sizeof(line)/2){ // half of line size assuming avg is last two fields
                char *endptr;
                double num = strtod(token, &endptr);

                // checking for numeric value and non-empty field
                if (!(*endptr) && num != 0.0){ 
                    sum += num;
                }    
            }

            token = strtok(NULL, ",");
            i++;
        }

        double avg = 2*sum / (i+1); // Assuming average is last field of line
        printf("Average: %.2f\n", avg);  
    }

    fclose(file); 
}

int main() {
    char ip[100];
    get_ip("www.example.com", ip);
    printf("%s resolved to : %s \n", "www.example.com" , ip );

    processFile("testfile.txt");  // replace with your file name

    return 0;
}
```

This code uses the standard library function `gethostbyname` for DNS resolution and reads a configuration file line by line using `fgets`. It assumes that each line in the file is a comma-separated string and computes the average of last two fields assuming all are numeric values.

Please note, this code does not handle errors or manage system resources efficiently. You may need to add your own error handling and memory management strategies based on real-world constraints. This is just a simple base for you to start with.
