#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

void sigint_handler(int signum) {
    printf("\nInterrupt signal received, exiting...\n");
    exit(0);
}

int findMax(int* arr, int size) {
    if (size <= 0 || arr == NULL) return -1; // Return error code for invalid input.

    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void readFile(const char* filename, int** arr, int* size) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        perror("Error opening file");
        exit(-1); // Exit with an error code.
    }

    int capacity = 10;
    *arr = malloc(capacity * sizeof(int));
    if (*arr == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        exit(-1); // Exit with an error code.
    }

    int num, count = 0;
    while (fscanf(file, "%d", &num) == 1) {
        if (count == capacity) {
            capacity *= 2;
            *arr = realloc(*arr, capacity * sizeof(int));

            if (*arr == NULL) {
                perror("Memory allocation failed");
                fclose(file);
                exit(-1); // Exit with an error code.
            }
        }

        (*arr)[count++] = num;
    }

    *size = count;
    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler); // Register the SIGINT handler.

    const char* filename = "numbers.txt";
    int* arr = NULL;
    int size = 0;

    readFile(filename, &arr, &size);

    if (size == 0) {
        printf("No integers found in the file.\n");
    } else {
        int maxNum = findMax(arr, size);
        printf("Largest integer is: %d\n", maxNum);
    }

    free(arr); // Free allocated memory.
    return 0;
}
```
