['This is quite a broad task and writing an entire code would be a very long one. However, here's some skeleton code to help you get started. Due to the complexity of this task, it won't cover all aspects such as command line arguments parsing or error handling but serves as a basic outline for how you could implement this feature in C:

```c
#include <stdio.h>
#include <dlfcn.h>
#include <time.h>
#include <string.h>
#include <limits.h>

#define MAX_CACHE 1000

typedef struct {
    const char *name;
    void *(*func)();
} CryptoAlgo;

int cacheCount = 0;
CryptoAlgo *cache[MAX_CACHE] = { NULL };
time_t cacheTimestamp[MAX_CACHE];

void *loadSharedLib(const char* libPath, const char* funcName) {
    void *libHandle = dlopen(libPath, RTLD_LAZY);
    if (libHandle == NULL) return NULL;
    dlerror(); // Clear any existing error

    void *funcSymbol = dlsym(libHandle, funcName);
    const char *symbolError = dlerror();
    if (symbolError != NULL) {
        fprintf(stderr, "Could not load symbol from library: %s\n", symbolError);
        return NULL;
    }

    printf("Loaded symbol '%s' from shared lib '%s'\n", funcName, libPath);
    return funcSymbol;
}

CryptoAlgo* checkCache(const char *name) {
    time_t now = time(NULL);
    for (int i = 0; i < cacheCount; ++i) {
        if (strcmp(cache[i]->name, name) == 0 && difftime(now, cacheTimestamp[i]) <= 60)  // If available in last minute
            return cache[i];
    }

    if (cacheCount == MAX_CACHE) {   // Replace oldest entry with new one
        free(cache[0]);
        for (int i = 1; i < MAX_CACHE; ++i) 
            cache[i-1] = cache[i];
        --cacheCount;
    }

    CryptoAlgo *algo = malloc(sizeof(CryptoAlgo)); // Assume it exists in a shared lib
    algo->name = name;
    algo->func = loadSharedLib("/path/to/lib.so", name);  // Placeholder
    cache[cacheCount++] = algo;

    return algo;
}
```

