['Sure, here is a basic implementation of the function you requested in C++ using the STL's forward_list:

```cpp
#include <forward_list>
#include <algorithm>
using namespace std;

struct Configuration {
    enum Priority{ BEFORE, AFTER };
    Priority priority = BEFORE;
    size_t threshold = 1000; // Adjust as necessary for performance thresholds.
};

void insertAfter(forward_list<int>& list, int toFind, int toInsert, const Configuration& config) {
    auto it = find(list.begin(), list.end(), toFind);

    if (it == list.end()) { // If first integer is not found.
        list.push_front(toInsert);
        return;
    }

    forward_list<int>::iterator pos;
    switch(config.priority){
        case Configuration::BEFORE:
            if(distance(list.begin(), it) >= config.threshold){ // If performance threshold is reached.
                for(pos = list.before_begin(); distance(it, pos) != 1; ++pos);
                list.insert_after(pos, toInsert);
            } else {
                list.insert_after(it, toInsert);
            }
            break;
        case Configuration::AFTER:
            if(distance(list.begin(), it) >= config.threshold){ // If performance threshold is reached.
                pos = it;
                ++pos;
                list.insert_after(pos, toInsert);
            } else {
                list.insert_after(it, toInsert);
            }
            break;
        default:
            throw invalid_argument("Unknown priority");
    }
}
```
Please note that the implementation assumes that "delay in data availability" is not an issue as STL forward_list does not support random access iterators, and hence cannot be efficiently used for large lists. Also this code doesn't handle delays from external data source yet. You may need to integrate it with your own custom threading model or use a real-time operating system or language that supports low latency, multi-threading like CycloneDDS or ROS in order to handle such scenarios.
']

