['Here is a simple implementation of your requirements in C#. 

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Data.SqlClient;

public class QueryExecutor
{
    private readonly IDbConnection _connection;

    public QueryExecutor(IDbConnection connection)
    {
        this._connection = connection ?? throw new ArgumentNullException(nameof(connection));
    }

    public IDataReader ExecuteQueryWithParametersPaginated(string queryTemplate, Dictionary<string, object> parameters, int pageSize = 1000, Func<int, bool> continueExecution = null)
    {
        if (queryTemplate == null) throw new ArgumentNullException(nameof(queryTemplate));
        if (parameters == null) throw new ArgumentNullException(nameof(parameters));

        using (var command = _connection.CreateCommand())
        {
            command.Connection = _connection;
            command.CommandText = queryTemplate;

            foreach (var parameter in parameters)
            {
                var dbParameter = command.CreateParameter();
                dbParameter.Value = parameter.Value;
                command.Parameters.Add(dbParameter);
            }

            int pageNumber = 0;
            do
            {
                command.CommandText += $" OFFSET {pageSize * pageNumber} ROWS FETCH NEXT {pageSize} ROWS ONLY";

                using (var reader = command.ExecuteReader())
                    while (reader.Read())
                        yield return reader;

                if (continueExecution != null && !continueExecution(++pageNumber))
                    break;
            } 
            while (_connection.DatabaseCountRowsInLastQuery() == pageSize);
        }
    }
}
```
This implementation is quite basic and could be improved in several ways. The `_connection.DatabaseCountRowsInLastQuery()` method call assumes that we can count the rows in a database after performing an action, which might not be possible with all databases or drivers. Further improvements would include better error handling, reusable components for building queries, support for different types of connections and commands, and more robust ways to paginate through large datasets.
']

