```csharp
public XElement FindFirstElement(string xmlDocument, string elementName)
{
    XDocument doc = XDocument.Parse(xmlDocument); // Parses XML document

    var elements = doc.Descendants().Where(e => e.Name.LocalName == elementName).ToList(); // Finds matching elements

    if (elements.Count == 0) 
        throw new Exception("No element found with the given name");
    else if (elements.Count > 1) 
        throw new Exception("Multiple elements found with the given name");

    return elements.First(); // Returns first matching element
}
