```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;
import java.lang.Exception;

public class MD5Hasher {
    private static final AtomicInteger counter = new AtomicInteger(0);
    private static final long startTime = System.currentTimeMillis();

    public synchronized String getMD5Hash(String input) throws Exception{
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        // Rate limiting mechanism
        int currentCount = counter.incrementAndGet();
        long elapsedTime = System.currentTimeMillis() - startTime;
        if (elapsedTime < 60_000 && currentCount > 100) {
            throw new Exception("Rate limit exceeded");
        } else if (elapsedTime >= 60_000) {
            counter.set(0);
        }

        try{
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes(StandardCharsets.UTF_8));

            // Convert the bytes to hexadecimal for readability.
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b & 0xff));
            }

            return sb.toString();
        } catch (Exception e){
            throw new Exception("An error occurred while generating the MD5 Hash");
        }
    }
}
```
This is a simplified implementation, and doesn't include integrating with an external data source for logging or monitoring method's usage as it's more dependent on your specific use case. 

