using System;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using System.Threading.Tasks;
using System.Diagnostics;
using System.Collections.Concurrent;
using System.Linq;

public class WebApplicationService : IWebApplicationService
{
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _semaphores = new();

    // Assume this is the service for interacting with CMS.
    private readonly ICmsService _cmsService; 
    private readonly ILogger<WebApplicationService> _logger;

    public WebApplicationService(ICmsService cmsService, ILogger<WebApplicationService> logger)
    {
        _cmsService = cmsService;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateHtmlContent([FromBody] UpdateRequest request)
    {
        var sw = Stopwatch.StartNew();
        var semaphoreKey = $"{request.PageSectionId}_{request.ElementId}";

        if (!_semaphores.ContainsKey(semaphoreKey))
            _semaphores[semaphoreKey] = new SemaphoreSlim(1, 1);

        await _semaphores[semaphoreKey].WaitAsync();
        try
        {
            // Fetch metadata from CMS if required.
            var additionalMetadataTask = _cmsService.GetAdditionalMetadata(request.ElementId);

            // Update HTML content with service class.
            await UpdateHtmlContentInternal(request);

            // Wait for the fetching task to complete.
            var additionalMetadata = await additionalMetadataTask;

            sw.Stop();
            _logger.LogInformation("Update completed in {elapsed} ms.", sw.ElapsedMilliseconds);
        }
        catch (Exception ex)
        {
            // Return error response if an exception occurs.
            _logger.LogError(ex, "An error occurred while updating content.");

            return BadRequest("Update failed due to an error.");
        }
        finally
        {
            _semaphores[semaphoreKey].Release();
        }

        // Return refresh response if the operation was successful.
        return Ok(new RefreshResponse());
    }

    private async Task UpdateHtmlContentInternal(UpdateRequest request) 
    {
        // Implement service class logic to update HTML content here.
    }
}
```
