['Here is a JavaScript solution using Promises and the fetch API to load files in order and handle errors. It also checks if a file version or dependency has changed since last loaded:

```javascript
const loadedScripts = {};
let metadata; // This will be populated later by calling an external API

function validateUrl(url) {
  try { new URL(url); return true; }
  catch (err) { return false; }
}

async function loadFile(file, baseUrl, apiEndpoint) {
    const filePath = !validateUrl(file) ? `${baseUrl}/${file}` : file;
    if (!loadedScripts[file] && validateUrl(filePath)) {
      try {
        loadedScripts[file] = true;
        const metadataResponse = await fetch(apiEndpoint + '/' + file);
        metadata = await metadataResponse.json();

        if (metadata[file] && localStorage.getItem(file) === metadata[file].version) {
          console.log('Skipping ' + file + '. No changes detected.');
          return;
        }

        const response = await fetch(filePath);
        const text = await response.text();
        eval(text); // Execute the script
        localStorage.setItem(file, metadata[file].version);  // Update version in cache
      } catch (error) {
        loadedScripts[file] = false;
        console.log('Failed to load ' + file + '. Error: ' + error);
        return;
      }
    } else if (!validateUrl(filePath)) {
      console.log("Invalid URL for file " + file);
    }
}

async function loadAndExecuteFiles(files, options) {
  const { baseUrl = '', apiEndpoint = '' } = options || {};
  for (const file of files) {
    await loadFile(file, baseUrl, apiEndpoint);
  }
}
```
This solution assumes that the API endpoint will return a JSON object where each key is a filename and its value is an object with metadata like version. It also uses localStorage to cache script versions for subsequent loads.
