```c
#include <stdio.h>
#include <string.h>
#include <sys/time.h>

// Union-Find data structure
typedef struct {
    int parent;
    int rank;
} Subset;

int find(Subset subsets[], int i) {
    if (subsets[i].parent != i)
        subsets[i].parent = find(subsets, subsets[i].parent);

    return subsets[i].parent;
}

void Union(Subset subsets[], int x, int y) {
    int xroot = find(subsets, x);
    int yroot = find(subsets, y);

    if (subsets[xroot].rank < subsets[yroot].rank)
        subsets[xroot].parent = yroot;
    else if (subsets[xroot].rank > subsets[yroot].rank)
        subsets[yroot].parent = xroot;

    else {
        subsets[yroot].parent = xroot;
        subsets[xroot].rank++;
    }
}

void renameFile(char *filename, int numDigits, char *fileType) {
    char newFilename[50];
    strcpy(newFilename, filename);

    char *dot = strrchr(newFilename, '.');
    if (dot != NULL) 
        *dot = '\0';

    sprintf(filename, "%s.%*d%s", newFilename, numDigits, rand() % (int)(pow(10, numDigits)), fileType);
}

long long disjointPairs(int arr[], int n) {
    struct timeval start_time, end_time;

    Subset *subsets = malloc(sizeof(Subset)*n);

    for (int i = 0; i < n; ++i) {
        subsets[arr[i]].parent = arr[i];
        subsets[arr[i]].rank = 0;
    }

    long long countPairs = 0;  // Total disjoint pairs
    gettimeofday(&start_time, NULL);
    for (int i=0; i<n-1; ++i) {
        for (int j=i+1; j<n; ++j) {
            if (find(subsets, arr[i]) != find(subsets, arr[j])) {
                Union(subsets, arr[i], arr[j]);
                countPairs++;
            }

            gettimeofday(&end_time, NULL);
            printf("Milliseconds taken for this pair: %ld\n", ((end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_usec - start_time.tv_usec)/1000));
        }
    }

    free(subsets);

    return countPairs;
}
```
This code assumes that the number of elements in `arr[]` is `n`, and all elements are distinct. If duplicate values are present within the array, this could lead to incorrect results because there can't be more than one parent for a value which is supposed to point to itself if it is a root. The Union function assumes that `x` and `y` are in different subsets; they aren't checked if they're already in the same subset.
