["Here's a simple JavaScript solution using Node.js with fs module and the 'fs', 'forge', and 'request-promise' libraries:

```javascript
const fs = require('fs');
const requestPromise = require('request-promise');
const forge = require('node-forge');

async function readFile(path) {
    try {
        const data = await fs.promises.readFile(path, 'utf8');
        return data;
    } catch (err) {
        console.error(`Error reading file from ${path}: ${err}`);
        throw err;
    }
}

async function fetchAndCombineFiles(directoryPath, privateKeyUrl, certificateUrl) {
    let keyData, certData;
    try {
        keyData = await requestPromise({uri: privateKeyUrl, encoding: null});
        certData = await requestPromise({uri: certificateUrl, encoding: null});
    } catch (err) {
        console.error(`Error fetching files from ${privateKeyUrl} and ${certificateUrl}: ${err}`);
        throw err;
    }

    const pemKey = forge.pki.publicKeyFromPem(keyData).keyToPEM();
    const pemCert = forge.pki.publicKeyFromPem(certData).keyToPEM();

    return `${pemKey}\n\n${pemCert}`;
}
