['Here is the complete C code for your problem:

```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include "external_service.h" // assuming this is an external service that validates transaction IDs

#define WINDOW_SIZE 1000

typedef struct {
    int id;
    int age;
    int weight;
} Transaction;

typedef struct {
    Transaction* transactions;
    int count;
    long max_weight_sum;
    int max_weight_id;
    long total_age;
} Metrics;

void initialize_metrics(Metrics* metrics) {
    metrics->transactions = (Transaction*)malloc(WINDOW_SIZE * sizeof(Transaction));
    metrics->count = 0;
    metrics->max_weight_sum = LONG_MIN;
    metrics->max_weight_id = -1;
    metrics->total_age = 0;
}

void update_metrics(Metrics* metrics, Transaction new_transaction) {
    if (validateTransactionId(new_transaction.id)) {
        if (metrics->count < WINDOW_SIZE) {
            metrics->transactions[metrics->count++] = new_transaction;
            metrics->total_age += new_transaction.age;
        } else {
            Transaction* oldest_transaction = &(metrics->transactions[(metrics->count - WINDOW_SIZE) % WINDOW_SIZE]);
            if (oldest_transaction->weight * oldest_transaction->age == metrics->max_weight_sum) {
                metrics->max_weight_id = -1;
                metrics->max_weight_sum = LONG_MIN;
            }
            metrics->total_age += new_transaction.age - oldest_transaction->age;
            *oldest_transaction = new_transaction;
        }

        long weighted_sum = (long)new_transaction.weight * new_transaction.age;
        if (weighted_sum > metrics->max_weight_sum) {
            metrics->max_weight_sum = weighted_sum;
            metrics->max_weight_id = new_transaction.id;
        }
    }
}

Transaction find_max_weighted_sum(const Metrics* metrics) {
    Transaction max_trans = {0, 0, 0};

    if (metrics->count > 0) {
        for (int i = 0; i < metrics->count && i < WINDOW_SIZE; ++i) {
            long weighted_sum = (long)metrics->transactions[i].weight * metrics->transactions[i].age;

            if (weighted_sum > max_trans.weight * max_trans.age) {
                max_trans = metrics->transactions[i];
            }
        }
    }

    return max_trans;
}

void free_metrics(Metrics* metrics) {
    free(metrics->transactions);
}

int main() {
    Metrics m;
    initialize_metrics(&m);

    Transaction t1 = {1, 2, 5};
    Transaction t2 = {2, 1, 7};

    update_metrics(&m, t1);
    update_metrics(&m, t2);

    Transaction max_trans = find_max_weighted_sum(&m);

    printf("Max Weighted Sum: %ld\n", m.max_weight_sum);
    printf("Transaction ID with Max Weighted Sum: %d\n", m.max_weight_id);

    free_metrics(&m);
}
```
