['Here is the completed function in C++. It uses `std::random_device` and `std::mt19937` for generating random numbers and uses uniform distribution to select an attack type. The cooldown time adjusts based on health percentage, with a range of 5-15 seconds.

```cpp
#include <iostream>
#include <random>

void selectAttack(int currentHealthPercentage, int currentMana) {
    std::random_device rd;
    std::mt19937 gen(rd());

    // Adjust cooldown time based on health percentage.
    std::uniform_int_distribution<> disCooldownTime((5 - (currentHealthPercentage / 10)) * 2, (15 - (currentHealthPercentage / 10)) * 2);

    // Select attack type.
    int manaCosts[3] = {10, 20, 30};
    std::uniform_int_distribution<> disAttackType(0, 2);

    int selectedAttack;
    if (currentMana >= manaCosts[0]) {
        // If character has enough mana for any attack, select one randomly.
        do {
            selectedAttack = disAttackType(gen);
        } while (manaCosts[selectedAttack] > currentMana);
    } else {
        // Otherwise, choose an attack that can be performed without using mana.
        selectedAttack = 0;
    }

    int remainingMana = currentMana - manaCosts[selectedAttack];
    int cooldownTime = disCooldownTime(gen);

    // Print the result.
    std::cout << "Selected attack: " << selectedAttack << ", Cooldown time: " 
              << cooldownTime << ", Remaining mana: " << remainingMana << std::endl;
}
```
Please note that this code assumes that the game character is a magic user, where each attack consumes a certain amount of mana. If your game has different mechanics or requirements for attacks, you may need to adjust this code accordingly. This code also takes into account the current health percentage and adjusts the cooldown time dynamically.
