["```javascript
const fetch = require('node-fetch');
let callCount = 0;

function asyncReduce(array, initialValue, callback, errorLogger) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    array.reduce(async (accumulatedPromise, currentNumber) => {
      await accumulatedPromise;
      ++callCount;
      try {
        accumulator = await callback(accumulator, currentNumber);
      } catch (error) {
        if (errorLogger) errorLogger(error);
        reject(error);
      }
    }, Promise.resolve())
    .then(() => resolve(accumulator))
    .catch((error) => reject(error));
  });
}

function fetchAndReduce(url, initialValue, callback, errorLogger) {
  return new Promise((resolve, reject) => {
    fetch(url)
      .then((response) => response.json())
      .then((data) => asyncReduce(data, initialValue, callback, errorLogger))
      .then((result) => resolve(result))
      .catch((error) => {
        if (errorLogger) errorLogger(error);
        reject(error);
      });
  });
}

// Testing the function with a sample array:
const url = 'https://jsonplaceholder.typicode.com/posts';
const initialValue = 0;
const callback = (accumulator, currentNumber) => {
  return new Promise((resolve) => {
    setTimeout(() => resolve(accumulator + currentNumber), 100);
  });
};
const errorLogger = (error) => console.log('Error:', error);
fetchAndReduce(url, initialValue, callback, errorLogger)
  .then((result) => {
    console.log('Result:', result);
    console.log('Number of calls:', callCount);
  })
  .catch((error) => console.error('Error during reduction:', error));
```
