#include <stdlib.h>
#include <string.h>

char *append_or_limit(const char *input, size_t limit, int appendNewline) {
    if (input == NULL || input[0] == '\0') {
        return NULL;  // Handle null pointers and empty strings
    }

    size_t length = strlen(input);
    char *output;

    if (length >= limit) {
        return NULL;  // Return NULL for inputs exceeding the size limit
    } else {
        output = malloc(limit + 1);  // Allocate memory considering slash or newline
        if (output == NULL) {
            return NULL;  // Handle allocation failures
        }

        strncpy(output, input, limit - 1);  // Copy the input string
        output[limit - 1] = '\0';  // Ensure null-termination
    }

    if (appendNewline) {
        output[length++] = '\n';  // Append a newline character
    } else {
        output[length++] = '/';  // Append a slash character
    }

    output[length] = '\0';  // Ensure null-termination after appending

    return output;
}
```
