void findElements(Element* root, char* selector, Element*** results, int* resultCount) {
    if (testElement(selector, root->tagName)) {
        *results = realloc(*results, (*resultCount + 1) * sizeof(Element*));
        (*results)[*resultCount] = root;
        (*resultCount)++;
    }

    for (int i = 0; i < root->childCount; ++i) {
        findElements(root->children[i], selector, results, resultCount);
    }
}

// Calculate average of last two fields
double calculateAverage(char* line) {
    char* token = strtok(line, ",");
    int count = 0;
    double sum = 0.0;
    double values[2] = { 0.0 };

    while (token != NULL) {
        if (count < 2) {
            values[count % 2] = atof(token);
        } else {
            values[count % 2] = atof(token);
            sum += values[0] + values[1];
        }
        ++count;
        token = strtok(NULL, ",");
    }

    return count < 2 ? 0.0 : sum / (count - 1);
}

int main() {
    FILE* file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Failed to open the file\n");
        return 1;
    }

    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        // Remove trailing newline if any
        if (line[strlen(line) - 1] == '\n') line[strlen(line) - 1] = '\0';

        double avg = calculateAverage(line);
        printf("%s,%f\n", line, avg);
    }

    free(line);
    fclose(file);

    return 0;
}
```
This is a very basic implementation. It reads each line from the file and calculates average of last two fields. Also, it has a placeholder function `testElement` for testing elements based on selector. A real implementation would need to parse XML/HTML or implement similar functionality. It doesn't handle DOM traversal, memory management after reading a line or external data sources like fetching metadata from remote API.
