['Here is a C code example that handles the task with considerations to memory management and thread safety. It uses OpenSSL for AES-256-CBC cipher context creation along with SHA-256 hash function. This implementation also ensures thread safety by using a mutex lock around access to the cipher contexts:

```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>
#include <pthread.h>

// Defining fixed IV and key lengths
#define IV_LEN 16
#define KEY_LEN 32

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t mutex;
} cipher_context;

cipher_context* cipher_init(const char *password) {
    // Allocate memory for the cipher context
    cipher_context* ctx = (cipher_context*)malloc(sizeof(cipher_context));
    if (!ctx) return NULL;

    // Initialize EVP Context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }

    unsigned char key[KEY_LEN];

    // Derive the encryption key from password using SHA256 hash function
    SHA256((const unsigned char*)password, strlen(password), key);

    // Initializing cipher context with AES-256-CBC mode and fixed IV/key length
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        free(ctx);
        return NULL;
    }

    // Initialize mutex for thread safety
    pthread_mutex_init(&ctx->mutex, NULL);

    return ctx;
}

void cipher_cleanup(cipher_context* ctx) {
    if (!ctx) return;

    EVP_CIPHER_CTX_free(ctx->ctx);

    // Destroy mutex and free memory
    pthread_mutex_destroy(&ctx->mutex);
    free(ctx);
}
```
To use the cipher, you would call `cipher_init` to initialize a new cipher context. This returns a pointer to an allocated cipher context structure. To clean up and disable a cipher when it is no longer needed, call `cipher_cleanup` with the cipher context as argument.

This code ensures thread safety by using a mutex around access to the cipher contexts. However, note that this simple approach can have performance implications if multiple threads are trying to encrypt/decrypt data at the same time due to mutual exclusion locking overhead. To reduce this overhead, you could consider using a more efficient synchronization mechanism depending on your specific use case, such as spinlocks or reader-writer locks.
']

