#include <sys/wait.h>
#include <stdlib.h>
#include <stdio.h>

int runInBackground(const char* command) {
    pid_t childId = fork();

    if (childId == 0){ 
        system(command);
        exit(EXIT_SUCCESS); // This exits the child process and is necessary for wait().
    } else if (childId > 0) {
        int status = 0;
        waitpid(childId, &status, WNOHANG); 

        if (WIFEXITED(status)){
            return 1;
        }else{
            return 0;
        }
    } else { // Error occurred.
        return -1;
    }
}
