```csharp
using System;
using System.IO;
using System.Diagnostics;
using System.Net;
using Newtonsoft.Json;

public string AddWebsite(string directoryPath, string siteName, int requestedPort)
{
    // Validate directory path
    if  (!Directory.Exists(directoryPath) || Path.IsPathRooted(directoryPath))
    {
        return null;
    }

    // Check if web.config file exists
    string configFilePath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(configFilePath))
    {
        return null;
    }

    // Fetch available ports from external configuration service
    string response = FetchAvailablePortsFromService();
    List<int> availablePorts = ParseAvailablePorts(response);

    int assignedPort = 0;
    lock (availablePorts) 
    {
        if (availablePorts.Contains(requestedPort)) 
        {
            // Requested port is available, assign it to the website
            assignedPort = requestedPort;
            availablePorts.Remove(assignedPort);
        } 
        else if (availablePorts.Count > 0) 
        {
            // Assign any other available port
            assignedPort = availablePorts[0];
            availablePorts.RemoveAt(0);
        } 
        else 
        {
            return "No ports are currently available.";
        }
    }

    // Check for existing website on the same port
    foreach (string site in GetExistingSites(assignedPort))
    {
        if (site == siteName)
        {
            return "Site already exists on this port.";
        }
    }

    // Start the website process
    ProcessStartInfo startInfo = new ProcessStartInfo();
    startInfo.FileName = "cmd.exe";
    startInfo.Arguments = $"/c iisaddsitew /site_name:{siteName} /physical_path:{directoryPath} /bindings:http/*:{assignedPort}:";

    using (Process exeProcess = Process.Start(startInfo))
    {
        exeProcess.WaitForExit();
    }

    return $"Website added successfully on port {assignedPort}.";
}
