['```java
import java.io.*;
import java.util.concurrent.*;

public class CommandExecutor {

    private final int maxRetries;
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private final ExternalLoggingService logService;
    private final BlockingQueue<Command> commandQueue = new LinkedBlockingQueue<>();

    public CommandExecutor(int maxRetries, ExternalLoggingService logService) {
        this.maxRetries = maxRetries;
        this.logService = logService;
    }

    public void executeCommands() {
        while (!commandQueue.isEmpty()) {
            Command command = null;
            try {
                command = commandQueue.take();
                File fileToDelete = new File(command.getFilePath());
                if (fileToDelete.exists()) {
                    deleteFile(fileToDelete);
                }

                Process process = Runtime.getRuntime().exec(command.getCommand(), null, new File("."));
                BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                String outputLine;
                while ((outputLine = stdInput.readLine()) != null) {
                    logService.logOutput(command, outputLine);
                }
                while ((outputLine = stdError.readLine()) != null) {
                    logService.logError(command, outputLine);
                }

            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            } finally {
                if (command != null && command.getRetries() < maxRetries) {
                    commandQueue.offer(new Command(command.getCommand(), command.getFilePath(), command.getRetries() + 1));
                }
            }
        }
    }

    private void deleteFile(File fileToDelete) {
        if (!fileToDelete.delete()) {
            throw new RuntimeException("Unable to delete " + fileToDelete);
        }
    }
}

class Command {
    private final String command;
    private final String filePath;
    private int retries = 0;

    public Command(String command, String filePath) {
        this.command = command;
        this.filePath = filePath;
    }

    public Command(String command, String filePath, int retries) {
        this.command = command;
        this.filePath = filePath;
        this.retries = retries;
    }

    public String getCommand() {
        return command;
    }

    public String getFilePath() {
        return filePath;
    }

    public int getRetries() {
        return retries;
    }
}
``` 

This code defines a `CommandExecutor` class that manages command execution. The constructor takes the maximum number of retries and an instance of `ExternalLoggingService` as parameters. The `executeCommands` method runs indefinitely, taking commands from a queue and executing them. It deletes any existing file before each command to ensure a clean state. If a command fails due to a temporary issue, it is added back to the queue for retries up to the specified maximum. Command outputs and errors are logged via the `ExternalLoggingService` instance.
']

