    private readonly HttpClient _httpClient = new HttpClient(); //Replace this with your server address

    public async Task<DataTableReader> ProcessRemote(byte[] data)
    {
        var stringData = Encoding.UTF8.GetString(data); //Convert byte array to string

        var maxRetryAttempts = 3;  //Maximum retry attempts
        for (int i = 0; i < maxRetryAttempts; ++i)
        {
            try
            {
                HttpContent content = new StringContent(stringData, Encoding.UTF8, "application/json");
                var response = await _httpClient.PostAsync("your-endpoint", content); //Replace with your server endpoint

                if (response.IsSuccessStatusCode)
                {
                    var result = await response.Content.ReadAsStringAsync();

                    return JsonConvert.DeserializeObject<DataTableReader>(result);  //Parse the returned JSON into DataTableReader object
                }
            }
            catch (Exception ex)
            {
                if (i == maxRetryAttempts - 1) throw;  //Throw exception after all retry attempts fail

                Thread.Sleep(500);   //Wait for half a second before retrying
            }
        }

        return null;
    }
}
