```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public class AESGCMDecrypter 
{
    public byte[] Decrypt(byte[] cipherText, byte[] key, byte[] nonce, byte[] tag) 
    {
        // Check all the inputs for null or incorrect length
        if (cipherText == null || key == null || nonce == null || tag == null || 
            nonce.Length != 12 || key.Length != 32 || tag.Length != 16) 
        {
            throw new ArgumentException("Invalid input parameters");
        }

        byte[] plainText = null;

        // Create an AesGcm object
        using (AesGcm aesGcm = new AesGcm(key))
        {
            // Decrypt the ciphertext
            try
            {
                plainText = new byte[cipherText.Length];
                aesGcm.Decrypt(nonce, cipherText, tag, plainText);
            } 
            catch (CryptographicException e) 
            {
                // Decryption failed
                Console.WriteLine("The decryption operation failed: " + e.Message);
                return null;
            }
        }

        // Return the decrypted plaintext
        return plainText;
    }
}
```

This code encapsulates the decryption logic into an AESGCMDecrypter class that can be instantiated and used in a larger system where different inputs are expected. It also includes exception handling for invalid input parameters or decryption failures.
