public static class BinaryFileLoader<T> where T : new() {
    private const int MaxCacheSize = 10; // Adjust this based on system resource limitations
    private static readonly ConcurrentDictionary<string, CacheEntry> _cache = new(StringComparer.Ordinal);

    public static T LoadAndGetDataFromFile(string filePath, IExternalAPI externalApi) {
        var lastWriteTime = File.GetLastWriteTimeUtc(filePath);

        if (!_cache.TryGetValue(filePath, out var entry)) {
            lock (_cache) {
                if (!_cache.TryGetValue(filePath, out entry)) {
                    using (var fileStream = File.OpenRead(filePath)) {
                        var formatter = new BinaryFormatter();

                        T data;
                        try {
                            data = (T)formatter.Deserialize(fileStream);
                        } catch {
                            // Handle deserialization issue
                            throw;
                        }

                        entry = new CacheEntry(data, lastWriteTime, externalApi.GetMetadata());

                        while (_cache.Count >= MaxCacheSize) {
                            var oldestEntryKey = _cache.Keys.First();
                            _cache.TryRemove(oldestEntryKey, out _);
                        }

                        _cache[filePath] = entry;
                    }
                }
            }
        } else if (entry.LastWriteTime != lastWriteTime) {
            // The file has been updated externally
            lock (_cache) {
                using (var fileStream = File.OpenRead(filePath)) {
                    var formatter = new BinaryFormatter();

                    T data;
                    try {
                        data = (T)formatter.Deserialize(fileStream);
                    } catch {
                        // Handle deserialization issue
                        throw;
                    }

                    entry = new CacheEntry(data, lastWriteTime, externalApi.GetMetadata());
                }

                _cache[filePath] = entry;
            }
        }

        return entry.Data;
    }

    public static void MergeNewDataIntoFile(string filePath, T newData) {
        // Here you can provide a method to merge new data with the existing one without reloading the entire file
        throw new NotImplementedException();
    }

    private class CacheEntry {
        public DateTime LastWriteTime { get; }
        public object Metadata { get; }

        public T Data { get; set; } // Assuming your data structure is named as T

        public CacheEntry(T data, DateTime lastWriteTime, object metadata) {
            Data = data;
            LastWriteTime = lastWriteTime;
            Metadata = metadata;
        }
    }
}
