void allocate_and_initialize(size_t size, long offset_range, int key_range) {

    // Allocating memory for arrays and checking for NULL return
    long *offsets = malloc(sizeof(*offsets) * size);
    if (offsets == NULL) exit(EXIT_FAILURE);

    int *keys = malloc(sizeof(*keys) * size);
    if (keys == NULL) {
        free(offsets);
        exit(EXIT_FAILURE);
    }

    record *records = malloc(sizeof(*records) * size);
    if (records == NULL) {
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

