        keys[i] = rand() % key_range;
        offsets[i] = rand() % offset_range;
        records[i].value = rand() % (key_range + offset_range);

        // Ensure unique values for both arrays and within their ranges.
        while(keys[i] == keys[i-1]) keys[i] = rand() % key_range;
        while(offsets[i] == offsets[i-1]) offsets[i] = rand() % offset_range; 
    }

    // Sorting based on the offset values.
    for (size_t i = 0; i < size - 1; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            if (offsets[i] > offsets[j]) {
                long temp = offsets[i];
                offsets[i] = offsets[j];
                offsets[j] = temp;

                int temp_int = keys[i];
                keys[i] = keys[j];
                keys[j] = temp_int; 

                record temp_record = records[i];
                records[i] = records[j];
                records[j] = temp_record;  
