// Mutex for thread-safe memory allocation and deallocation
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateAndInitialize(size_t size, long lowBoundary, long highBoundary) {
    // Lock the mutex before memory allocation and initialization
    pthread_mutex_lock(&mutex);

    // Allocating memory for offset array of type 'long'
    long* offsets = malloc(sizeof(long) * size);
    if (offsets == NULL) {
        perror("Failed to allocate memory for offsets");
        pthread_mutex_unlock(&mutex); // Unlock the mutex before returning
        return NULL;
    }

    // Allocating memory for keys array of type 'int'
    int* keys = malloc(sizeof(int) * size);
    if (keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        pthread_mutex_unlock(&mutex); // Unlock the mutex before returning
        return NULL;
    }

    // Allocating memory for record array of type 'Record'
    Record* records = malloc(sizeof(Record) * size);
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex); // Unlock the mutex before returning
        return NULL;
    }

    srand((unsigned int) time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].value = lowBoundary + rand() % (highBoundary - lowBoundary);
    }

    // Unlock the mutex after memory allocation and initialization are done
    pthread_mutex_unlock(&mutex);

    return records;
}
```

