namespace myns {
    class RandomGenerator {
        public:
            static std::mt19937 mt; // Static member variable for the Mersenne Twister generator.

            RandomGenerator() = default;
            ~RandomGenerator() = default; // Trivial destructor.

            int getRandomNumber(int min, int max) {
                std::uniform_int_distribution<int> dist(min, max); 
                return dist(mt);
            }
    };

