                 std::mutex& mtx) {
    myns::RandomGenerator rg;

    for (size_t i = 0; i < n; ++i) {
        std::lock_guard<std::mutex> lock(mtx); // Ensuring thread safety by using a mutex.

        offsets[i] = rg.getRandomNumber(minVal, maxVal); // Filling the arrays with random values.
        keys[i] = rg.getRandomNumber(minVal, maxVal);
    }
