pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
node_t *head = NULL;

void* populateUeContext(char* IMSI, char* RRCState, radioBearer_t* bearers, int numOfBearers) {
    node_t * new_node = (node_t *) malloc(sizeof(node_t));

    if(new_node == NULL) return NULL;

    strncpy(new_node->data.IMSI, IMSI, sizeof(new_node->data.IMSI)-1);
    new_node->data.IMSI[sizeof(new_node->data.IMSI)-1] = '\0';

    strncpy(new_node->data.RRCState, RRCState, sizeof(new_node->data.RRCState)-1);
    new_node->data.RRCState[sizeof(new_node->data.RRCState)-1] = '\0';

    new_node->data.bearers = bearers;
    new_node->data.numOfBearers = numOfBearers;
    new_node->next = NULL;

    pthread_mutex_lock(&lock);  // Mutual exclusion lock
    if(head == NULL) {
        head = new_node;
    } else {
        node_t * current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);  // Release lock

    return new_node;
}
```
This code creates a linked list of UE Contexts. It also uses mutex locks to prevent race conditions during concurrent access. However, this is only basic and does not handle all the engineering challenges mentioned above due to its complexity.
