typedef struct {
    int value;
} record;

void initialize_records(long *offsets, int *keys, record **records, size_t max_offset, size_t num_keys) {
    srand(time(NULL));  // Seed the random number generator

    offsets = malloc(max_offset * sizeof(long));
    if (offsets == NULL) {
        printf("Memory allocation for offsets failed!\n");
        exit(1);
