    keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        printf("Memory allocation for keys failed!\n");
        free(offsets);
        exit(1);
    }

    records = calloc(num_keys, sizeof(record *));
    if (records == NULL) {
        printf("Memory allocation for records failed!\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    // Assigning unique random values to the record fields.
