    memset(usedValues, 0, num_keys * sizeof(int));
    for (size_t i = 0; i < num_keys; ++i) {
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            printf("Memory allocation for record %zu failed!\n", i);
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            exit(1);
