['```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/time.h>
#include <jni.h>
#include "java_Channel.h"

typedef struct {
    int value;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static JavaVM *jvm;
static jobject channel;
static jmethodID connectMethod, disconnectMethod;
static int maxConnections = 10;

void logEvent(const char *event) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    printf("[%ld.%06ld] %s\n", (long)tv.tv_sec, (long)tv.tv_usec, event);
}

void *allocateMemory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        logEvent("Failed to allocate memory");
        exit(-1);
    }
    return ptr;
}

int connectToRemote() {
    JNIEnv *env;
    (*jvm)->AttachCurrentThread(jvm, (void **)&env, NULL);

    jobject obj = (*env)->CallObjectMethod(env, channel, connectMethod);
    if (!obj) return -1;

    logEvent("Connected to remote address");
    return 0;
}

int disconnectFromRemote() {
    JNIEnv *env;
    (*jvm)->AttachCurrentThread(jvm, (void **)&env, NULL);

    (*env)->CallVoidMethod(env, channel, disconnectMethod);
    logEvent("Disconnected from remote address");
    return 0;
}

int connectIfNeeded() {
    static int connectionCount = 0;
    pthread_mutex_lock(&mutex);
    ++connectionCount;
    if (connectionCount > maxConnections) {
        logEvent("Rate limit reached, waiting for connections to close...");
        while (connectionCount > maxConnections) {
            usleep(100000);  // Sleep for 0.1s before checking again
        }
    }

    int ret = connectToRemote();
    pthread_mutex_unlock(&mutex);
    return ret;
}

void initJavaChannel() {
    JNIEnv *env;
    (*jvm)->AttachCurrentThread(jvm, (void **)&env, NULL);

    jclass clazz = (*env)->FindClass(env, "com/example/java_channel");
    connectMethod = (*env)->GetMethodID(env, clazz, "connect", "()Ljava/lang/Object;");
    disconnectMethod = (*env)->GetMethodID(env, clazz, "disconnect", "()V");

    channel = (*env)->NewGlobalRef(env, (*env)->AllocObject(env, clazz));
}

void freeMemory(void *ptr) {
    if (ptr) {
        free(ptr);
        logEvent("Freed memory");
    }
}

int initArraysAndRecords() {
    long *offsets = allocateMemory(sizeof(long) * 1024);
    int *keys = allocateMemory(sizeof(int) * 1024);

    record *records = allocateMemory(sizeof(record) * 1024);
    for (int i = 0; i < 1024; ++i) {
        records[i].value = rand() % 100;
    }

    freeMemory(offsets);
    freeMemory(keys);
    freeMemory(records);
}

void initSystemResources() {
    int ret = connectIfNeeded();
    if (ret < 0) {
        logEvent("Failed to establish connection");
        exit(-1);
    }

    initArraysAndRecords();
    disconnectFromRemote();
}

JNIEXPORT jint JNICALL JNI_OnLoad(JavaVM *vm, void *reserved) {
    jvm = vm;
    initJavaChannel();
    srand((unsigned int)time(NULL));
    return JNI_VERSION_1_6;
}
```
