    if (file == NULL) {
        printf("Failed to open configuration file. Using default values.\n");
        return (Config){ 10 };
    }

    Config config;
    fscanf(file, "%d", &config.max_size);

    fclose(file);

    return config;
}

int *read_array(const Config *config) {
    int *values = malloc(config->max_size * sizeof(int));

    if (values == NULL) {
        printf("Failed to allocate memory. Aborting.\n");
        exit(-1);
    }

    for (int i = 0; i < config->max_size; ++i) {
        fscanf(stdin, "%d", &values[i]);
    }

    return values;
}

int find_largest(const int *array, const Config *config) {
    int largest = array[0];

    for (int i = 1; i < config->max_size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    return largest;
}

void free_memory(const int *ptr) {
    free((int*) ptr);
}

int main() {
    Config config = read_config();
    int *array = read_array(&config);
    int largest = find_largest(array, &config);

    printf("Largest integer: %d\n", largest);

    free_memory(array);

    return 0;
}
