    }

    // Function to filter records based on a given threshold value for their offset
    std::vector<Record> FilterRecords(int threshold) {
        std::lock_guard<std::mutex> lock(mtx);  // Thread safety

        std::vector<Record> filtered_records;
        std::copy_if(records.begin(), records.end(), std::back_inserter(filtered_records), [threshold](const Record& record) { return record.offset > threshold; });

        return filtered_records;
    }

private:
    // Function to generate a random value within the specified range
    int GenerateRandomValue() {
        std::uniform_int_distribution<int> distribution(min_value, max_value);
        return distribution(random_engine);
    }

    // Function to generate a record with a random value and unique offset
    Record GenerateRecord() {
        int value = GenerateRandomValue();

        std::uniform_int_distribution<int> distribution(0, num_records - 1);
        int offset;
        do {
            offset = distribution(random_engine);
        } while (std::find(offsets.begin(), offsets.end(), offset) != offsets.end());

        offsets.push_back(offset);

        return Record{value, offset};
    }

    // Function to check if all offsets are unique
    bool CheckUniqueOffsets() {
        std::sort(offsets.begin(), offsets.end());
        auto it = std::adjacent_find(offsets.begin(), offsets.end());

        return (it == offsets.end()) ? true : false;
    }

    // Function to sort the records based on their offset values in ascending order
    void SortRecords() {
        std::sort(records.begin(), records.end(), [](const Record& a, const Record& b) { return a.offset < b.offset; });
    }

    int num_records;
    int min_value;
    int max_value;
    std::vector<int> offsets;
    std::vector<Record> records;
    std::default_random_engine random_engine;
    std::mutex mtx;  // Mutex for thread safety
};
```
This code provides a solution to the described problem in C++. It uses classes, functions, and data structures provided by the Standard Library to create dynamic arrays of records with unique offsets, sort them based on their offset values, and filter them based on a given threshold. Thread safety is ensured through a mutex lock guard.
