['Here is a C implementation of your task using pthread for multithreading and a simple resizing strategy to avoid fragmentation. This code does not handle large datasets as it's out of scope of this question but you can expand it by implementing different data structures like Red-Black trees or B-trees.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    double value;
} Record;

// Mutex to avoid data corruption when multiple threads access the data structures at the same time
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

long* offsets;
int* keys;
double* values;
Record** records;
size_t size = 0, capacity = 16; // Initial capacities can be different based on your requirements.

void resize(size_t newCapacity) {
    long* newOffsets = realloc(offsets, sizeof(*newOffsets) * newCapacity);
    int* newKeys = realloc(keys, sizeof(*newKeys) * newCapacity);
    double* newValues = realloc(values, sizeof(*newValues) * newCapacity);

    if (!newOffsets || !newKeys || !newValues) {
        puts("Memory allocation failed."); 
        exit(-1);
    }

    offsets = newOffsets;
    keys = newKeys;
    values = newValues;
    capacity = newCapacity;
}

void addRecord(int key, long offset, double value) {
    pthread_mutex_lock(&lock); // Lock the data structures while updating.

    if (size == capacity) resize(capacity * 2); // Resize arrays when they are full.

    keys[size] = key;
    offsets[size] = offset;
    values[size] = value;
    ++size;

    pthread_mutex_unlock(&lock); // Unlock the data structures after updating.
}

void* initDataStructures(void *arg) {
    srand((unsigned int) time(NULL)); 
    for (int i = 0; i < ((long)arg); ++i) {
        addRecord(rand(), rand(), (double)(rand()) / RAND_MAX); // Add random data to the arrays.
    }

    return NULL; 
}
```
