#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

// Function to generate unique random numbers between min and max (inclusive)
int get_unique_random(int* arr, int size, int min, int max) {
    while (1) {
        int r = rand() % (max - min + 1) + min;  // Generate a new random number
        int i = 0;
        for (; i < size && arr[i] != r; ++i);   // Check if it's unique
        if (i == size) return r;                 // Return the number if it's unique
    }
}

void sort_by_offset(Record* records, long* offsets, int size) {
    for (int i = 0; i < size - 1; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (offsets[i] > offsets[j]) {
                long tmp_offset = offsets[i];
                Record tmp_record = records[i];

                offsets[i] = offsets[j];
                records[i] = records[j];

                offsets[j] = tmp_offset;
                records[j] = tmp_record;
            }
        }
    }
}

void allocate_and_init(long* max_offset, int num_keys, int minVal, int maxVal) {
    if (*max_offset < num_keys || *max_offset == 0 || num_keys == 0) {
        printf("Invalid parameters. Exiting...\n");
        return;
    }

    // Allocate memory for offsets and keys arrays
    long* offsets = malloc(*max_offset * sizeof(long));
    int* keys = malloc(num_keys * sizeof(int));
    Record* records = malloc(num_keys * sizeof(Record));

    // Error checking for memory allocation failure
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    srand((unsigned int)time(NULL));  // Seed the random number generator with current time

    // Initialize offsets and keys arrays
    for (int i = 0; i < *max_offset; ++i) {
        offsets[i] = i + 1;  // Offsets start from 1, assuming they represent positions in a file or something similar. You may need to adjust this based on your actual use case.
    }

    for (int i = 0; i < num_keys; ++i) {
        keys[i] = get_unique_random(keys, i, minVal, maxVal);  // Generate a unique random number and assign it to the key array at index i.
        records[i].value = keys[i];  // Copy the value into the record struct. You may need to adjust this based on your actual use case.
    }

    sort_by_offset(records, offsets, num_keys);  // Sort the records by their corresponding offsets.

    // Free allocated memory when it's no longer needed
    free(offsets);
    free(keys);
    free(records);
}
