int* read_integers(int* size) {
    *size = 0;
    int capacity = 16;
    int* arr = (int*)malloc(capacity * sizeof(int));
    if (arr == NULL) return NULL;  // handle memory allocation failure.

    while (scanf("%d", &arr[(*size)++]) == 1) {
        if (*size >= capacity) {
            capacity *= 2;
            arr = (int*)realloc(arr, capacity * sizeof(int));
            if (arr == NULL) return NULL;  // handle memory allocation failure.
