```python
import hashlib

def md5sum(filename, blocksize=8192):
    '''Compute and return the MD5 checksum of given filename'''

    # Use hashlib.md5() to create an md5 object
    h = hashlib.md5()

    with open(filename, "rb") as f:  # Open file for reading in binary mode
        while True:
            buf = f.read(blocksize)  # Read from the file in chunks to handle large files efficiently

            if not buf:  # If we've reached EOF, break out of loop
                break

            h.update(buf)  # Update the hash with the read chunk

    return h.hexdigest()  # Return hexadecimal representation of digest
