SensorData dequeue();  // function to remove data from the queue
int getQueueSize();  // function to get the current size of the queue
void logConnectionAttempts(char *message);  // function to handle connection attempts logging
/* End of omitted functions */

/* MQTT message callback */
int on_message(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    if (getQueueSize() >= SENSOR_DATA_SIZE){
        logEvent("Sensor data queue is full. Discarding new sensor data.");
        return 1; /* If the queue is full, we discard the new message */
    }

    SensorData data = {0};
    memcpy(&data, message->payload, sizeof(SensorData));
    enqueue(data);
    return 1;
}

void handleMQTTConnection() {
    pthread_mutex_lock(&connectionAttemptMutex);

    if (connectionAttempts > 10 && difftime(time(NULL), lastConnectionAttemptTime) <= 5){
        logEvent("Too many connection attempts. Rejecting further attempts for 30 seconds.");
        sleep(30);  /* Pause new connections for 30 seconds */
    } else {
        connectionAttempts++;
    }

    pthread_mutex_unlock(&connectionAttemptMutex);
}

void logRotationCheck(){
    if (logFileSize > LOG_FILE_SIZE_LIMIT){
        /* Implement your log rotation strategy here */
    }
}

int main(int argc, char* argv[]) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    int rc;

    handleMQTTConnection(); /* Check connection attempts before attempting to connect */

    MQTTClient_create(&client, "localhost", "SensorDataProcessor", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        logEvent("Failed to connect to MQTT broker.");
        exit(-1);
    }

    MQTTClient_subscribe(client, "SensorDataTopic", 0);
    MQTTClient_message *msg = NULL;

    while (1) {
        rc = MQTTClient_receive(client, &topicName, &topicLen, &message, 5000); /* Wait up to 5 seconds for a message */

        if (rc != MQTTCLIENT_SUCCESS){
            logEvent("Disconnected from the MQTT broker.");

            while(1) {
                rc = MQTTClient_connect(client, &conn_opts);

                if (rc == MQTTCLIENT_SUCCESS) {
                    break;  /* Reconnected successfully */
                }

                logEvent("Failed to reconnect to the MQTT broker. Retrying in 5 seconds.");
                sleep(5);
            }

            MQTTClient_subscribe(client, "SensorDataTopic", 0); /* Resubscribe after reconnection */
        } else {
            on_message(NULL, topicName, topicLen, message);
            MQTTClient_freeMessage(&msg);
            MQTTClient_free(topicName);

            logRotationCheck(); /* Check and rotate logs if necessary */
        }
    }

    MQTTClient_disconnect(client, 10000);
    MQTTClient_destroy(&client);

    return rc;
}
