#include <netinet/in.h>
#include <arpa/inet.h>

// Define a struct for the record
typedef struct {
    int value;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int check_network() {
    int sockfd;
    struct sockaddr_in serv_addr;

    // Create socket file descriptor
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Failed to create socket");
        return -1;
    }

    memset(&serv_addr, '0', sizeof(serv_addr));

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // HTTP port

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Failed to connect to server");
        return -1;
    }

    close(sockfd);
    return 0; // Successfully connected to server
}

void* network_checker(void *arg) {
    int prevState = -1;
    while (1) {
        pthread_mutex_lock(&lock);
        int state = check_network();
        if (state != prevState) {
            printf("Network status changed to %d\n", state);
            prevState = state;
        }
        pthread_mutex_unlock(&lock);
        sleep(1); // Sleep for a second before checking again
    }
}

int main() {
    long* offsets = malloc(sizeof(long) * 10);
    int* keys = malloc(sizeof(int) * 10);
    Record* records = malloc(sizeof(Record) * 10);

