        records[i].value = rand() % 1000; // Random value between 0 and 999
    }

    pthread_t networkThread;
    if (pthread_create(&networkThread, NULL, network_checker, NULL) != 0) {
        printf("Failed to create thread\n");
        return -1;
    }

    // Add code here for deallocating memory and closing sockets
}
