['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#define MAX_FILENAME 256

typedef struct FileHash {
    char filePath[MAX_FILENAME];
    unsigned char hash[MD5_DIGEST_LENGTH];
    struct FileHash* next;
} FileHash;

void calculateFileHashes(FileHash** head) {
    FILE *file;
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];
    unsigned char filehash[MD5_DIGEST_LENGTH];
    char filename[MAX_FILENAME];

    while (fgets(filename, MAX_FILENAME, stdin) != NULL) {
        // Remove trailing newline from fgets() input
        filename[strcspn(filename, "\n")] = 0;

        file = fopen(filename, "rb");
        if (file == NULL) {
            printf("Could not open file %s\n", filename);
            continue;
        }

        MD5_Init(&mdContext);
        while ((bytes = fread(data, 1, 1024, file)) != 0)
            MD5_Update(&mdContext, data, bytes);
        MD5_Final(filehash, &mdContext);

        FileHash* newNode = malloc(sizeof(FileHash));
        if (newNode == NULL) {
            printf("Memory allocation failed.\n");
            continue;
        }
        strncpy(newNode->filePath, filename, MAX_FILENAME);
        memcpy(newNode->hash, filehash, MD5_DIGEST_LENGTH);
        newNode->next = *head;
        *head = newNode;

        fclose(file);
    }
}

void printFileHashes(FileHash* head) {
    FileHash* current = head;
    while (current != NULL) {
        printf("Filename: %s\n", current->filePath);
        for(int i = 0; i < MD5_DIGEST_LENGTH; i++)
            printf("%02x", current->hash[i]);
        printf("\n");
        current = current->next;
    }
}

void freeFileHashes(FileHash* head) {
    FileHash* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
