    *float_array = (float *) malloc(sizeof(float) * float_count);
    if (*float_array == NULL) return -1;

    *double_array = (double *) malloc(sizeof(double) * double_count);
    if (*double_array == NULL) { 
        free(*float_array); 
        return -1; 
    }

    *point_array = (point **) malloc(sizeof(point *) * point_count);
