bool establish_mqtt_connection(char* address, char* clientId, int max_concurrent_connections, MQTTClient *client) {
    static int active_connections = 0;

    // Lock the mutex before accessing shared resource
    pthread_mutex_lock(&lock);
    if (active_connections >= max_concurrent_connections) {
        log_event("Max concurrent connections reached.");
        return false;
    }
    ++active_connections;
    pthread_mutex_unlock(&lock); // unlock the mutex

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc = 0;

    if ((rc = MQTTClient_create(client, address, clientId, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        log_event("Failed to create MQTT client.");
        return false;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(*client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        log_event("Failed to connect to MQTT broker.");
        return false;
    }

    // Unlock the mutex and decrement active connections after connection is established
    pthread_mutex_lock(&lock); 
    --active_connections;
    pthread_mutex_unlock(&lock);

    log_event("Successfully connected to MQTT broker.");
    return true;
}

