['Here is a basic example using POSIX threads for thread safety, memoization with an LRU cache to minimize redundant memory allocations, and the C11 random functions for improved random number generation:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdatomic.h>
#define LRU_CACHE_SIZE 1024 // Set according to your requirement

typedef struct {
    int value;
} record;

// Cache for previously allocated structures.
typedef struct node {
    void* data;
    struct node *prev, *next;
} Node;

Node* head = NULL, *tail = NULL;
pthread_mutex_t lock;
atomic_int cache_size = 0;

void* lru_cache(void* args) {
    pthread_mutex_lock(&lock);
    if (head == NULL) {
        Node* newNode = malloc(sizeof(Node));
        newNode->data = args;
        head = newNode;
        tail = newNode;
        ++cache_size;
    } else {
        Node *temp = head;
        while (temp) {
            if (temp->data == args) {
                // Remove the node from its current position.
                temp->prev->next = temp->next;
                break;
            }
            temp = temp->next;
        }
        // Add the recently used node to the front of the list.
        newNode->next = head;
        head->prev = newNode;
        head = newNode;
    }
    pthread_mutex_unlock(&lock);
}

void allocate(long* offsets, int n_offsets, int* keys, int n_keys, record** records, int n_records) {
    srand(time(NULL)); // Initialize random seed.
    long *offset_array = malloc(n_offsets * sizeof(*offset_array));
    if (!offset_array) exit(-1); // Check for allocation failure.
    memset(offset_array, 0, n_offsets*sizeof(*offset_array)); // Initialize array elements to zero.

    int *keys_array = malloc(n_keys * sizeof(*keys_array));
    if (!keys_array) exit(-1); // Check for allocation failure.
    memset(keys_array, 0, n_keys*sizeof(*keys_array)); // Initialize array elements to zero.

    record** records_array = malloc(n_records * sizeof(*records_array));
    if (!records_array) exit(-1); // Check for allocation failure.
    for (int i = 0; i < n_records; ++i) {
        lru_cache(records[i]);
        records_array[i] = malloc(sizeof(**records_array));
        if (!records_array[i]) exit(-1); // Check for allocation failure.

        atomic_int cache_count = 0;
        Node *temp = head;
        while (temp) {
            if (++cache_count > LRU_CACHE_SIZE && temp->data == records[i]) {
                free(temp->data); // Remove the least recently used.
                --cache_size;

                if (head == tail) {
                    head = tail = NULL;
                } else {
                    tail = tail->prev;
                    tail->next = NULL;
                }
            }
            temp = temp->next;
        }

        records_array[i]->value = rand(); // Set random int value for record.
    }
}
```
This implementation should provide a good balance between efficiency, usability, maintainability, and scalability in real-world engineering constraints. However, it does not include optimizations for specific scenarios such as low memory conditions or high concurrency needs. These would be additional trade-offs to consider based on the unique requirements of your application.
']

