use std::env;
use std::fs::{create_dir, remove_file};
use rand::Rng;
use std::sync::Mutex;
use log::{info, error};
use anyhow::Result;
use env_logger::Env;
use std::thread;

#[derive(Debug)]
struct Record {
    value: i32
}

pub fn create_dir_and_initialize() -> Result<()> {
    // Initialize logging
    env_logger::builder().parse_env(Env::default().filter_or("RUST_LOG", "info")).init();

    // Check for existing directory path environment variable
    let dir_path = match env::var("DIR_PATH") {
        Ok(val) => val,
        Err(_) => {
            info![ "No environment variable set for DIR_PATH. Creating new directory."];
            let new_dir_path = format!["./new_directory_{}", rand::thread_rng().gen_range(1..=50));
            create_dir(&new_dir_path)?;
            env::set_var("DIR_PATH", &new_dir_path);
            new_dir_path
        }
    };

    // Get range of random values for each record from environment variable or default to (1, 50)
    let range: (i32, i32) = match env::var("RANGE") {
        Ok(val) => val.split_once('-').map(|(a, b)| (a.parse().unwrap(), b.parse().unwrap())).unwrap_or((1, 50)),
        Err(_) => (1, 50),
    };

    // Create and initialize array of 'record' structures with random values within given range
    let mut records = Mutex::new(vec![Record { value: 0 }; 20]);
    thread::scope(|s| {
        for record in &mut *records.lock().unwrap() {
            s.spawn(move || {
                *record = Record { value: rand::thread_rng().gen_range(range.0..=range.1) };
            });
        }
    });

    // Clean up and free memory
    remove_file(&format![ "{}/temp", dir_path])?;
    Ok(())
}
```

