```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int PRODUCT_ID;
    float PRICE;
    int STOCK_QUANTITY;
} PRODUCT_T;

void* readFloatArray(size_t *size) {
    size_t capacity = 1024; // Initial capacity
    float *array = malloc(capacity * sizeof(*array));
    if (!array) exit(EXIT_FAILURE);

    *size = 0;
    while (scanf("%f", &array[*size]) == 1) {
        (*size)++;
        // Double capacity when array is full
        if (*size == capacity) {
            capacity *= 2;
            float *temp = realloc(array, capacity * sizeof(*array));
            if (!temp) exit(EXIT_FAILURE);
            array = temp;
        }
    }

    return array;
}

void* createProducts(size_t size) {
    PRODUCT_T *products = malloc(sizeof(*products) * size);
    if (!products) exit(EXIT_FAILURE);

    for (size_t i = 0; i < size; ++i) {
        // Assuming inputs are valid and in the correct order.
        scanf("%d %f %d", &products[i].PRODUCT_ID, &products[i].PRICE, &products[i].STOCK_QUANTITY);

        if (products[i].PRODUCT_ID < 0 || products[i].PRICE < 0.0f || products[i].STOCK_QUANTITY < 0) {
            free(products);
            exit(EXIT_FAILURE);
        }
    }

    return products;
}

int main() {
