Record* initializeRecords(int numRecords, int minKey, int maxKey) {
    srand((unsigned int)time(NULL));

    // Allocate memory for the arrays and records
    int *keys = malloc(numRecords * sizeof(*keys));
    long *offsets = calloc(numRecords, sizeof(*offsets)); 
