    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = sighandler;
    sigaction(SIGINT, &action, NULL);

    int count = 0;
    double sum = 0.0;
    int max_size = 1024;
    int *numbers = malloc(max_size * sizeof(int));
    if (numbers == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
