        sum += numbers[count];
        ++count;
        if (count >= max_size) {
            max_size *= 2;
            int *temp = realloc(numbers, max_size * sizeof(int));
            if (temp == NULL) {
                perror("realloc");
                free(numbers);
                exit(EXIT_FAILURE);
