#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>

typedef struct FileHash {
    char* file_path;
    unsigned char md5[MD5_DIGEST_LENGTH];
} FileHash;

struct Node{
   FileHash hash;
   struct Node *next;
};

// Helper function to calculate MD5 of a file.
void calc_md5(const char *filename, unsigned char *hash) {
    // Open the file
    FILE *file = fopen (filename, "rb");
    if (!file) return; 

    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    MD5_Init(&mdContext);
    while ((bytes = fread(data, 1, 1024, file)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }

    // Get the hash and clean up
    MD5_Final(hash, &mdContext);
    fclose (file);
}

int main() {
   char file_path[1024];
   struct Node *head = NULL;

   while(fgets(file_path, sizeof file_path, stdin)) {
       // Remove trailing newline character.
       file_path[strcspn(file_path, "\n")] = 0;

       unsigned char md5[MD5_DIGEST_LENGTH];
       calc_md5(file_path, md5);

       struct Node *newNode = malloc(sizeof(struct Node));
       newNode->hash.file_path = strdup(file_path);
       memcpy(newNode->hash.md5, md5, MD5_DIGEST_LENGTH);
       newNode->next = head;
       head = newNode;
   }

   // Print the list content
   for (struct Node *p = head; p != NULL; p = p->next) {
      printf("File: %s, MD5: ", p->hash.file_path);
      for(int i = 0; i < MD5_DIGEST_LENGTH; ++i)
          printf("%02x", p->hash.md5[i]);
      printf("\n");
   }

   // Free the list.
   while (head != NULL) {
       struct Node *temp = head;
       head = head->next;
       free(temp->hash.file_path);
       free(temp);
   }
}
```
