// Function to handle dynamic sizing of the array
void resize_array(int size, Config& config) {
    std::lock_guard<std::mutex> lock(mtx); // Ensuring thread safety for shared resources

    if (size > config.arraySize) {
        arr.reserve(size);  // Reserving memory to prevent reallocation in the loop below.

        for (int i = config.arraySize; i < size; ++i)
            arr.push_back(elemPool.construct());
    } else if (size < config.arraySize) {
        for (int i = size; i < config.arraySize; ++i) 
            elemPool.destroy(arr[i]);

        arr.resize(size);
