void sort_array(std::vector<ElementType*>& arr) {
    std::lock_guard<std::mutex> lock(mtx); // Ensuring thread safety for shared resources

    std::sort(arr.begin(), arr.end(), [](const ElementType* a, const ElementType* b){ 
        return a->offset < b->offset; 
