void allocateMemory(size_t size) {
    pthread_mutex_lock(&lock);

    srand((unsigned int) time(NULL)); // initialize the random number generator
    offsets = malloc(size * sizeof(long));
    assert(offsets != NULL && "Memory allocation failed"); 

    keys = calloc(size, sizeof(int));
    assert(keys != NULL && "Memory allocation failed");

    records = malloc(size * sizeof(Record));
    assert(records != NULL && "Memory allocation failed");

    for (int i = 0; i < size; ++i) {
        offsets[i] = rand(); // initialize the 'long' values with random numbers
        keys[i] = rand();  // initialize the 'int' values with random numbers
        records[i].value = rand(); // initialize the record struct fields with random numbers
    }

    pthread_mutex_unlock(&lock);
}

void freeMemory() {
    pthread_mutex_lock(&lock);

    if(offsets) {
        free(offsets); 
        offsets = NULL;
    }

    if(keys){
        free(keys);
        keys = NULL;
    }

    if(records){
        free(records);
        records = NULL;
    }

    pthread_mutex_unlock(&lock);
}
