typedef struct {
    int value;
} Record;

void allocate_and_init(long max_offset, int num_keys, int min_value, int max_value) {
    if (max_offset < num_keys || !max_offset || !num_keys) {
        printf("Invalid parameters\n");
        return;
    }

    long* offsets = malloc(sizeof(long) * max_offset);
    int* keys = calloc(num_keys, sizeof(int));
    Record* records = malloc(sizeof(Record) * num_keys);

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    srand(time(NULL));

    int* used_values = calloc(max_value - min_value + 1, sizeof(int));
    if (!used_values) {
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    for (long i = 0; i < max_offset; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    for (int i = 0; i < num_keys; i++) {
        int value;

        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while(used_values[value - min_value]);

        used_values[value - min_value] = 1;
        keys[i] = value;
        records[i].value = value;
    }

    free(used_values);
}
