#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record_t;

typedef struct {
    long *offsets;
    int *keys;
    record_t **records;
    size_t size;
} dataset_t;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // For thread-safe allocation
const int RANDOM_RANGE = 100;  // Range for random values

dataset_t *allocate_datasets(int num_datasets, size_t dataset_size) {
    pthread_mutex_lock(&mutex);  // Lock to ensure thread-safety

    srand(time(NULL));  // Seed the random number generator

    dataset_t *datasets = calloc(num_datasets, sizeof(dataset_t));
    if (datasets == NULL) {
        printf("Memory allocation failed!\n");
        pthread_mutex_unlock(&mutex);  // Unlock even in case of failure
        return NULL;
    }

    for (int i = 0; i < num_datasets; ++i) {
        datasets[i].size = dataset_size;

        datasets[i].offsets = malloc(dataset_size * sizeof(long));
        if (datasets[i].offsets == NULL) {
            printf("Memory allocation failed!\n");
            free_datasets(datasets, i);  // Free already allocated memory
            pthread_mutex_unlock(&mutex);  
            return NULL;
        }

        datasets[i].keys = malloc(dataset_size * sizeof(int));
        if (datasets[i].keys == NULL) {
            printf("Memory allocation failed!\n");
            free_datasets(datasets, i);  // Free already allocated memory
            pthread_mutex_unlock(&mutex);  
            return NULL;
        }

        datasets[i].records = malloc(dataset_size * sizeof(record_t*));
        if (datasets[i].records == NULL) {
            printf("Memory allocation failed!\n");
            free_datasets(datasets, i);  // Free already allocated memory
            pthread_mutex_unlock(&mutex);  
            return NULL;
        }

        for (size_t j = 0; j < dataset_size; ++j) {
            datasets[i].records[j] = malloc(sizeof(record_t));
            if (datasets[i].records[j] == NULL) {
                printf("Memory allocation failed!\n");
                free_datasets(datasets, i);  // Free already allocated memory
                pthread_mutex_unlock(&mutex);  
                return NULL;
            }

            datasets[i].records[j]->value = rand() % RANDOM_RANGE;  // Random initialization
        }
    }

    pthread_mutex_unlock(&mutex);  // Unlock after successful allocation

    return datasets;
}

void free_datasets(dataset_t *datasets, int num_datasets) {
    for (int i = 0; i < num_datasets; ++i) {
        for (size_t j = 0; j < datasets[i].size; ++j) {
            free(datasets[i].records[j]);  // Free each record individually to prevent fragmentation
        }

        free(datasets[i].offsets);
        free(datasets[i].keys);
        free(datasets[i].records);
    }

    free(datasets);  // Free the entire array after all individual frees to prevent fragmentation
}
```

This code allocates memory for multiple datasets with specified size and initializes each record within a dataset with a random value in a given range. It handles allocation failures by reporting an error message and freeing already allocated memory before returning NULL. The function `free_datasets` frees all the memory when it is no longer needed, preventing memory leaks or corruption.
']

