#include <random>

// Define a record structure.
struct Record {
    int value;
};

class RecordManager {
private:
    std::vector<std::atomic<long>> offsets;
    std::vector<int> keys;
    std::vector<Record> records;
    std::mutex mutex_;
    std::condition_variable cv_;
    int minVal;
public:
    RecordManager(const std::vector<std::atomic<long>>& offsets, 
                  const std::vector<int>& keys, 
                  const std::vector<Record>& records,
                  int minVal) :
        offsets(offsets), keys(keys), records(records), minVal(minVal) { }

    // Thread-safe initialization function.
    void initializeRecords() {
        std::lock_guard<std::mutex> lock(mutex_);
        for (size_t i = 0; i < records.size(); ++i) {
            records[i].value = minVal + keys[i];
        }
    }

    // Thread-safe function to handle concurrent access and updates to the records.
    void manageRecords(int threadId, int recordIndex, int newValue) {
        std::unique_lock<std::mutex> lock(mutex_);

        cv_.wait(lock, [this, &recordIndex]{ return records[recordIndex].is_lock_free(); });

        // Update the record with a new value.
        records[recordIndex].value = newValue;

        std::cout << "Thread " << threadId 
                  << " updated record " << recordIndex 
                  << " to " << newValue << std::endl;
    }

    // Thread-safe function to handle memory deallocation when no longer needed.
    ~RecordManager() {
        for (auto& record : records) {
            std::atomic_thread_fence(std::memory_order_acquire);
            record.~Record();
        }
    }
};
```
