class MemoryPool {
public:
    static constexpr std::size_t chunkSize = 1024;
    using Chunk = char[chunkSize];

    MemoryPool() : mCurrentChunk(nullptr) {}

    ~MemoryPool() {
        for (auto& chunk : mAllocatedChunks) {
            delete[] chunk;
        }
    }

    void* allocate(std::size_t size) {
        if (!mCurrentChunk || mOffset + size > chunkSize) {
            allocateNewBlock();
        }

        void* result = &mCurrentChunk[mOffset];
        mOffset += size;
        return result;
    }

private:
    std::vector<Chunk*> mAllocatedChunks;
    Chunk* mCurrentChunk;
    std::size_t mOffset = 0;

    void allocateNewBlock() {
        mCurrentChunk = new Chunk();
        mAllocatedChunks.push_back(mCurrentChunk);
        mOffset = 0;
    }
};

