```java
import java.math.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.eclipse.paho.client.mqttv3.*;

public class MQTTManager {
    private static final int DEFAULT_MAX_CONCURRENT_CONNECTIONS = 5;
    private static final int DEFAULT_MAX_SENSOR_DATA_SIZE = 1000;
    private static final long RATE_LIMIT_PERIOD = 60000; // 1 minute in milliseconds

    private final AtomicInteger connectionsCounter = new AtomicInteger(0);
    private int maxConcurrentConnections;
    private int maxSensorDataSize;
    private Set<String> activeMQTTConnections = Collections.newSetFromMap(new ConcurrentHashMap<>());
    private Map<String, List<String>> sensorDataStore = new ConcurrentHashMap<>(); // Store data as a list of strings.
    private long lastRateLimitCheck = 0;
    private AtomicInteger rateLimiterCounter = new AtomicInteger(0);

    public MQTTManager() {
        this(DEFAULT_MAX_CONCURRENT_CONNECTIONS, DEFAULT_MAX_SENSOR_DATA_SIZE);
    }

    public MQTTManager(int maxConcurrentConnections, int maxSensorDataSize) {
        this.maxConcurrentConnections = maxConcurrentConnections;
        this.maxSensorDataSize = maxSensorDataSize;
    }

    private synchronized void establishMQTTConnection(String brokerUrl, String clientId){
        if (connectionsCounter.get() < maxConcurrentConnections && !activeMQTTConnections.contains(clientId)) {
            if (!rateLimit()) { // If rate limiting is applied reject the connection attempt
                try {
                    MqttClient mqttClient = new MqttClient(brokerUrl, clientId);
                    activeMQTTConnections.add(clientId);
                    connectionsCounter.incrementAndGet();
                    // Further code to handle connection setup and data processing 
                } catch (Exception e) {
                    e.printStackTrace();
                }
            } else {
                System.out.println("Rate limit exceeded. Try again later.");
            }
        } else {
            System.out.println("Max connections reached or client is already connected");
        }
    }

    private boolean rateLimit() {
        long currentTime = System.currentTimeMillis();

        if (lastRateLimitCheck + RATE_LIMIT_PERIOD < currentTime) { // Reset counter every minute
            lastRateLimitCheck = currentTime;
            rateLimiterCounter.set(0);
        }

        if (rateLimiterCounter.incrementAndGet() > 100) {
            return true;
        }

        return false;
    }

    private String md5Hashing(String input) throws NoSuchAlgorithmException {
        MessageDigest messageDigest = MessageDigest.getInstance("MD5");
        byte[] digestedBytes = messageDigest.digest(input.getBytes());

        BigInteger bigInt = new BigInteger(1, digestedBytes);
        return bigInt.toString(16);
    }

    private synchronized void storeSensorData(String clientId, String sensorData) {
        if (!sensorDataStore.containsKey(clientId)) {
            sensorDataStore.put(clientId, new LinkedList<>());
        }

        List<String> data = sensorDataStore.get(clientId);
        if (data.size() >= maxSensorDataSize) { // Remove oldest entry to make space for new one
            data.remove(0);
        }

        data.add(sensorData);
    }
}
```
Please note that this example assumes use of Paho MQTT client library and Java 8 or above. Further improvements on error handling, logging, thread safety etc could be made based on your specific requirements. Also, you would need to integrate with an actual MQTT broker for real usage.
']

