#include <stdatomic.h>
#include <jemalloc/jemalloc.h>  // Using jemalloc as custom allocator for demonstration purposes

// Define a structure to hold our data and configuration
typedef struct Config {
  size_t recordSize;
  int numRecords;
  int initValue;
} Config;

// Function to create an array of records using provided config
void* createRecord(Config* config) {
  void* ptr = je_malloc(config->recordSize * config->numRecords);

  // Using loop to set value of each record's fields
  for (int i = 0; i < config->numRecords; ++i) {
    ((int*)ptr)[i] = config->initValue;
  }

  return ptr;
}

// Global array to cache created records
void* recordCache[100]; // Assuming max 100 different configurations
atomic_uint cacheIndex = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* createRecordThreadSafe(Config* config) {
  pthread_mutex_lock(&mutex);

  // Check if this configuration is already cached
  for (size_t i = 0; i < cacheIndex; ++i) {
    if (memcmp(config, recordCache[i], sizeof(Config)) == 0) {
      pthread_mutex_unlock(&mutex);
      return recordCache[i]; // Return cached data
    }
  }

  // If not in cache, create new and add to cache
  void* newRecord = createRecord(config);
  if (cacheIndex < 100) { // If cache is full, replace the oldest entry
    je_free(recordCache[cacheIndex % 100]);
    recordCache[cacheIndex % 100] = newRecord;
    ++cacheIndex;
  } else {
    je_free(newRecord);
    ++cacheIndex;
  }

  pthread_mutex_unlock(&mutex);
  return recordCache[(cacheIndex-1) % 100]; // Return cached data
}
```

