['Below is an example of how you might solve this problem in C:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double value;
} data_point;

void load_data(char *filename, double **doubles, int **ints, data_point **data_points, size_t *size) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Failed to open file %s\n", filename);
        return;
    }

    double tmpDouble;
    int tmpInt;
    while (fscanf(file, "%lf,%d", &tmpDouble, &tmpInt) == 2) {
        (*size)++;

        *doubles = realloc(*doubles, sizeof(double)*(*size));
        if (*doubles == NULL){
            printf("Failed to allocate memory\n");
            return;
        }
        (*doubles)[(*size)-1] = tmpDouble;

        *ints = realloc(*ints, sizeof(int)*(*size));
        if (*ints == NULL){
            printf("Failed to allocate memory\n");
            return;
        }
        (*ints)[(*size)-1] = tmpInt;

        *data_points = realloc(*data_points, sizeof(data_point)*(*size));
        if (*data_points == NULL){
            printf("Failed to allocate memory\n");
            return;
        }
        (*data_points)[(*size)-1].value = tmpDouble;
    }

    fclose(file);
}
```
This function opens the specified file and reads in data line by line. It dynamically allocates more memory as needed to store the new values. If there is an error allocating memory, it prints an error message and returns early. After successfully reading all lines from the file, it closes the file. This approach minimizes memory usage and performance overhead when dealing with large datasets.
