['Here is a simple C code snippet for the problem mentioned. Please note that error handling part is omitted due to complexity, but you can add your own error handling mechanism with `errno` or by returning appropriate error codes.

```c
#include <stdio.h>
#include <stdlib.h>
#define CACHE_SIZE 1024
typedef struct {
    int value;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    int size;
    int maxSize;
    int countRecords;
    int cache[CACHE_SIZE][2];  // [key, index in records]
} ArrayManager;

void initArrayManager(ArrayManager *am, int initialSize) {
    am->offsets = (long *)malloc(sizeof(long)*initialSize);
    am->keys = (int *)malloc(sizeof(int)*initialSize);
    am->records = (Record **)malloc(sizeof(Record*)*initialSize);
    am->size = 0;
    am->maxSize = initialSize;
    am->countRecords = 0;
}
void addToArrayManager(ArrayManager *am, long offset, int key, Record *record) {
    if (am->size >= am->maxSize) {
        // reallocate memory
        am->offsets = (long *)realloc(am->offsets, sizeof(long)*am->maxSize*2);
        am->keys = (int *)realloc(am->keys, sizeof(int)*am->maxSize*2);
        am->records = (Record **)realloc(am->records, sizeof(Record*)*am->maxSize*2);
        am->maxSize *= 2;
    }
    // add to cache if not full and not in it already
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (am->cache[i][0] == key || am->cache[i][1] == 0) {
            am->cache[i][0] = key;
            am->cache[i][1] = am->size;
            break;
        }
    }
    am->offsets[am->size] = offset;
    am->keys[am->size] = key;
    am->records[am->size] = record;
    am->countRecords++;
    am->size++;
}
Record *getFromArrayManager(ArrayManager *am, int key) {
    // check cache first
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (am->cache[i][0] == key && am->cache[i][1] != 0) {
            return am->records[am->cache[i][1]];
        }
    }
    // search main array
    for (int i = 0; i < am->size; ++i) {
        if (am->keys[i] == key) {
            // update cache
            for (int j = 0; j < CACHE_SIZE; ++j) {
                if (am->cache[j][1] == 0) {
                    am->cache[j][0] = key;
                    am->cache[j][1] = i;
                    break;
                }
            }
            return am->records[i];
        }
    }
    // not found in cache or main array
    return NULL;
}
void destroyArrayManager(ArrayManager *am) {
    free(am->offsets);
    free(am->keys);
    for (int i = 0; i < am->size; ++i) {
        free(am->records[i]);
    }
    free(am->records);
}
``` 
Please note that you need to manage the cache and size according to your specific use case. The above code is a very basic one and may not be ideal for all scenarios, but it gives an idea of how this could work. Please adapt it as per your needs. Also please make sure you have error checking mechanism in place (like errno or return codes) to ensure the function can handle failures gracefully.
']

