        *arr = realloc(*arr, sizeof **arr * (*count + 1)); // dynamic allocation
        if (!*arr) { printf("Memory allocation failed.\n"); pthread_mutex_unlock(&lock); return -1;} 

        Record *r = malloc(sizeof *r); // dynamic allocation
        if (!r){ printf("Record memory allocation failed.\n"); fclose(fp); pthread_mutex_unlock(&lock); return -1; }

        r->value = val; // initialize record fields
        r->dvalue = dval;
        (*arr)[*count - 1] = r; // add the record to array
    }

    fclose(fp);
    pthread_mutex_unlock(&lock);

    return 0;
}
