    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int *keys = (int*) calloc(m, sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    Record* records = (Record*) malloc(sizeof(Record) * n);
    if (!records) {
        free(offsets);
        free(keys);
