void generateRandomValues(std::vector<int>& dataset, int n) {
    std::uniform_int_distribution<> dis(0, 1 << 30);
    for (int i = 0; i < n; ++i) {
        dataset.push_back(dis(gen));
    }
}

// Function to persist dataset states to disk after each modification.
void persistDataset(const std::string& filename, const std::vector<int>& dataset) {
    std::ofstream outFile(filename);
    for (int value : dataset) {
        outFile << value << ' ';
    }
}

// Function to handle adding a new dataset.
void addDataset(const std::string& filename, int n) {
    std::lock_guard<std::mutex> lock(mtx); // Acquire the mutex to avoid data races

    std::vector<int> newDataset;
    generateRandomValues(newDataset, n);

    persistDataset(filename, newDataset);  // Persist dataset state after modification.

    datasets.push_back(n);  // Add the new dataset to our collection
    ++datasetMetadata[filename];  // Increase the count of active datasets for this filename
}

// Function to handle removing a dataset.
void removeDataset(const std::string& filename) {
    std::lock_guard<std::mutex> lock(mtx); // Acquire the mutex to avoid data races

    if (datasetMetadata[filename] > 0) {
        --datasetMetadata[filename];  // Decrease the count of active datasets for this filename.

        auto it = std::find(datasets.begin(), datasets.end(), n);
        if (it != datasets.end()) {
            datasets.erase(it);  // Remove the dataset from our collection
        }
    }
}
