// Custom memory pool implementation
typedef struct MemoryPool {
    Record *records;
    pthread_mutex_t lock;
} MemoryPool;

void initMemoryPool(MemoryPool* pool, int size) {
    pool->records = initializeArrays(size);
    pthread_mutex_init(&pool->lock, NULL);  // Initialize mutex for thread safety
}

// Function to free memory when done with records
void destroyMemoryPool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);  
    free(pool->records);  
}

// Thread-safe function to access and modify the record data in the pool
