import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.TimeUnit;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import io.netty.channel.*;

public class ChannelHandler extends SimpleChannelInboundHandler<String> {
    private final LoadingCache<String, String> loadingCache = CacheBuilder.newBuilder()
        .maximumSize(10_000) // Max 10K keys
        .expireAfterWrite(1, TimeUnit.MINUTES) // Expires after 1 minute
        .build(new CacheLoader<String, String>() {
            public String load(String key) throws Exception {
                return computeMD5(key);
            }
    });

    private static final MessageDigest digest;

    static {
        try {
            digest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, String msg) throws Exception {
        if (!msg.isEmpty() && !loadingCache.getIfPresent(msg) == null){
             loadingCache.put(msg, computeMD5(msg));
        }else{
            System.out.println("Message is empty or has been processed before");
        }
    }

    private String computeMD5(String msg) {
        byte[] hash = digest.digest(msg.getBytes(StandardCharsets.UTF_8));
        return bytesToHex(hash); 
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (int i = 0; i < hash.length; ++i) {
            String hex = Integer.toHexString(0xff & hash[i]);
            if(hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
