void readFiles(int n, char *filenames[], long offsets[], int keys[], record_t **records[]) {
    srand(time(0)); // seed the random number generator

    for (int i = 0; i < n; ++i) {
        FILE *file = fopen(filenames[i], "r");

        if (!file) {
            perror("Failed to open file.");
            exit(EXIT_FAILURE);
        }

        // get the metadata of the file
        struct stat *metadata = malloc(sizeof(struct stat));
        fstat(fileno(file), metadata);
        (*records)[i]->metadata = metadata;

        fseek(file, offsets[i], SEEK_SET); // seek to the desired offset

        char *buffer = malloc(1024); // allocate a buffer for reading strings from the file

        if (fgets(buffer, 1024, file) != NULL) { // read a line from the file into the buffer
            (*records)[i]->string = malloc((strlen(buffer) + 1) * sizeof(char)); // allocate memory for the string and copy it
            strcpy((*records)[i]->string, buffer);
        } else {
            (*records)[i]->string = NULL;
        }

        keys[i] = rand() % 100 + 1; // generate a random key within the desired range
        (*records)[i]->value = keys[i]; // set the int field of each record to this key

        free(buffer); // deallocate the buffer
        fclose(file); // close the file
