pthread_mutex_t lock;
unsigned long total_memory = 0;
FILE* logfile = NULL;

void init_log() {
    if (logfile == NULL) {
        logfile = fopen("log.txt", "a");
    }
}

int allocate_memory(size_t size) {
    pthread_mutex_lock(&lock);
    unsigned long new_total = total_memory + size;

    if (new_total > MAX_MEMORY) {
        fprintf(logfile, "Failed to allocate memory. Exceeded maximum limit.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    total_memory = new_total;
    pthread_mutex_unlock(&lock);
    return 0;
}

void deallocate_memory(size_t size) {
    pthread_mutex_lock(&lock);
    if (total_memory < size) {
        fprintf(logfile, "Failed to deallocate memory. Attempting to free more than allocated.\n");
    } else {
        total_memory -= size;
    }

    pthread_mutex_unlock(&lock);
}

void init_records() {
    if (offsets != NULL || keys != NULL || records != NULL) {
        fprintf(logfile, "Memory already initialized.\n");
