const { Readable } = require('stream');
const { exec } = require('child_process');
let isPaused = false;

// Simulate a real-time sensor stream with Readable stream
class SensorStream extends Readable {
  _read() {
    if (!isPaused) {
      this.push(process.hrtime()); // Push data into the stream
    } else {
      // Do nothing when paused, effectively pausing the stream
    }
  }
}

const generateAnalyticsReports = (requestParams) => {
