  let isFetchingExternalData = false;

  sensorStream.on('data', (chunk) => {
    console.log(`Chunk: ${chunk}`); // Process data in real-time

    if (!isFetchingExternalData && chunk % requestParams.pagination.limit === 0) {
      isFetchingExternalData = true;

      exec('shell command here', (error, stdout, stderr) => { // Fetch external data
        if (error) {
          console.error(`Error fetching external data: ${error}`);
          return;
        }

        isFetchingExternalData = false;
      });
