typedef struct {
    int value;
} Record;

struct FileHash {
    char *filePath;
    unsigned char md5[MD5_DIGEST_LENGTH];
    struct FileHash *next;
};

pthread_mutex_t totalCountLock = PTHREAD_MUTEX_INITIALIZER;
size_t totalCount = 0;

void* initRecords(void* arg) {
    srand((unsigned int) time(NULL)); // Seed the random number generator

    long *offsets = (long*) malloc(1024 * sizeof(long));  // Allocate memory for offset array
    assert(offsets != NULL);  // Check if allocation was successful

    int *keys = (int*) calloc(1024, sizeof(int));   // Allocate and zero-initialize memory for keys array
    assert(keys != NULL);

    Record* records = (Record*) malloc(1024 * sizeof(Record));  // Allocate memory for record array
    assert(records != NULL);

    size_t localCount = 0;
    for(int i = 0; i < 1024; ++i) {
        records[i].value = rand();   // Initialize each record with a random value
        ++localCount;
    }

    pthread_mutex_lock(&totalCountLock);  // Lock the total count to update it safely
    totalCount += localCount;
    pthread_mutex_unlock(&totalCountLock);

    free(offsets);   // Free allocated memory
    free(keys);
    free(records);

    return NULL;
}

void* calculateMD5ForFile(void* arg) {
    char *filePath = (char*) arg;
    unsigned char md5[MD5_DIGEST_LENGTH];
    FILE *file = fopen(filePath, "rb");  // Open the file in binary mode
    assert(file != NULL);   // Check if file was opened successfully

    MD5_CTX context;
    unsigned char buffer[8192];
    size_t bytesRead;

    MD5_Init(&context);  // Initialize the MD5 context

    while((bytesRead = fread(buffer, 1, sizeof(buffer), file)) != 0) {   // Read from the file in chunks
        MD5_Update(&context, buffer, bytesRead);  // Update the MD5 hash with each chunk
    }

    MD5_Final(md5, &context);   // Finalize the MD5 hash

    fclose(file);   // Close the file

    struct FileHash *newFileHash = malloc(sizeof(struct FileHash));  // Allocate memory for a new FileHash structure
    assert(newFileHash != NULL);

    newFileHash->filePath = strdup(filePath);   // Duplicate the file path
    memcpy(newFileHash->md5, md5, MD5_DIGEST_LENGTH);  // Copy the hash into the structure
    newFileHash->next = NULL;   // The next field will be set by the caller

    return newFileHash;   // Return a pointer to the dynamically allocated memory
