} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static const size_t INITIAL_SIZE = 1024;
static size_t totalSize = 0, maxSize;
static long* offsets;
static int* keys;
static double* values;
static Record** records;
static void (*logFunction)(const char*) = NULL;

void logMessage(const char* message) {
    if (logFunction != NULL) {
        logFunction(message);
    }
}

int initArrays() {
    pthread_mutex_lock(&mutex);

    if (totalSize > 0) {
        // Arrays have already been initialized, so we can return early.
        pthread_mutex_unlock(&mutex);
        return 1;
    }

    offsets = malloc(sizeof(long) * INITIAL_SIZE);
    if (offsets == NULL) {
        logMessage("Failed to allocate memory for 'offsets' array.");
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    keys = malloc(sizeof(int) * INITIAL_SIZE);
    if (keys == NULL) {
        logMessage("Failed to allocate memory for 'keys' array.");
        free(offsets);
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    values = malloc(sizeof(double) * INITIAL_SIZE);
    if (values == NULL) {
        logMessage("Failed to allocate memory for 'values' array.");
        free(offsets);
        free(keys);
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    records = malloc(sizeof(Record*) * INITIAL_SIZE);
    if (records == NULL) {
        logMessage("Failed to allocate memory for 'records' array.");
        free(offsets);
        free(keys);
        free(values);
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    totalSize = INITIAL_SIZE;

    // Initialize arrays.
    memset(offsets, 0, sizeof(long) * INITIAL_SIZE);
    memset(keys, 0, sizeof(int) * INITIAL_SIZE);
    memset(values, 0, sizeof(double) * INITIAL_SIZE);

    pthread_mutex_unlock(&mutex);
    return 1;
}

void resizeArrays() {
    pthread_mutex_lock(&mutex);

    size_t newSize = totalSize * 2;
    if (newSize > maxSize) {
        logMessage("Failed to resize arrays: Maximum memory limit reached.");
        pthread_mutex_unlock(&mutex);
        return;
    }

    long* newOffsets = realloc(offsets, sizeof(long) * newSize);
    if (newOffsets == NULL) {
        logMessage("Failed to resize 'offsets' array.");
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        offsets = newOffsets;
    }

    int* newKeys = realloc(keys, sizeof(int) * newSize);
    if (newKeys == NULL) {
        logMessage("Failed to resize 'keys' array.");
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        keys = newKeys;
    }

    double* newValues = realloc(values, sizeof(double) * newSize);
    if (newValues == NULL) {
        logMessage("Failed to resize 'values' array.");
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        values = newValues;
    }

    Record** newRecords = realloc(records, sizeof(Record*) * newSize);
    if (newRecords == NULL) {
        logMessage("Failed to resize 'records' array.");
        pthread_mutex_unlock(&mutex);
        return;
    } else {
        records = newRecords;
    }

    totalSize = newSize;

    pthread_mutex_unlock(&mutex);
}

int initRecordArrays(size_t count) {
    if (count > totalSize) {
        // Resize the arrays to accommodate more records.
        size_t targetSize = totalSize * 2;
        while (targetSize < count && targetSize <= maxSize) {
            resizeArrays();
            targetSize *= 2;
        }

        if (totalSize == count || count > maxSize) {
            logMessage("Failed to initialize record arrays: Maximum memory limit reached.");
            return 0;
        }
    }

    for (size_t i = 0; i < count; ++i) {
        records[i] = malloc(sizeof(Record));

        if (records[i] == NULL) {
            logMessage("Failed to allocate memory for record.");

            // Free all previously allocated records.
            for (--i; i > 0; --i) {
                free(records[i]);
            }
            free(records[0]);
            return 0;
        }

        // Initialize the record.
        memset(records[i], 0, sizeof(Record));
    }

    return 1;
}

void setLogFunction(void (*logFunc)(const char*)) {
    pthread_mutex_lock(&mutex);
    logFunction = logFunc;
    pthread_mutex_unlock(&mutex);
}
```
