#include <time.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

Node* createLinkedList(int numNodes, int maxLimit) {
    srand(time(0)); // Seeding the random number generator.
    if (numNodes * sizeof(Node) > maxLimit) {
        printf("Memory limit exceeded. Adjusting node count to fit within limit.\n");
        numNodes = maxLimit / sizeof(Node);
    }

    Node* head = NULL;
    Node* current = NULL;

    for (int i = 0; i < numNodes; i++) {
        Node* newNode = malloc(sizeof(Node)); // Allocating memory.
        if (!newNode) {
            printf("Memory allocation failed. Exiting...\n");
            exit(1);
        }

        newNode->value = rand() % 100; // Initializing the node's value to a random number between 0 and 99.
        newNode->next = NULL;

        if (!head) {
            head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    return head;
}
```

