        // Initialize arrays with random values
        (*offsets)[i] = rand() % LONG_MAX; 
        (*keys)[i] = rand() % INT_MAX; 

        // Allocate memory for each record
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            // Free previously allocated memory on failure
            while (--i >= 0) free((*records)[i]); 

            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }

        // Initialize record value with random value
        (*records)[i]->value = rand() % INT_MAX; 
    }

    return 0;
}
