['Here is a basic implementation in C using pthreads and libcurl. This solution assumes that each sensorData record corresponds to one server connection which may not be suitable for all scenarios but it provides a basic outline of how this can be done. Please note, this code requires libcurl and pthread libraries. 

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    int value;
    float fvalue;
    char str[1024]; // assuming max string length is 1023 chars
} sensorData;

void* transfer_data(void *url) {
    CURL *curl;
    FILE *fp;
    CURLcode res;
    curl = curl_easy_init();
    if (curl) {
        fp = fopen("/dev/null", "wb"); // assuming log file is /dev/null
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        res = curl_easy_perform(curl);

        /* Check for errors */ 
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            fprintf(stdout, "Response code: %ld\n", response_code); // assuming log file is stdout
        }

        /* always cleanup */ 
        curl_easy_cleanup(curl);
        fclose(fp);
    }

    return NULL;
}

void generate_random_data(sensorData *sd, int length) {
    srand(time(NULL));
    for (int i = 0; i < length; ++i) {
        sd[i].value = rand() % 1000 + 1; // assuming range of integer values is 1 to 1000
        sd[i].fvalue = ((float)rand()/(float)(RAND_MAX)) * 5.0; // assuming range of float values is 0.0 to 5.0

        int strlen = rand() % 128 + 1; // assuming max string length is 128 chars
        for (int j = 0; j < strlen; ++j) {
            sd[i].str[j] = 'a' + (rand() % ('z'-'a')); // assuming strings contain lower case alphabets only
        }
        sd[i].str[strlen] = '\0';
    }
}

void free_all(sensorData *sd, int length) {
    if (sd) {
        free(sd);
    }
}

int main() {
    const char* urls[] = {"http://server1.com", "http://server2.com"}; // assuming we are connecting to 2 servers
    int num_urls = sizeof(urls) / sizeof(char *);

    pthread_t threads[num_urls];
    for (int i = 0; i < num_urls; ++i) {
        if (pthread_create(&threads[i], NULL, transfer_data, (void*) urls[i])) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < num_urls; ++i) {
        pthread_join(threads[i], NULL);
    }

    int length = 1000; // assuming we have 1000 sensor data records
    sensorData *sd = malloc(length * sizeof(sensorData));
    if (!sd) {
        fprintf(stderr, "Error allocating memory for sensor data\n");
        return 1;
    }

    generate_random_data(sd, length);

    // Here you can perform any additional operations on the generated data.

    free_all(sd, length);
}
```

