#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include "jni.h"
#include "record.h"
#include "db_interface.h"

typedef struct {
    pthread_mutex_t mutex;
    long *offsets;
    int *keys;
    record_t *records;
} context_t;

void* connection_routine(void* args) {
    JNIEnv *env;
    JavaVMInitArgs vm_args;
    JavaVMOption options[1];
    jclass cls;
    jmethodID mid;
    jint res;
    jobject channel;

    /* Initialize JVM */
    if (JNI_CreateJavaVM(&env, &env, &vm_args) < 0 || !env) {
        log_error("Failed to initialize Java Virtual Machine");
        return NULL;
    }

    options[0].optionString = "-Djava.class.path=.";
    vm_args.version = JNI_VERSION_1_6;
    vm_args.nOptions = 1;
    vm_args.options = options;
    vm_args.ignoreUnrecognized = FALSE;

    /* Establish connection */
    cls = (*env)->FindClass(env, "Channel");
    if (cls == NULL) {
        log_error("Failed to find class Channel");
        return NULL;
    }

    mid = (*env)->GetStaticMethodID(env, cls, "establishConnection", "()I");
    if (mid == NULL) {
        log_error("Failed to get method id for establishConnection");
        return NULL;
    }

    res = (*env)->CallStaticIntMethod(env, cls, mid);
    if (res < 0) {
        log_error("Failed to establish connection: %d", res);
        return NULL;
    }

    /* Handle connection state changes */
    channel = (*env)->NewGlobalRef(env, (jobject) args[1]);

    /* Clean up JVM and connection */
    (*env)->DeleteLocalRef(env, cls);
    (*env)->DeleteWeakGlobalRef(env, channel);
    return NULL;
}

int setup_context(context_t* ctx, size_t size) {
    pthread_mutexattr_t attr;
    int status = 0;

    /* Initialize mutex attribute */
    if (pthread_mutexattr_init(&attr)) {
        log_error("Failed to initialize mutex attribute");
        return -1;
    }

    /* Set mutex type as recursive */
    if ((status = pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE))) {
        log_error("Failed to set mutex attribute");
        return status;
    }

    /* Initialize mutex */
    if ((status = pthread_mutex_init(&ctx->mutex, &attr))) {
        log_error("Failed to initialize mutex");
        return status;
    }

    ctx->offsets = calloc(size, sizeof(long));
    ctx->keys = malloc(size * sizeof(int));
    ctx->records = malloc(size * sizeof(record_t));

    if (!ctx->offsets || !ctx->keys || !ctx->records) {
        log_error("Memory allocation failed");
        free(ctx->offsets);
        free(ctx->keys);
        free(ctx->records);
        return -1;
    }

    /* Initialize random number generator */
    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        ctx->keys[i] = rand() % 100 + 1;
        ctx->records[i].value = ctx->keys[i];
    }

    return 0;
}

void cleanup_context(context_t* ctx) {
    pthread_mutex_destroy(&ctx->mutex);
    free(ctx->offsets);
    free(ctx->keys);
    for (size_t i = 0; i < size; ++i) {
        db_interface_insert(ctx->records[i].key, ctx->records[i].value);
    }
}
```
