} Point;

typedef struct arrayHolder {
    double *doubleArray;
    char *charArray;
    Point **pointArray;
    size_t currentSize;
    size_t maxSize;
    pthread_mutex_t lock;
} ArrayHolder;

// Initialization of the array holder. 
void initArrayHolder(ArrayHolder *ah, size_t initialSize) {
    ah->doubleArray = malloc(initialSize * sizeof(double));
    ah->charArray = malloc(initialSize * sizeof(char));
    ah->pointArray = malloc(initialSize * sizeof(Point*));
    for (int i = 0; i < initialSize; ++i) {
        ah->pointArray[i] = malloc(sizeof(Point));
    }

    if (!ah->doubleArray || !ah->charArray || !ah->pointArray){
       // error handling
    } 

    ah->currentSize = 0;
    ah->maxSize = initialSize;
    pthread_mutex_init(&(ah->lock), NULL);
}

// Dynamically resize the arrays.
void resizeArrays(ArrayHolder *ah, size_t newMaxSize) {
    ah->doubleArray = realloc(ah->doubleArray, newMaxSize * sizeof(double));
    ah->charArray = realloc(ah->charArray, newMaxSize * sizeof(char));

    // Ensure existing point structs are not lost.
    ah->pointArray = realloc(ah->pointArray, newMaxSize * sizeof(Point*));
    for (int i = ah->maxSize; i < newMaxSize; ++i) {
        ah->pointArray[i] = malloc(sizeof(Point));
    }

    if (!ah->doubleArray || !ah->charArray || !ah->pointArray){
       // error handling
    } 

    ah->maxSize = newMaxSize;
}

// Add a data point to the arrays.
void addDataPoint(ArrayHolder *ah, double dblValue, char charValue, int xCoord, int yCoord) {
    pthread_mutex_lock(&(ah->lock));

    if (ah->currentSize >= ah->maxSize){
        resizeArrays(ah, ah->maxSize * 2);
    }

    ah->doubleArray[ah->currentSize] = dblValue;
    ah->charArray[ah->currentSize] = charValue;
    ah->pointArray[ah->currentSize]->x = xCoord;
    ah->pointArray[ah->currentSize]->y = yCoord;

    ++(ah->currentSize);

    pthread_mutex_unlock(&(ah->lock));
}
``` 

You can see that the double and char arrays are resized using `realloc`. However, since a pointer to 'Point' is stored in the array, it needs to be handled separately as 'realloc' does not initialize newly added memory. The mutex lock ensures threads don't access the same memory space concurrently which could lead to data corruption or race conditions. 

