typedef struct {
    int *id, count;
} UnionFind;

UnionFind UF_init(int size) {
    UnionFind uf;
    uf.count = size;
    uf.id = (int*)malloc(sizeof(int)*uf.count);

    for (int i = 0; i < uf.count; ++i)
        uf.id[i] = i;

    return uf;
}

void UF_union(UnionFind *uf, int p, int q) {
    int pid = find(uf, p), qid = find(uf, q);

    if (pid != qid) {
        for (int i = 0; i < uf->count; ++i)
            if (uf->id[i] == pid) uf->id[i] = qid;

        --uf->count;
    }
