}

clock_t start, end;
double cpu_time_used;
int check_disjoint_pairs(UnionFind *uf, int arr[], int size) {
    start = clock();
    int disjointPairs = 0;

    for (int i=0; i<size-1; ++i){
        if (UF_find(uf, arr[i]) != UF_find(uf, arr[i+1])) {
            disjointPairs++;
        }
