    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);  // Unlock the mutex before returning
        return NULL;  // Returning NULL indicates failure
    }

    for (int i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
