#include <time.h>

typedef struct Record {
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

void* allocateMemory(size_t size, void** pointer) {
    pthread_mutex_lock(&lock);

    *pointer = malloc(size);
    if (*pointer == NULL) {
        exit(EXIT_FAILURE); // error handling mechanism
    }

    pthread_mutex_unlock(&lock);
    return *pointer;
}

void initializeRecordArray(long* offsets, int size1, Record** records, int size2) {
    srand(time(NULL)); // seed the random number generator

    allocateMemory(sizeof(long)*size1, (void**)&offsets);
    for (int i = 0; i < size1; i++) {
        offsets[i] = rand() % INT_MAX; 
    }

    allocateMemory(sizeof(Record)*size2, (void**)&records);
    for (int i = 0; i < size2; i++) {
        records[i]->value = offsets[rand()%size1]; 
    }
}
```

This program initializes an array of `long` values and another array of 'Record' structures. Then for each record, it assigns a value from the `offsets` array. The random number generator is seeded with the current time to ensure different results on each run. 

The memory allocation function is wrapped in a mutex lock which ensures that only one thread can access this critical section at a time. This prevents race conditions and allows for safe concurrent access. 

