    // Calculate the size of each element in bytes.
    size_t offset_size = sizeof(long);
    size_t key_size = sizeof(int);

    // Calculate total required memory.
    size_t total_memory = (offset_size + key_size + sizeof(record)) * num_elements;

    if (total_memory > MAX_MEMORY) {
        return -1;  // Return error code if not enough memory.
