        if (new_records == NULL) {
            pthread_mutex_unlock(&lock);
            fprintf(stderr, "Failed to allocate memory for records\n");
            return;
        }

        records = new_records;
        records_capacity = new_capacity;
    }

    record_t *new_record = malloc(sizeof(*new_record));
    if (new_record == NULL) {
        pthread_mutex_unlock(&lock);
        fprintf(stderr, "Failed to allocate memory for new record\n");
        return;
    }

    new_record->offset = offset;
    new_record->key = key;
    new_record->fpoint = fpoint;
    new_record->character = character;

    records[records_size++] = new_record;

    pthread_mutex_unlock(&lock);
}
```

This function allocates and initializes a new record. If the current array is full, it doubles its capacity using `realloc` to avoid frequent reallocations. 

