typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Add required members for your structure here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheEntry {
    void *item;
    size_t itemSize;
    time_t timestamp;
    struct CacheEntry* next;
} CacheEntry;

CacheEntry* cacheHead = NULL;
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile = NULL;
time_t seed = 0; // Set by user
size_t maxCacheSize = 1024 * 1024 * 50; // 50 MB

void logEvent(const char* event) {
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", event);
        fflush(logFile);
    }
}

void addToCache(void *item, size_t itemSize) {
    pthread_mutex_lock(&cacheMutex);

    CacheEntry* newEntry = malloc(sizeof(CacheEntry));
    assert(newEntry != NULL);

    newEntry->item = item;
    newEntry->itemSize = itemSize;
    newEntry->timestamp = time(NULL);
    newEntry->next = cacheHead;

    cacheHead = newEntry;

    // Remove oldest entry if cache is full
    CacheEntry *current = cacheHead, *prev = NULL;
    size_t totalSize = 0;
    while (current != NULL) {
        totalSize += current->itemSize;
        prev = current;
        current = current->next;

        if (totalSize > maxCacheSize && prev != cacheHead) {
            free(prev->next->item);
            CacheEntry* temp = prev->next;
            prev->next = prev->next->next;
            free(temp);
        }
    }

    pthread_mutex_unlock(&cacheMutex);
}

void *allocateAndInitializeMemory(size_t N) {
    void* cachedItem = NULL;

    // Check cache first
    pthread_mutex_lock(&cacheMutex);
    CacheEntry* current = cacheHead;
    while (current != NULL && cachedItem == NULL) {
        if (current->itemSize >= N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            // Use this item and remove it from the cache
            cachedItem = current->item;

            if (current == cacheHead) {
                cacheHead = current->next;
            } else {
                CacheEntry* prev = cacheHead;
                while (prev != NULL && prev->next != current) {
                    prev = prev->next;
                }

                if (prev != NULL) {
                    prev->next = current->next;
                }
            }

            free(current);
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&cacheMutex);

    // If not in cache, allocate new memory
    if (cachedItem == NULL) {
        cachedItem = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (cachedItem != NULL) {
            logEvent("Memory allocated successfully");

            // Initialize memory here...
        } else {
            logEvent("Failed to allocate memory");
        }
    }

    return cachedItem;
}

void freeAllAllocatedMemory() {
    pthread_mutex_lock(&cacheMutex);

    while (cacheHead != NULL) {
        CacheEntry* temp = cacheHead;
        cacheHead = cacheHead->next;

        free(temp->item);
        free(temp);
    }

    pthread_mutex_unlock(&cacheMutex);
}
```

