void* handle_database(void *arg) {
    pthread_mutex_lock(&lock);
    PGresult *res = PQexec(conn, "SELECT * FROM table");
    if (PQresultStatus(res) != PGRES_TUPLES_OK) {
        printf("Error in database query\n%s", PQerrorMessage(conn));
        pthread_mutex_unlock(&lock);
        return NULL; 
    }

    int rows = PQntuples(res);
    array_nodes = calloc(rows, sizeof(Node*));
    for (int i = 0; i < rows; i++) {
        Node *node = malloc(sizeof(Node));
        node->value = atoi(PQgetvalue(res, i, 0)); // assuming int values in database
        array_nodes[i] = node;
    }

    PQclear(res);
    pthread_mutex_unlock(&lock);
    return NULL;
}

size_t handle_response(void *ptr, size_t size, size_t nmemb, void *stream) {
