    return size * nmemb;
}

void dynamic_init(const char* dbname, const char* user, const char* password, 
                  const char* hostaddr, const char* port) {

    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("\n mutex init failed\n");
        return;
    }

    curl = curl_easy_init();
    conn = PQsetdbLogin(hostaddr, port, NULL, NULL, dbname, user, password);

    if (PQstatus(conn) != CONNECTION_OK) {
        printf("Connection to database failed: %s", PQerrorMessage(conn));
        return;
    }

    pthread_t thread;
    pthread_create(&thread, NULL, handle_database, NULL);

    curl_easy_setopt(curl, CURLOPT_URL, "http://example.com");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, handle_response);
    curl_easy_perform(curl);

    pthread_join(thread, NULL);

    PQfinish(conn);
    curl_easy_cleanup(curl);
}
