```java
public int countDisjointPairs(int[] arr) {
    Map<Integer, Integer> parent = new HashMap<>(); // Union-Find structure

    for (int num : arr) {
        if (!parent.containsKey(num)) {
            parent.put(num, num); // initially, each element is its own parent
        }

        int rootNum = findRoot(parent, num);

        for (int neighbor : new int[]{num - 1, num + 1}) { // check neighbors only if they exist in the array
            if (parent.containsKey(neighbor)) {
                int rootNeighbor = findRoot(parent, neighbor);

                if (rootNum != rootNeighbor) { // merge two disjoint sets if roots are different
                    parent.put(rootNeighbor, rootNum);
                }
            }
        }
    }

    int count = 0;

    for (int key : parent.keySet()) {
        if (parent.get(key) == key) { // count the number of disjoint sets
            ++count;
        }
    }

    return count;
}

private int findRoot(Map<Integer, Integer> parent, int i) {
    if (parent.get(i) != i) {
        parent.put(i, findRoot(parent, parent.get(i))); // path compression for efficiency
    }

    return parent.get(i);
}
```
