typedef struct {
    int key;
    long offset;
    double value;
} record;

record* records = NULL;
int *keys, n_records = 0, max_records;
long *offsets;
double *values;
pthread_mutex_t lock;

void init(int num_records) {
    srand(time(NULL));  // seed random number generator
    if (num_records <= 0) return;
    max_records = num_records;

    keys = malloc(sizeof(int)*max_records);
    offsets = malloc(sizeof(long)*max_records);
    values = malloc(sizeof(double)*max_records);
    records = malloc(sizeof(record)*max_records);

    if (!keys || !offsets || !values || !records) {
        // handle error: allocation failed
        free(keys); free(offsets); free(values); free(records);
        return;
    }
}

void add_record() {
    pthread_mutex_lock(&lock);  // lock to ensure thread-safe access

    if (n_records >= max_records) {
        // handle error: array full
        pthread_mutex_unlock(&lock);
        return;
    }

