typedef struct {
    int UE_ID;
    int RNTI;
    int CQI_REPORT;
} UE_CTXT_T;

void sort(int *array, size_t len) {
    for (size_t i = 0; i < len - 1; ++i) {
        for (size_t j = i + 1; j < len; ++j) {
            if (array[i] > array[j]) {
                int temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }
}

int findMax(const int *array, size_t len) {
    return array[len - 1];
}

UE_CTXT_T* createContextList(size_t n) {
    UE_CTXT_T *list = malloc(n * sizeof(*list));
    if (list == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; ++i) {
        list[i].UE_ID = rand();
        list[i].RNTI = rand();
        list[i].CQI_REPORT = rand() % 16;
    }

    return list;
}

void deleteContextList(UE_CTXT_T *list) {
    free(list);
}

int main() {
    size_t n = 10;
    int *array = malloc(n * sizeof(*array));
    if (array == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    sem_t semaphore;
    if (sem_init(&semaphore, 0, 1) != 0) {
        perror("Semaphore initialization failed");
        free(array);
        exit(EXIT_FAILURE);
    }

    // populate array here

    sort(array, n);
    int max = findMax(array, n);
    printf("Largest integer: %d\n", max);

    UE_CTXT_T *list = createContextList(10);
    deleteContextList(list);

    if (sem_destroy(&semaphore) != 0) {
        perror("Semaphore destruction failed");
        free(array);
        exit(EXIT_FAILURE);
    }

    free(array);
    return 0;
}
