Here is the Python code block for calculating MD5 hash of multiple files using concurrent processing and rate limiting.

```python
import os
import threading
import hashlib
from queue import Queue
from functools import partial
from time import sleep

def read_and_update_hash(path, hasher):
    with open(path, 'rb') as f:
        for chunk in iter(partial(f.read, 4096), b''):
            hasher.update(chunk)
    return hasher

def process_file(q, semaphore, rate_limit):
    sleep(rate_limit)
    path = q.get()

    with semaphore:
        hasher = hashlib.md5()
        read_and_update_hash(path, hasher)

    print(f'{os.path.basename(path)}: {hasher.hexdigest()}')
    q.task_done()

def calculate_MD5(file_list, num_threads=4, rate_limit=0.1):
    q = Queue()
    semaphore = threading.Semaphore(num_threads)

    for i in range(len(file_list)):
        t = threading.Thread(target=process_file, args=(q, semaphore, rate_limit * i))
        t.daemon = True
        t.start()

    for path in file_list:
        q.put(path)

    q.join()
```

In the Python function `calculate_MD5`, you can provide a list of files to calculate MD5 hashes for and it will process them concurrently with rate limiting. The number of threads and rate limit are optional parameters.
