typedef struct {
    int value;
    char* string;
} record;

void* read_records(FILE *file, size_t bufSize, long *offsets, int **keys) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    char buffer[bufSize + 1];
    offsets = malloc(sizeof(*offsets));
    if (offsets == NULL) {
        perror("malloc() failed");
        exit(EXIT_FAILURE);
    }
    keys = malloc(sizeof(*keys));
    if (keys == NULL) {
        perror("malloc() failed");
        free(offsets);
        exit(EXIT_FAILURE);
    }
    record **records = malloc(sizeof(*records));
    if (records == NULL) {
        perror("malloc() failed");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    long offset = 0;
    int key = 0;
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        pthread_mutex_lock(&mutex);

        offsets[key] = offset;
        keys[key] = key;

        record *rec = malloc(sizeof(*rec));
        if (rec == NULL) {
            perror("malloc() failed");
            free(offsets);
            free(keys);
            for (int i = 0; i < key; ++i)
                free(records[i]);
            fclose(file);
            exit(EXIT_FAILURE);
        }

        rec->value = key;
        size_t len = strlen(buffer);
        char *str = malloc(len + 1);
        if (str == NULL) {
            perror("malloc() failed");
            free(offsets);
            free(keys);
            for (int i = 0; i <= key; ++i)
                free(records[i]);
            fclose(file);
            exit(EXIT_FAILURE);
        }

        strcpy(str, buffer);
        rec->string = str;
        records[key] = rec;

        ++key;
        offset += len + 1;

        pthread_mutex_unlock(&mutex);
    }

    fclose(file);

    return (void*)records;
}
```
This code uses a mutex to ensure thread safety during memory allocation and file reading. It also properly deallocates all resources in case of errors or successful completion, preventing memory leaks. 

