['Writing the entire implementation of a complex task like this from scratch is outside the capabilities of text-based AI models. However, I can provide you with a high level pseudocode that outlines the main tasks involved in your request:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sqlite3.h>

typedef struct {
    int key;
    double value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety
const long MEMORY_LIMIT = 1024 * 1024 * 1024;   // Total memory limit in bytes (1GB)
long usedMemory = 0;  // Track currently used memory
int recordCount = 0;  // Number of records to generate
Record* records = NULL;  // Array of Records
sqlite3* dbHandle = NULL;  // Database handle
const char* dbName = "database.db";  // Name of the database file
char* errorMessage = NULL;  // Error message buffer

// Function to allocate memory and initialize record array
int initRecords(int count, int minValue, int maxValue) {
    if (count < 1 || minValue >= maxValue) {
        printf("Invalid parameters\n");
        return -1;
    }

    // Calculate the memory required for records and validate with limit
    long reqMemory = count * sizeof(Record);
    if (usedMemory + reqMemory > MEMORY_LIMIT) {
        printf("Insufficient memory\n");
        return -1;
    }

    // Allocate memory for records array
    Record* newRecords = malloc(reqMemory);
    if (!newRecords) {
        printf("Failed to allocate memory\n");
        return -1;
    }

    // Initialize the record values with random keys and doubles within given range
    srand(time(NULL));  // Seed for random number generation
    for (int i = 0; i < count; i++) {
        newRecords[i].key = minValue + rand() % (maxValue - minValue + 1);
        newRecords[i].value = ((double)rand() / RAND_MAX) * maxValue;  // Random double value within range
    }

    // Replace existing records array with the new one
    free(records);
    records = newRecords;
    recordCount = count;
    usedMemory += reqMemory;

    return 0;
}

// Function to safely clean up resources and store in database if possible
void cleanup() {
    pthread_mutex_lock(&lock);

    // Store records in database if available
    if (dbHandle) {
        // SQL statement to insert records into a table
        const char* sql = "INSERT INTO Records(key, value) VALUES(?, ?);";

        // Begin transaction and execute the insert statement for each record
        sqlite3_exec(dbHandle, "BEGIN TRANSACTION", NULL, NULL, &errorMessage);
        for (int i = 0; i < recordCount; i++) {
            sqlite3_stmt* stmt;
            sqlite3_prepare_v2(dbHandle, sql, -1, &stmt, NULL);

            // Bind the key and value to the statement parameters
            sqlite3_bind_int(stmt, 1, records[i].key);
            sqlite3_bind_double(stmt, 2, records[i].value);

            // Execute the insert statement
            sqlite3_step(stmt);
            sqlite3_finalize(stmt);
        }

        // Commit transaction and handle errors
        if (sqlite3_exec(dbHandle, "COMMIT", NULL, NULL, &errorMessage) != SQLITE_OK) {
            printf("Failed to commit records: %s\n", errorMessage);
        }
    }

    // Free allocated memory and cleanup resources
    free(records);
    records = NULL;
    recordCount = 0;
    usedMemory -= reqMemory;

    pthread_mutex_unlock(&lock);
}
``` 

