    MQTTClient client;
    int active_connections;
    pthread_mutex_t connection_count_mutex;
} mqtt_broker;

void mqtt_init(mqtt_broker *b, const char* broker_address) {
    MQTTClient_create(&b->client, broker_address, "sensor_data_manager", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    b->active_connections = 0;
    pthread_mutex_init(&b->connection_count_mutex, NULL);
}
```

```c
void mqtt_connect(mqtt_broker *b) {
    pthread_mutex_lock(&b->connection_count_mutex);
    ++b->active_connections;
    if (b->active_connections <= 5) {
        MQTTClient_connect(b->client, NULL);
    } else {
        --b->active_connections; // rollback the connection count
        pthread_mutex_unlock(&b->connection_count_mutex);
        printf("Error: too many active MQTT connections. Please retry later.\n");
    }
}
```

```c
void mqtt_disconnect(mqtt_broker *b) {
    pthread_mutex_lock(&b->connection_count_mutex);
    --b->active_connections;
    MQTTClient_disconnect(b->client, 10000); // disconnect with a timeout of 10 seconds
    pthread_mutex_unlock(&b->connection_count_mutex);
}
```

