void calcFileSHA256(const char* filename, unsigned char hash[SHA256_DIGEST_LENGTH]) {
    FILE* file = fopen(filename, "rb");

    // Error handling.
    if (file == NULL) {
        printf("Failed to open the file.\n");
        return;
