['Here's a C program that fulfills the requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct node {
    char* data;
    int priority;
    struct node* next;
} node;

node* createNode(int priority, const char* data) {
    node* newNode = malloc(sizeof(node));
    if (newNode == NULL) {
        printf("Failed to allocate memory for a node\n");
        return NULL;
    }
    newNode->priority = priority;
    size_t len = strlen(data);
    newNode->data = malloc((len + 1)*sizeof(char));
    if (newNode->data == NULL) {
        printf("Failed to allocate memory for data\n");
        free(newNode);
        return NULL;
    }
    strcpy(newNode->data, data);
    newNode->next = NULL;
    return newNode;
}

void initialize_nodes(node** head, int num_nodes, int min_priority, int max_priority, size_t max_data_length) {
    srand((unsigned int)time(NULL)); 
    node* tail = NULL;
    for (int i = 0; i < num_nodes; ++i) {
        char data[max_data_length + 1];
        memset(data, 'A' + rand() % 26, max_data_length);
        data[max_data_length] = '\0';  

        int priority = min_priority + (rand() % (max_priority - min_priority + 1));
        node* newNode = createNode(priority, data);
        if (newNode == NULL) {
            printf("Failed to initialize a node\n");
            return;  
        }

        if (*head == NULL) {
            *head = newNode; 
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode; 
        }
    }
}
```
