        FILE *file = fopen(files[i], "rb");
        if (!file) {
            perror("Error opening file");
            continue;
        }

        const int bufSize = 32768; // Read in 32kb chunks
        unsigned char *buffer = malloc(bufSize);

        while(!feof(file)) {
            size_t bytesRead = fread(buffer, 1, bufSize, file);
            SHA256_Update(&sha256, buffer, bytesRead);
        }

        free(buffer);
        fclose(file);

        SHA256_Final(hash, &sha256);

        FileHash *newNode = malloc(sizeof(FileHash));
        newNode->filePath = strdup(files[i]);
        memcpy(newNode->hash, hash, SHA256_DIGEST_LENGTH);
        newNode->next = NULL;

        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
