public:
    DynamicArray(int minValue, int maxValue, size_t offsetThreshold) 
        : minValue_(minValue), maxValue_(maxValue), offsetThreshold_(offsetThreshold) {}
    ~DynamicArray() = default; // RAII for memory deallocation

    void resizeIfNeeded() {
        std::lock_guard<std::mutex> lock(resizeMutex_); 
        if (values_.size() >= offsetThreshold_) {
            values_.reserve(values_.capacity() * 2); // Doubling the capacity of vector
        }
    }

    void addValueWithUniqueOffset(int value, size_t offset) {
        std::lock_guard<std::mutex> lock(addMutex_); 
        if (offsets_.find(offset) == offsets_.end()) { // Checking for unique offset
            resizeIfNeeded();
            values_.push_back({value, offset}); 
            offsets_.insert(offset); 
        } else {
            std::cout << "Offset is not unique. Skipping value.\n";
        }
    }

    void sortValuesByOffset() {
        std::lock_guard<std::mutex> lock(sortMutex_); 
        std::sort(values_.begin(), values_.end(), [](const auto& a, const auto& b) { return a.second < b.second; });
    }

    int getValueAtOffset(size_t offset) {
        std::lock_guard<std::mutex> lock(getMutex_); 
        auto it = std::lower_bound(values_.begin(), values_.end(), offset, [](const auto& a, const size_t val){ return a.second < val; });
        if (it != values_.end() && it->second == offset) { // Found the value at offset
            return it->first;
        } else {
            std::cout << "Offset not found. Returning -1.\n";
            return -1;
        }
    }

private:
