    std::unordered_set<size_t> offsets_; // Set to store unique offsets
    int minValue_, maxValue_; // Value range
    size_t offsetThreshold_; // Threshold for dynamic resizing

    std::mutex resizeMutex_, addMutex_, sortMutex_, getMutex_; // For thread safety
};
