void* allocate_and_initialize(size_t size, long range1, double range2) {
    assert(range1 > 0 && range2 > 0);

    long *offsets = malloc(sizeof(*offsets) * size);
    if (!offsets) return NULL;

    int *keys = malloc(sizeof(*keys) * size);
    if (!keys) {
        free(offsets);
        return NULL;
    }

    double *values = malloc(sizeof(*values) * size);
    if (!values) {
        free(offsets);
        free(keys);
        return NULL;
    }

    record_t *records = malloc(sizeof(*records) * size);
    if (!records) {
        free(offsets);
        free(keys);
        free(values);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % range1;
        keys[i] = rand();
        values[i] = ((double)rand() / RAND_MAX) * range2;  // random double between [0, range2)

        records[i].key = keys[i];
        records[i].value = values[i];
    }

    pthread_mutex_lock(&mtx);

    free(offsets);
    free(keys);
    free(values);
    free(records);  // this line only frees the last allocated memory block

    pthread_mutex_unlock(&mtx);

    return NULL;
}
