#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct PRODUCT_T {
    int PRODUCT_ID;
    float PRICE;
    int STOCK_QUANTITY;
} PRODUCT_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *largestNumber(void *args) {
    float maxNum = 0.0f;
    int i, n;
    scanf("%d", &n);
    if (n < 1 || errno == ERANGE) {
        printf("Invalid product count.\n");
        return NULL;
    }

    float *arr = malloc(sizeof(float) * n);
    if (!arr) {
        perror("Memory allocation failed.");
        return NULL;
    }

    for (i = 0; i < n; i++) {
        if (scanf("%f", &arr[i]) != 1 || errno == ERANGE) {
            printf("Invalid input at index %d.\n", i);
            continue;
        }

        pthread_mutex_lock(&lock);
        maxNum = arr[i] > maxNum ? arr[i] : maxNum;
        pthread_mutex_unlock(&lock);
    }

    printf("Largest number: %f\n", maxNum);
    free(arr);
    return NULL;
}

PRODUCT_T *initProducts(int n) {
    PRODUCT_T *products = malloc(sizeof(PRODUCT_T) * n);

    if (!products) {
        perror("Memory allocation failed.");
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        products[i].PRODUCT_ID = rand() % 100; // Change this to fetch actual data from external source.
        products[i].PRICE = rand() % 100 + 0.99f; // Replace with actual price from source.
        products[i].STOCK_QUANTITY = 0; // Replace with actual stock quantity.
    }

    return products;
}

int main(int argc, char **argv) {
    if (argc != 2 || atoi(argv[1]) < 1) {
        printf("Usage: %s <product_count>\n", argv[0]);
        return -1;
    }

    pthread_t threadId;

    if (pthread_create(&threadId, NULL, &largestNumber, (void *)atoi(argv[1])) != 0) {
        perror("Thread creation failed.");
        return -2;
    }

    if (pthread_join(threadId, NULL) != 0) {
        perror("Error joining thread.");
        return -3;
    }

    PRODUCT_T *products = initProducts(atoi(argv[1]));

    // If products is null then there was an error during initialization, so we do not need to free it.
    if (products) {
        free(products);
    }

    pthread_mutex_destroy(&lock);

    return 0;
}
