```C++
#include <stdlib.h>
#include <time.h>
#include <algorithm>
#include <vector>
#include <thread>
#include <mutex>
#include <random>

class CustomMemoryPool {
private:
    char* pool;
    size_t capacity;
    std::vector<size_t> offsets;
    std::mutex mtx;
public:
    CustomMemoryPool(size_t _capacity) : capacity(_capacity), pool((char*)malloc(capacity)) { }
    ~CustomMemoryPool() { free(pool); }
    void* allocate(size_t size) {
        std::lock_guard<std::mutex> lock(mtx);
        if (offsets.empty()) return nullptr; // No space available in pool
        size_t offset = offsets[0];
        offsets.erase(offsets.begin());
        return pool + offset;
    }
    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mtx);
        size_t offset = (char*)ptr - pool;
        offsets.push_back(offset);
        std::sort(offsets.begin(), offsets.end()); // Keep the offsets sorted
    }
};

class DynamicArray {
private:
    CustomMemoryPool* memoryPool;
    size_t* data;
    size_t size, capacity, threshold;
public:
    DynamicArray(size_t _threshold) : threshold(_threshold), capacity(0), size(0), memoryPool(new CustomMemoryPool(1024)) { }
    ~DynamicArray() { delete memoryPool; }
    void push_back(int value) {
        if (size >= capacity) resize();
        data[size++] = value;
    }
    size_t& operator[](size_t index) { return data[index]; }
    void sort() { std::sort(data, data + size); }
    bool binarySearch(int target) { return std::binary_search(data, data + size, target); }
private:
    void resize() {
        if (capacity == 0) capacity = 1; // Initial allocation
        else capacity = static_cast<size_t>(capacity * threshold); // Resize based on a given threshold
        int* newData = reinterpret_cast<int*>(memoryPool->allocate(capacity * sizeof(int)));
        std::memcpy(newData, data, size * sizeof(int)); // Copy old data to new memory block
        if (data) memoryPool->deallocate(data); // Free the old memory block
        data = newData;
    }
};

class RandomValueGenerator {
private:
    std::mt19937 gen;
public:
    RandomValueGenerator() : gen(std::random_device{}()) { }
    int generate(int min, int max) { return std::uniform_int_distribution<int>{min, max}(gen); }
};
```
