#include <stdatomic.h> // Requires GCC 4.9+
#include <stdlib.h>

typedef struct Record {
    int int_value;
    long offset;
    double value;
} Record;

// Thread-safe counter for the number of elements in each array/structure
atomic_size_t count = 0;

// Mutex to ensure atomicity when changing the size of arrays/structures
pthread_mutex_t mut = PTHREAD_MUTEX_INITIALIZER;

void* initialize(int capacity) {
    // Dynamically allocate memory for each array
    long* offsets = malloc(sizeof(*offsets) * capacity);
    int* keys = calloc(capacity, sizeof(*keys)); // Initialized to zero
    double* values = malloc(sizeof(*values) * capacity);

    Record* records = malloc(sizeof(*records) * capacity);

    for (int i = 0; i < capacity; ++i) {
        pthread_mutex_lock(&mut); // Ensure atomicity when changing the shared count variable

        if (count == capacity) {
            // If arrays are full, resize them with a new capacity of twice their current size
            int new_capacity = capacity * 2;

            offsets = realloc(offsets, sizeof(*offsets) * new_capacity);
            keys = realloc(keys, sizeof(*keys) * new_capacity);
            values = realloc(values, sizeof(*values) * new_capacity);
            records = realloc(records, sizeof(*records) * new_capacity);

            capacity = new_capacity; // Update the current capacity
        }

        // Initialize each record with a random value within a given range (here: 0-100)
        records[count].int_value = rand() % 100;
        ++count;

        pthread_mutex_unlock(&mut);
    }

    return NULL; // This function doesn't really need to return anything
}
```
