```c
#include <stdlib.h>
#include <time.h>

// Define a record structure
typedef struct {
    long offset;
    int key;
    double value;
} Record;

void init_arrays(Record **records, size_t n) {
    srand(time(NULL));  // Seed the random number generator

    for (size_t i = 0; i < n; i++) {
        (*records)[i].offset = rand() % 10000;  // Initialize offset to a random value between 0 and 9999
        (*records)[i].key = rand() % 5000;  // Initialize key to a random value between 0 and 4999

        // Generate a random double in the range -100.0 <= value < 100.0
        (*records)[i].value = ((double)rand() / RAND_MAX * (100.0 + 100.0)) - 100.0;
    }
}

// Function to sort the records based on their key values in ascending order
int compare(const void *a, const void *b) {
    Record *recordA = (Record *)a;
    Record *recordB = (Record *)b;

    return recordA->key - recordB->key;  // Compare the keys of two records
}

int main() {
    size_t n = 10000;  // The total number of records to allocate memory for and initialize

    Record *records = malloc(n * sizeof(Record));  // Allocate memory for the records
    if (records == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    init_arrays(&records, n);  // Initialize the arrays

    qsort(records, n, sizeof(Record), compare);  // Sort the records based on their key values in ascending order

    free(records);  // Free the allocated memory to prevent memory leaks

    return 0;
}
```

