use std::process::{Command, Stdio};
use std::time::Instant;
use memory_profiler::get_resident_set_size;
use SyncLazy as slog;
use rustc_driver::catch_with_exit_code;

fn compile_rust() -> Result<(), Box<dyn std::error::Error>> {
    let start = Instant::now();
    let resident_set_size_before = get_resident_set_size();

    let output = Command::new("rustc")
        .arg("your_file.rs")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;

    match slog::output(move || {
        let status = output.wait_with_output()?;

        if !status.success() {
            Err(Box::new(std::io::Error::last_os_error()))
        } else {
            Ok(())
        }
    }) {
        Ok(_) => {}
        Err(e) => printlnerror: {e}, // replace with your logging hooks
    };

    let elapsed = start.elapsed().as_secs();
    let resident_set_size_after = get_resident_set_size();

    printlncompilation time: {elapsed}s, before: {resident_set_size_before}, after: {resident_set_size_after}; // replace with your logging hooks

    Ok(())
}
```

