import hashlib

def calculate_md5(filepath, blocksize=8192):
    md5 = hashlib.md5()

    with open(filepath,'rb') as f: 
        while True:
            data = f.read(blocksize)

            if not data:
                break

            md5.update(data)

    return md5.hexdigest()
