    dataset *ds = (dataset *) arg;
    srand((unsigned int) time(NULL));

    for(int i = 0; i < ds->length; ++i) {
        // Initialize offsets sequentially
        ds->offsets[i] = i;

        // Generate unique keys
        ds->keys[i] = i + 1;

        // Allocate memory for record
        ds->records[i] = (record*)malloc(sizeof(record));
        assert(ds->records[i]);

        // Generate unique string based on key and store in text field of the record
        generate_string(ds->records[i]->text, ds->keys[i]);

