// Function to initialize dataset
dataset *initializeDataset(int length, int min_val, int max_val, bool isParallel) {
    assert(length > 0);
    assert(max_val >= min_val);

    dataset *ds = (dataset*)malloc(sizeof(dataset));
    assert(ds);

    ds->offsets = (long *)calloc(length, sizeof(long));
    assert(ds->offsets);

    ds->keys = (int *)malloc(length * sizeof(int));
    assert(ds->keys);

    ds->records = (record **)malloc(length * sizeof(record*));
    assert(ds->records);

    srand((unsigned int) time(NULL));

    if(isParallel){
        // Threads will be created and initialized records in parallel
        pthread_t threads[length];
        for (int i = 0; i < length; i++) {
            if (pthread_create(&threads[i], NULL, initializeRecordThreaded, ds)) {
                fprintf(stderr, "Error creating thread\n");
                return NULL;  // or exit
            }
        }
    } else{
        // Records will be initialized sequentially
        for (int i = 0; i < length; ++i) {
            ds->offsets[i] = i;
            ds->keys[i] = i + 1;
            ds->records[i] = (record*)malloc(sizeof(record));
            assert(ds->records[i]);
            generate_string(ds->records[i]->text, ds->keys[i]);
            ds->records[i]->value = rand() % (max_val - min_val + 1) + min_val;
        }
    }

    return ds;
}
