bool initialize_arrays(long *offsets[], int *keys[], record **records[], long num_offsets, int num_keys, long num_records) {
    srand((unsigned int) time(NULL)); // seeding random number generator

    // Allocating memory for offsets array
    *offsets = (long *)malloc(num_offsets * sizeof(long));
    if (*offsets == NULL) return false; 

    // Allocating memory for keys array
    *keys = (int *)malloc(num_keys * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return false;
    }

    // Initializing keys array with unique random values within a given range 0-1000
    for (long i = 0; i < num_keys; ++i) {
        (*keys)[i] = rand() % 1001; // assuming the required range is [0, 1000]
    }

    // Allocating memory for records array
    *records = (record **)malloc(num_records * sizeof(record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return false;
    }

    // Allocating memory for each record structure in the records array
    for (long i = 0; i < num_records; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Freeing previously allocated records 
            for (--i; i >= 0; --i) {
                free((*records)[i]);
            }
            free(*offsets);
            free(*keys);
            return false;
        }
    }

    // Initializing each record's int field with a random value within the specified range 0-100
    for (long i = 0; i < num_records; ++i) {
        (*records)[i]->value = rand() % 101; // assuming the required range is [0, 100]
    }

    // Initializing offsets array with sequential values starting from 0
    for (long i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = i;
    }

    return true;
}
