    char listId[16]; // assuming unique id will be string and max length of 15 chars
    CCI *ccis;
} CCILIST;

int compare(const void* a, const void* b) {
    return ((CCI*)a)->ccid - ((CCI*)b)->ccid;
}

void insertSorted(CCILIST* list, CCI cci) {
    if (list->count >= list->capacity) {
        size_t newCapacity = (list->capacity == 0)? 1 : list->capacity * 2; // double capacity when full
        CCI* newCCIs = realloc(list->ccis, sizeof(CCI)*newCapacity);

        if (!newCCIs) {
            printf("Memory allocation failed\n");
            return;
        }

        list->capacity = newCapacity;
        list->ccis = newCCIs;
    }

    // insert cci in sorted order
    CCI* pos = bsearch(&cci, list->ccis, list->count, sizeof(CCI), compare);
    if (pos) {
        memmove(pos+1, pos, (list->ccis + list->count - 1)- pos + 1); // shift elements to right
    } else {
        pos = bsearch(&cci, list->ccis, list->count, sizeof(CCI), compare) - 1; // find the correct position for insertion
    }

    *pos = cci;
    qsort(list->ccis, ++(list->count), sizeof(CCI), compare); // keep sorted after inserting
}
```
This code creates a custom sorting algorithm that sorts the CCILIST struct based on the ccid values. It also handles resizing of lists dynamically when capacity is full. The bsearch function is used to find the correct position for new CCI in the list maintaining its sorted order. This implementation assumes unique ccid's, if there can be duplicates please modify compare and handling accordingly. 

Note: I have implemented only insertion of single elements. Merge operation, batch insertion and out-of-range values handling are not handled here as they require more specific details regarding the requirement. This code also doesn't handle system dependencies like integration with external systems for initial population which you need to provide depending on the data source. Also, I have used qsort() function for sorting but if performance and memory usage is a concern then custom implementation of sorting algorithm may be better.
']

