['Here is a rough sketch of how you can implement the above task in C using functions and signal handling to ensure clean termination:

```c
#include <stdio.h>
#include <signal.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    int value;
} Record;

int *array = NULL;
size_t arraySize = 0;
long *offsetValues = NULL;
Record **records = NULL;
volatile sig_atomic_t done = 0;

void sighandler(int signum) {
    if (signum == SIGINT) {
        done = 1;
    }
}

int readInput() {
    int i = 0, temp;

    while (!done && scanf("%d", &temp) == 1) {
        array = realloc(array, (i + 1) * sizeof(*array));
        if(!array){
            perror("Memory allocation failed");
            return -1;
        }
        array[i++] = temp;
    }

    arraySize = i;
    offsetValues = calloc(arraySize, sizeof(long));
    records = malloc(arraySize * sizeof(*records));

    if(!offsetValues || !records) {
        perror("Memory allocation failed");
        return -1;
    }

    for (i = 0; i < arraySize; i++) {
        records[i] = malloc(sizeof(**records));
        if(!records[i]) {
            perror("Memory allocation failed");
            return -1;
        }
        records[i]->value = rand() % 100 + 1; // Random value in range [1, 100]
    }

    return 0;
}

int main(void) {
    srand(time(NULL));
    signal(SIGINT, sighandler);

    if (readInput() != 0) {
        fprintf(stderr, "Error reading input\n");
        return EXIT_FAILURE;
    }

    // Clean up
    for (size_t i = 0; i < arraySize; i++) {
        free(records[i]);
    }
    free(array);
    free(offsetValues);
    free(records);

    return EXIT_SUCCESS;
}
```
This code reads integers from standard input, stores them in an array, allocates memory for two arrays (`long offsetValues[]` and `Record records[]->value`) and fills the latter with random values. The program handles `SIGINT` signal to ensure clean termination of the program. After reading input it frees allocated memory resources.

Please note that this is a simple example and doesn't cover all points you mentioned in your requirements, but it gives you an idea of how you can implement some of them. For instance, this code doesn't limit maximum number of integers read from standard input or provide logging functionality, neither does handle error cases when reading input. You would need to add appropriate checks and logging based on your specific use case.
']

['Here's a basic implementation of your requirements in C using POSIX threads for thread safety and malloc()/free() for memory allocation:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Record* init_records(long *offsets, int *keys, size_t count) {
    if (count > 10000000) return NULL; // 10 million records constraint

    srand((unsigned int) time(NULL)); // Seed random generator

    Record* records = (Record*) malloc(sizeof(Record) * count);
    if (!records) {
        perror("malloc() failed");
        return NULL;
    }

    pthread_mutex_lock(&lock); // Lock for thread safety

    for (size_t i = 0; i < count; ++i) {
        records[i].value = keys[offsets[i] % count]; // Random value within given range
    }

    pthread_mutex_unlock(&lock); // Unlock after allocation

    return records;
}

void free_records(Record* records) {
    if (records) {
        pthread_mutex_lock(&lock); // Lock for thread safety
        free(records);
        pthread_mutex_unlock(&lock); // Unlock after deallocation
    }
}
```
In this code, `init_records` allocates memory and initializes records with random values within a given range. It uses POSIX threads for thread safety by locking the mutex before allocation and unlocking it afterwards. If allocation fails (malloc returns NULL), an error message is printed to stderr and the function returns NULL.

The `free_records` function frees the memory allocated by `init_records`. It also locks the mutex before deallocation and unlocks it afterwards for thread safety. 

Please replace 'keys' with your actual data source or any other random value generation method you prefer.
']

