typedef struct FileHash {
    char filePath[256];
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
} FileHash;

typedef struct Node {
    FileHash *fileHash;
    struct Node *next;
} Node;

void addNode(Node **head, FileHash *fileHash) {
    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) exit(1);

    newNode->fileHash = fileHash;
    newNode->next = *head;
    *head = newNode;
}

void printList(const Node *node) {
    while (node != NULL) {
        printf("%s: ", node->fileHash->filePath);

        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i)
            printf("%02x", node->fileHash->md5Hash[i]);
        printf("\n");

        node = node->next;
    }
}

void calculateMD5(const char *filename, unsigned char *hash, int maxFilesToProcess) {
    FILE *inFile = fopen (filename, "rb");
    if (inFile == NULL) return;

    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    if(ferror(inFile)) {
        return;
    }

    MD5_Init(&mdContext);
    while ((bytes = fread (data, 1, 1024, inFile)) != 0)
        MD5_Update(&mdContext, data, bytes);
    MD5_Final(hash, &mdContext);

    fclose (inFile);
}

int main() {
    Node *head = NULL;
    char filePath[256];
    unsigned char hash[MD5_DIGEST_LENGTH];
    int maxFilesToProcess = 0; // fill in actual value

    while (fgets(filePath, sizeof filePath, stdin) && maxFilesToProcess > 0) {
        filePath[strlen(filePath)-1] = '\0'; // remove newline character

        FileHash *fileHash = malloc(sizeof(FileHash));
        if (fileHash == NULL) exit(2);
        strncpy(fileHash->filePath, filePath, sizeof(fileHash->filePath)-1);

        calculateMD5(filePath, hash, maxFilesToProcess);
        memcpy(fileHash->md5Hash, hash, MD5_DIGEST_LENGTH);

        addNode(&head, fileHash);

        --maxFilesToProcess;
    }

    printList(head);

    // free memory here...
}
