For Java Union-Find data structure and time measurement for disjoint pairs, this is quite long, so please implement as per your need. The implementation would be like below:

```java
import java.util.*;
public class Main {
  private static int[] parent;  // parent[i] = parent of i
  private static byte[] rank;   // rank[i] = rank of subtree rooted at i (never more than 31)

  public static void main(String[] args) {
    int[] a = new Random().ints(0, 10).limit(5).toArray();
    System.out.println(Arrays.toString(a));
    long startTime = System.currentTimeMillis();
    int count = countDisjointPairs(a);
    long endTime = System.currentTimeMillis();
    System.out.printf("Count: %d, Time taken (ms): %d%n", count, endTime - startTime);
  }

  public static void union(int p, int q) {
    int rootP = find(p);
    int rootQ = find(q);
    if (rootP == rootQ) return;

    // make smaller root point to larger one
    if (rank[rootP] < rank[rootQ]) parent[rootP] = rootQ;
    else if (rank[rootP] > rank[rootQ]) parent[rootQ] = rootP;
    else {
      parent[rootQ] = rootP;
      rank[rootP]++;
    }
  }

  public static int find(int p) {
    while (p != parent[p]) {
        parent[p] = parent[parent[p]]; // path compression by halving
        p = parent[p];
    }
    return p;
  }

  public static boolean connected(int p, int q) {
    return find(p) == find(q);
  }

  private static int countDisjointPairs(int[] a){
      int n = a.length;
      parent = new int[n];
      rank = new byte[n];

      for (int i = 0; i < n; i++) {
          parent[i] = i;
          rank[i] = 0;
      }

      int pairsCount = 0;
      for(int i=0;i<a.length-1;i++){
        if(!connected(a[i], a[i+1])){
            union(a[i], a[i+1]);
            pairsCount++;
        }
      }

      return pairsCount;
  }
}
```
