#include <stdlib.h>
#include <pthread.h>
#define MAX_RECORDS 1000000 /* Adjust this according to your needs */

typedef struct Record {
    int value;
} Record;

typedef struct RecordArray {
    pthread_mutex_t mutex;
    long *offsets;
    int *keys;
    Record *records;
    size_t numRecords;
} RecordArray;

RecordArray* createRecordArray(size_t numRecords) {
    RecordArray *array = malloc(sizeof(RecordArray));
    if (array == NULL || pthread_mutex_init(&array->mutex, NULL) != 0) {
        free(array);
        return NULL;
    }

    array->offsets = calloc(numRecords, sizeof(long));
    array->keys = calloc(numRecords, sizeof(int));
    array->records = calloc(numRecords, sizeof(Record));
    if (array->offsets == NULL || array->keys == NULL || array->records == NULL) {
        destroyRecordArray(array);
        return NULL;
    }

    array->numRecords = numRecords;
    return array;
}

void destroyRecordArray(RecordArray *array) {
    if (array != NULL) {
        pthread_mutex_destroy(&array->mutex);
        free(array->offsets);
        free(array->keys);
        free(array->records);
        free(array);
    }
