["Here's a basic example of how you might implement such a function in C using POSIX threads (pthreads):

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct managed_array {
    long* offsets;
    int* keys;
    Record** records;

    size_t capacity;
    size_t size;

    pthread_mutex_t lock;
} ManagedArray;

ManagedArray* create_managed_array(size_t initial_capacity) {
    ManagedArray* array = malloc(sizeof(ManagedArray));

    if (array == NULL) return NULL;

    array->offsets = calloc(initial_capacity, sizeof(long));
    array->keys = calloc(initial_capacity, sizeof(int));
    array->records = calloc(initial_capacity, sizeof(Record*));

    if (array->offsets == NULL || array->keys == NULL || array->records == NULL) {
        free(array->offsets);
        free(array->keys);
        free(array->records);

        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void resize_managed_array(ManagedArray* array, size_t new_capacity) {
    if (new_capacity < array->size) return;

    pthread_mutex_lock(&array->lock);

    array->offsets = realloc(array->offsets, new_capacity * sizeof(long));
    array->keys = realloc(array->keys, new_capacity * sizeof(int));
    array->records = realloc(array->records, new_capacity * sizeof(Record*));

    if (new_capacity > array->capacity) {
        memset(&array->offsets[array->capacity], 0, (new_capacity - array->capacity) * sizeof(long));
        memset(&array->keys[array->capacity], 0, (new_capacity - array->capacity) * sizeof(int));
        memset(&array->records[array->capacity], 0, (new_capacity - array->capacity) * sizeof(Record*));
    }

    array->capacity = new_capacity;

    pthread_mutex_unlock(&array->lock);
}

void add_to_managed_array(ManagedArray* array, long offset, int key, Record* record) {
    pthread_mutex_lock(&array->lock);

    if (array->size >= array->capacity) {
        resize_managed_array(array, array->capacity * 2);
    }

    array->offsets[array->size] = offset;
    array->keys[array->size] = key;
    array->records[array->size] = record;
    array->size++;

    pthread_mutex_unlock(&array->lock);
}
```
