typedef struct FileHash {
    char *filePath;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    struct FileHash *next;
} FileHash;

void calculateAndStoreHash(char *filePath, FileHash **head) {
    FILE *file = fopen(filePath, "rb");
    if (file == NULL) exit(EXIT_FAILURE);

    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    unsigned char *fileBuffer = malloc(fileSize);
    if (fileBuffer == NULL) exit(EXIT_FAILURE);

    fread(fileBuffer, 1, fileSize, file);

    FileHash *newNode = malloc(sizeof(FileHash));
    if (newNode == NULL) exit(EXIT_FAILURE);

    newNode->filePath = strdup(filePath); // Duplicate the string for later use
    SHA256(fileBuffer, fileSize, newNode->hash);
    newNode->next = *head;
    *head = newNode;

    free(fileBuffer);
    fclose(file);
}
