```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

void initialize_linked_list(const char* config_file, Node** head) {

    FILE *file = fopen(config_file, "r");
    if (file == NULL){
        printf("Failed to open configuration file.\n");
        exit(EXIT_FAILURE);
    }

    int size;
    int maxValue;
    if (fscanf(file, "%d %d", &size, &maxValue) != 2) {
        printf("Invalid format of configuration file.\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int) time(NULL));

    *head = (Node*) malloc(sizeof(Node));
    if (*head == NULL){
        printf("Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    Node* curr = *head;

    for (int i = 0; i < size-1; ++i) {
        curr->value = rand() % maxValue;
        curr->next = (Node*) malloc(sizeof(Node));
        if (curr->next == NULL){
            printf("Failed to allocate memory.\n");
            exit(EXIT_FAILURE);
        }

        curr = curr->next;
    }

    curr->value = rand() % maxValue;
    curr->next = NULL;

    fclose(file);
}
