Due to its complexity, dynamic resizing in multi-threaded environment, proper memory management, DNS server response handling, network latency handling, synchronization mechanisms etc., you need a well-structured knowledge on these subjects. The code also requires libresolv for the dns resolution functions.

```c
#include <stdlib.h>
#include <stdio.h>
#include <sys/types.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <resolv.h>
#include <netinet/in.h>
#include <arpa/nameser.h>
#include <arpa/inet.h>
#include <pthread.h>

// Custom struct for holding dns response and error code
typedef struct {
    int errcode;  // Holds any error codes encountered during resolution
    u_char ip[4]; // Array to hold the IP address returned by DNS
} ResolutionResult;

ResolutionResult *resolveHost(const char* hostname) {

    unsigned char answer[NS_PACKETSZ];
    int i, ret = -1;
    ns_msg handle;
    ns_rr rr;

    ResolutionResult *res = malloc(sizeof(ResolutionResult));
    if (!res) {
        perror("Memory Allocation Error:");
        return NULL;
    }

    memset(&handle, 0, sizeof(handle));

    // Send DNS query for hostname
    ret = res_query(hostname, C_INET, T_A, answer, sizeof(answer));

    if (ret < 0) {
        printf("res_query failed: %s\n", strerror(errno));
        res->errcode = errno;
        return res;
    }

    // Parse DNS response
    ret = ns_initparse(answer, ret, &handle);

    if (ret < 0) {
        printf("ns_initparse failed: %s\n", strerror(-ret));
        res->errcode = -ret;
        return res;
    }

    // Fetch the IP address from the DNS response 
    ret = ns_parserr(&handle, ns_s_an, 0, &rr);

    if (ret <= 0) {
        printf("ns_parserr failed: %s\n", strerror(-ret));
        res->errcode = -ret;
        return res;
    }

    // Store the IP address in the struct 
    memcpy(res->ip, rr.rdata, rr.rdlength);

    res->errcode = 0; // No error code means success
    return res;
}
```
In this example, a simple DNS resolution function is implemented. The `resolveHost` function takes a hostname string and returns a ResolutionResult pointer. This structure holds the error code (0 for success) and the IP address found in the DNS response. If an error occurs during DNS resolution, it will be stored in the 'errcode' field of the ResolutionResult struct.
']

