['Sure, here is the C function based on your requirements. Note that thread safety is not implemented in this sample. For actual use, you should consider using a mutex lock for critical sections to ensure data integrity. Also, the maximum memory usage check and dynamic resizing is just a basic implementation and may need adjustments depending on specific use cases:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    size_t offsetCount;
    int* keys;
    size_t keyCount;
    Record** records;
    size_t recordCount;
} DataStorage;

DataStorage dataStore = {NULL, 0, NULL, 0, NULL, 0};
size_t maxMemory = 1024 * 1024; // 1MB
FILE* file = NULL;

int addRecord(int key, int value) {
    if (dataStore.offsetCount + 1 >= maxMemory / sizeof(long)) {
        fprintf(stderr, "Max memory usage exceeded\n");
        return -1;
    }

    dataStore.keys = realloc(dataStore.keys, ++dataStore.keyCount * sizeof(int));
    if (!dataStore.keys) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    dataStore.records = realloc(dataStore.records, ++dataStore.recordCount * sizeof(Record*));
    if (!dataStore.records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    dataStore.offsets = realloc(dataStore.offsets, dataStore.keyCount * sizeof(long));
    if (!dataStore.offsets) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    dataStore.keys[dataStore.keyCount - 1] = key;
    *record = (Record){value};
    dataStore.records[dataStore.recordCount - 1] = record;
    dataStore.offsets[dataStore.offsetCount++] = (long)record;

    if (file && fwrite(record, sizeof(*record), 1, file) != 1) {
        perror("File write failed");
        return -1;
    }

    return 0;
}
```

In this code, the `addRecord()` function adds a new record. It checks if the addition of a new record exceeds the maximum memory usage and returns an error if so. If not, it reallocates memory for the arrays and creates a new record with the given key and value. The offsets array is also updated to store the address of the newly allocated record. If a file has been opened for persistence, the function writes the record to disk.
