typedef struct {
    int value;
} Record;

typedef struct {
    Record *records;
    size_t size;
    size_t capacity;
} DynamicArray;

DynamicArray* createArray(size_t initialSize) {
    DynamicArray *array = malloc(sizeof(DynamicArray));

    if (array == NULL) {
        exit(-1);
    }

    array->records = malloc(initialSize * sizeof(Record));

    if (array->records == NULL) {
        free(array);
        exit(-1);
    }

    array->size = 0;
    array->capacity = initialSize;

    return array;
}

void resizeArray(DynamicArray *array, size_t newCapacity) {
    Record *newRecords = realloc(array->records, newCapacity * sizeof(Record));

    if (newRecords == NULL) {
        free(array);
        exit(-1);
    }

    array->records = newRecords;
    array->capacity = newCapacity;
}

void pushToArray(DynamicArray *array, Record record) {
    if (array->size == array->capacity) {
        resizeArray(array, 2 * array->capacity);
    }

    array->records[array->size++] = record;
}

void populateArrayWithRandomValues(DynamicArray *array, size_t minValue, size_t maxValue) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < array->capacity; ++i) {
        Record record;
        record.value = rand() % (maxValue - minValue + 1) + minValue;

        pushToArray(array, record);
    }
}

void destroyArray(DynamicArray *array) {
    free(array->records);
    free(array);
}
```
