void* allocateAndInitialize(size_t recordCount, size_t range) {
    if (recordCount == 0 || range <= 1) {
        fprintf(stderr, "Invalid input parameters: %s\n", strerror(EINVAL));
        return NULL;
    }

    long* offsetValues = malloc(sizeof(*offsetValues) * recordCount);
    if (offsetValues == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    int* keys = calloc(recordCount, sizeof(*keys));
    if (keys == NULL) {
        free(offsetValues);
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    Record* records = malloc(sizeof(*records) * recordCount);
    if (records == NULL) {
        free(offsetValues);
        free(keys);
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    for (size_t i = 0; i < recordCount; ++i) {
        records[i].value = rand() % range;
    }

    // Store allocated memory addresses in a struct to keep them together
    void** allocationBlock = malloc(3 * sizeof(*allocationBlock));
    if (allocationBlock == NULL) {
        free(offsetValues);
        free(keys);
        free(records);
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    allocationBlock[0] = offsetValues;
    allocationBlock[1] = keys;
    allocationBlock[2] = records;

    return (void*)allocationBlock;
}

void freeAllocations(void* allocations) {
    void** allocationBlock = (void**) allocations;
    if (allocationBlock == NULL) {
        return;
    }

    // Free in reverse order to avoid dangling pointers
    free(allocationBlock[2]);
    free(allocationBlock[1]);
    free(allocationBlock[0]);
    free(allocationBlock);
}
