['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int integer;
    float floating_point;
    char character[256];
} Record;

typedef struct Arrays {
    pthread_mutex_t lock;
    long* offsets;
    int* keys;
    float* values;
    Record* records;
    size_t capacity;
} Arrays;

void initialize(Arrays* arrays, size_t offset_count, size_t key_count, size_t value_count, size_t record_count) {
    if (pthread_mutex_init(&arrays->lock, NULL) != 0) {
        printf("\n Mutex init failed\n");
        return;
    }

    arrays->offsets = malloc(sizeof(long)*offset_count);
    if (arrays->offsets == NULL) { 
      printf("Memory allocation for offsets array failed.\n");
      return;
    }

    arrays->keys = malloc(sizeof(int)*key_count);
    if (arrays->keys == NULL) { 
      printf("Memory allocation for keys array failed.\n");
      return;
    }

    arrays->values = malloc(sizeof(float)*value_count);
    if (arrays->values == NULL) { 
      printf("Memory allocation for values array failed.\n");
      return;
    }

    arrays->records = malloc(sizeof(Record)*record_count);
    if (arrays->records == NULL) { 
      printf("Memory allocation for records array failed.\n");
      return;
    }

    arrays->capacity = offset_count + key_count + value_count + record_count * sizeof(Record);
}

void resize(Arrays* arrays, size_t new_offset_count, size_t new_key_count, size_t new_value_count, size_t new_record_count) {
    pthread_mutex_lock(&arrays->lock); 

    long *new_offsets = realloc(arrays->offsets, sizeof(long)*new_offset_count);
    if (new_offsets == NULL && new_offset_count != 0) { 
      printf("Memory allocation for resizing offsets array failed.\n");
      pthread_mutex_unlock(&arrays->lock);  
      return;
    }

    int *new_keys = realloc(arrays->keys, sizeof(int)*new_key_count);
    if (new_keys == NULL && new_key_count != 0) { 
      printf("Memory allocation for resizing keys array failed.\n");
      pthread_mutex_unlock(&arrays->lock);  
      return;
    }

    float *new_values = realloc(arrays->values, sizeof(float)*new_value_count);
    if (new_values == NULL && new_value_count != 0) { 
      printf("Memory allocation for resizing values array failed.\n");
      pthread_mutex_unlock(&arrays->lock);  
      return;
    }

    Record *new_records = realloc(arrays->records, sizeof(Record)*new_record_count);
    if (new_records == NULL && new_record_count != 0) { 
      printf("Memory allocation for resizing records array failed.\n");
      pthread_mutex_unlock(&arrays->lock);  
      return;
    }

    arrays->offsets = new_offsets;
    arrays->keys = new_keys;
    arrays->values = new_values;
    arrays->records = new_records;
    arrays->capacity = new_offset_count + new_key_count + new_value_count + new_record_count * sizeof(Record);

    pthread_mutex_unlock(&arrays->lock);  
}

void cleanup(Arrays* arrays) {
  pthread_mutex_destroy(&arrays->lock);
  free(arrays->offsets);
  free(arrays->keys);
  free(arrays->values);
  free(arrays->records);
}
```
This code provides a solution using C programming language. It uses pthread library for thread safety, and also realloc for dynamic resizing of arrays with efficient memory utilization. This is the basic structure and it needs to be adjusted based on your specific requirements.
