Here is the JavaScript program that dynamically loads and executes multiple JavaScript files:

```javascript
async function loadAndExecuteFiles(files, options) {
    const cache = new Map(); // for caching scripts

    async function fetchWithCache(url) {
        if (!cache.has(url)) {
            const response = await fetch(url);
            if (response.ok) {
                const scriptText = await response.text();
                cache.set(url, scriptText);
            } else {
                throw new Error('HTTP error: ' + response.status);
            }
        }

        return cache.get(url);
    }

    async function checkAndExecuteScript(file) {
        const url = `${options.baseUrl}${file}`;
        const metadataResponse = await fetch(`${options.apiEndpoint}/${file}`);

        if (metadataResponse.ok) {
            const metadata = await metadataResponse.json();
            const currentScriptText = cache.get(url);

            // Check for version and dependencies, skip or reload as needed
            if (currentScriptText && metadata.version === currentVersion && metadata.dependencies.every(dep => cache.has(`${options.baseUrl}${dep}.js`))) {
                console.log(`Skipping ${file}: version and dependencies match`);
                return;
            } else if (currentScriptText) {
                console.log(`Reloading ${file}: version or dependency mismatch`);
                cache.delete(url); // remove old script from cache
            }

            const newScriptText = await fetchWithCache(url);
            eval(newScriptText); // execute the script
        } else {
            console.error('Error fetching metadata: ', metadataResponse.status);
        }
    }

    for (const file of files) {
        try {
            await checkAndExecuteScript(file);
        } catch (err) {
            console.log(`Failed to load and execute ${file}: `, err);
        }
    }
}
```
Please note that the JavaScript code assumes Node environment with `fetch` support for API calls and CORS policy. The network latency is managed by caching previous requests which reduces redundant network calls. However, in a real-world application you should also consider other factors like server response time, file size etc., while implementing these strategies.
