    int usedKeys[1001] = { 0 }; // Keeps track of used keys to ensure uniqueness.
    for (size_t i = 0; i < num_keys; ++i) {
        int key;

        do {
            key = rand() % 1001; // Generates a random number in range [0, 1000].
        } while(usedKeys[key] != 0);

        usedKeys[key] = 1;
        keys[i] = key;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i]->value = rand() % 101; // Generates a random number in range [0, 100].
    }
}

void initializeAndAllocate(size_t num_offsets, size_t num_keys, size_t num_records) {
    long* offsets = safeMalloc(num_offsets * sizeof(*offsets));
    int* keys = safeMalloc(num_keys * sizeof(*keys));

    record_t** records = safeMalloc(num_records * sizeof(*records));
    for (size_t i = 0; i < num_records; ++i) {
        records[i] = safeMalloc(sizeof(record_t));
    }

    initializeArrays(offsets, keys, records, num_offsets, num_keys, num_records);

    // Clean up.
    free(offsets);
    free(keys);

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i]);
    }

    free(records);
}
