['Here is the required C code block that implements this task:
```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct record {
    int int_value;
    double double_value;
    char* string_ptr;
} record;

typedef struct data_struct {
    long* offsets;
    int* keys;
    double* values;
    record** records;
    pthread_mutex_t lock;
    size_t capacity;
    size_t length;
} data_struct;

data_struct* create_struct(size_t initial_capacity) {
    data_struct* ds = malloc(sizeof(data_struct));
    if (ds == NULL) return NULL;

    ds->offsets = calloc(initial_capacity, sizeof(long));
    ds->keys = calloc(initial_capacity, sizeof(int));
    ds->values = calloc(initial_capacity, sizeof(double));
    ds->records = calloc(initial_capacity, sizeof(record*));

    if (ds->offsets == NULL || ds->keys == NULL || 
        ds->values == NULL || ds->records == NULL) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->values);
        free(ds->records);
        free(ds);
        return NULL;
    }

    ds->capacity = initial_capacity;
    ds->length = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void add_record(data_struct* ds, record* r) {
    pthread_mutex_lock(&ds->lock);

    if (ds->length == ds->capacity) {
        size_t new_size = ds->capacity * 2;
        long* new_offsets = realloc(ds->offsets, new_size * sizeof(long));
        int* new_keys = realloc(ds->keys, new_size * sizeof(int));
        double* new_values = realloc(ds->values, new_size * sizeof(double));
        record** new_records = realloc(ds->records, new_size * sizeof(record*));

        if (new_offsets == NULL || new_keys == NULL || 
            new_values == NULL || new_records == NULL) {
            pthread_mutex_unlock(&ds->lock);
            return;
        }

        ds->capacity = new_size;
        ds->offsets = new_offsets;
        ds->keys = new_keys;
        ds->values = new_values;
        ds->records = new_records;
    }

    ds->records[ds->length] = r;
    ds->length++;

    pthread_mutex_unlock(&ds->lock);
}

void free_struct(data_struct* ds) {
    for (size_t i = 0; i < ds->length; ++i) {
        free(ds->records[i]->string_ptr);
        free(ds->records[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->values);
    free(ds->records);

    pthread_mutex_destroy(&ds->lock);
    free(ds);
}
```
In this code, `create_struct` creates a new data structure with the given initial capacity. If memory allocation fails at any point, all previously allocated memory is freed and NULL is returned. 

The `add_record` function adds a new record to the data structure. If the current capacity of the data structure is reached, the size of the data structure will double. The same mechanism as for allocation failure is used here. After adding the record successfully, the mutex is unlocked.

Finally, the `free_struct` function frees all memory associated with a given data structure and destroys its lock to clean up afterwards. It also frees each individual string within each record.
