```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#define INITIAL_SIZE 1024

typedef struct {
    int value;
} Record;

// Define a structure to hold array-related data and mutex for thread safety
typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ArrayData;

// Initialize a new array data structure with initial capacity and mutex initialization
ArrayData init_array() {
    ArrayData data = {0};
    data.offsets = calloc(INITIAL_SIZE, sizeof(*data.offsets));
    assert(data.offsets != NULL);

    data.keys = calloc(INITIAL_SIZE, sizeof(*data.keys));
    assert(data.keys != NULL);

    data.records = calloc(INITIAL_SIZE, sizeof(*data.records));
    assert(data.records != NULL);

    data.capacity = INITIAL_SIZE;
    pthread_mutex_init(&data.lock, NULL);

    return data;
}

// Add a new element to the array and resize if necessary
void add(ArrayData* data, long offset, int key, Record* record) {
    pthread_mutex_lock(&data->lock);
    if (data->count == data->capacity) {
        // Double capacity when full
        data->offsets = realloc(data->offsets, sizeof(*data->offsets) * data->capacity * 2);
        assert(data->offsets != NULL);

        data->keys = realloc(data->keys, sizeof(*data->keys) * data->capacity * 2);
        assert(data->keys != NULL);

        data->records = realloc(data->records, sizeof(*data->records) * data->capacity * 2);
        assert(data->records != NULL);
    }

    // Add new element
    data->offsets[data->count] = offset;
    data->keys[data->count] = key;
    data->records[data->count] = record;
    (data->count)++;

    pthread_mutex_unlock(&data->lock);
}
```

In this code, we start by defining a `Record` structure. We then define an array data type that includes offsets and keys arrays, as well as the number of records in the array and its capacity. 

We also use a mutex to ensure thread safety when accessing or modifying these arrays. When adding new elements, we check if we need to resize our arrays and lock/unlock the mutex while doing so. This will make sure that concurrent access from multiple threads is correctly managed without data corruption.

This code only covers allocation of memory for and initialization of arrays and records. Implementing error handling, caching mechanism, performance optimization, logging capabilities, unit tests, and integration with an existing system are complex tasks beyond this scope, requiring further discussion and implementation that would be significantly larger than this initial block. The specifics greatly depend on the exact requirements and constraints in your particular use case.
