public void connectToServer() 
{
    int maxRetryCount = 5;
    long initialDelayMs = 1000; // Initial delay in ms
    for (int i = 0; i <= maxRetryCount; i++) 
    {
        try 
        {
            AsynchronousSocketChannel socket = AsynchronousSocketChannel.open();
            InetSocketAddress addr = new InetSocketAddress("localhost", 80);
            Future<Void> result = socket.connect(addr);
            // Handle connection and communication here
            break;
        } 
        catch (IOException ex) 
        {
            if (i == maxRetryCount) 
            {
                // Max retries reached, handle exception
                throw ex;
            }
            else 
            {
                // Sleep and retry with exponential backoff
                Thread.sleep(initialDelayMs * (1 << i)); // Left shift is equivalent to multiplying by 2^i
            }
        }
    }
}
```

