```cpp
#include <iostream>
#include <vector>
#include <fstream>
#include <string>
#include <algorithm>
#include <cstdint>
#include <memory>
#include <random>
#include <atomic>
#include <mutex>
#include <shared_mutex>
#include <utility>

class MemoryPool {
private:
    std::unique_ptr<uint8_t[]> pool;
public:
    explicit MemoryPool(size_t size) : pool{new uint8_t[size]} {}
    ~MemoryPool() = default;
};

std::atomic<bool> shutdownRequested{false};
constexpr uint32_t kMaxRandomValue = 10'000;
constexpr double kShrinkThresholdRatio = 0.5; // shrink when used size is less than 50% of total size
constexpr double kGrowthFactor = 2.0; // grow by doubling the size
std::random_device rd{};
std::mt19937 gen{rd()};
std::uniform_int_distribution<> dis{0, kMaxRandomValue};

class DynamicArray {
private:
    std::unique_ptr<MemoryPool> memory;
    size_t totalSize = 0;
    size_t usedSize = 0;
    std::shared_mutex mtx; // Use shared_mutex for multiple readers and single writer.
public:
    explicit DynamicArray(size_t init) : totalSize{init}, memory{std::make_unique<MemoryPool>(totalSize)} {}
    ~DynamicArray() = default;

    uint32_t insert() {
        std::lock_guard<std::shared_mutex> lock{mtx}; // Use exclusive write access for concurrency control.
        ++usedSize;
        if (usedSize > totalSize) {
            memory = std::make_unique<MemoryPool>(static_cast<size_t>(totalSize * kGrowthFactor));
            totalSize *= kGrowthFactor;
        }
        return dis(gen); // Returns a new random value.
    }

    void erase() {
        std::lock_guard<std::shared_mutex> lock{mtx}; 
        --usedSize;
        if (static_cast<double>(usedSize) / totalSize < kShrinkThresholdRatio) {
            memory = std::make_unique<MemoryPool>(totalSize / 2); // Shrinks by half when used size is less than 50% of the total.
            totalSize /= 2;
        }
    }

    void readConfigFile() {
        std::ifstream file{"config.txt"};
        if (file) {
            file >> totalSize;
            memory = std::make_unique<MemoryPool>(totalSize);
        } else {
            throw std::runtime_error("Failed to open the config file");
        }
    }

    void writeConfigFile() const {
        std::ofstream file{"config.txt"};
        if (file) {
            file << totalSize;
        } else {
            throw std::runtime_error("Failed to write to the config file");
        }
    }

    size_t getUsedSize() const { return usedSize; }
    size_t getTotalSize() const { return totalSize; }
};
```
This is a basic implementation of DynamicArray class. It only handles insertion and deletions in a concurrent-safe manner, and it does not handle offsets, lookups or the like. You would need to expand on this code to include these features according to your specifications. For example, you could use a std::unordered_map<size_t, size_t> to store offsets, where keys represent unique identifiers for values and values represent memory locations. The actual value can be stored in the MemoryPool as binary data at specified location.
