void resize(size_t s) {
    pthread_mutex_lock(&lock);

    // Resize arrays
    offsets = (long*) realloc(offsets, s * sizeof(long));
    keys = (int*) realloc(keys, s * sizeof(int));
    values = (double*) realloc(values, s * sizeof(double));

