    // Check if memory allocation was successful for each array
    assert(offsets != NULL);
    assert(keys != NULL);
    assert(values != NULL);
    assert(records != NULL);

    DynamicArrays* arrays = malloc(sizeof(DynamicArrays));
    // Check if memory allocation was successful for the arrays structure
    assert(arrays != NULL);

    arrays->offsets = offsets;
    arrays->keys = keys;
    arrays->values = values;
    arrays->records = records;

    return arrays;
}

void resizeArrays(DynamicArrays* arrays, int newSize) {

    // Lock the mutex before resizing to prevent concurrent access
    pthread_mutex_lock(&lock); 

    // Reallocate memory for each array
    arrays->offsets = realloc(arrays->offsets, newSize * sizeof(long));
    arrays->keys = realloc(arrays->keys, newSize * sizeof(int));
    arrays->values = realloc(arrays->values, newSize * sizeof(double));

    // Check if memory allocation was successful for each array
    assert(arrays->offsets != NULL);
    assert(arrays->keys != NULL);
    assert(arrays->values != NULL);

    pthread_mutex_unlock(&lock);  // Unlock the mutex after resizing
}

void freeArrays(DynamicArrays* arrays) {

    // Lock the mutex before freeing to prevent concurrent access
    pthread_mutex_lock(&lock);  

    // Free memory for each array
    free(arrays->offsets);
    free(arrays->keys);
    free(arrays->values);

    // Also, since 'records' points to a list of structures, 
    // we need to iterate over it and individually free each structure.
    for (int i = 0; i < sizeof(arrays->records) / sizeof(dataRecord*); i++) {
        free(arrays->records[i]->stringPointer);
        free(arrays->records[i]);
    }

    // Finally, free the arrays structure itself
    free(arrays);

    pthread_mutex_unlock(&lock);  // Unlock the mutex after freeing
}
```

Note: The code above assumes you're working in an environment where memory allocation can fail and the process should exit if that happens. In real-world applications, error handling would be more robust and include checks for allocation failures. It also doesn't handle resizing of individual records or adding new records to the list. Implementing these features would require more complex code and might involve additional considerations like dynamically growing the `records` array.
