pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logfile;
void *pool;
size_t pool_offset = 0;

void *allocate(size_t size) {
    pthread_mutex_lock(&mutex);
    if (pool_offset + size > POOL_SIZE) {
        fprintf(logfile, "Error: Out of memory in allocator\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    void *ptr = pool + pool_offset;
    pool_offset += size;
    pthread_mutex_unlock(&mutex);
    return ptr;
}

int init() {
    // Initialize logfile and allocator
    logfile = fopen("error.log", "w");
    if (logfile == NULL) {
        printf("Error: Could not open log file\n");
        return -1;
    }
    pool = mmap(NULL, POOL_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool == MAP_FAILED) {
        fprintf(logfile, "Error: Could not allocate memory pool\n");
        return -1;
