} Record;

typedef struct PoolAllocator {
    size_t poolSize;
    long* offsetValues;
    int* keys;
    Record** records;
    pthread_mutex_t mutex;
} PoolAllocator;

PoolAllocator* createPoolAllocator(size_t poolSize) {
    PoolAllocator* allocator = malloc(sizeof(PoolAllocator));
    if (allocator == NULL) {
        return NULL;
    }

    allocator->poolSize = poolSize;
    allocator->offsetValues = calloc(poolSize, sizeof(long));
    allocator->keys = malloc(poolSize * sizeof(int));
    allocator->records = calloc(poolSize, sizeof(Record*));

    if (allocator->offsetValues == NULL || allocator->keys == NULL || allocator->records == NULL) {
        freePoolAllocator(allocator);
        return NULL;
    }

    pthread_mutex_init(&allocator->mutex, NULL);

    return allocator;
}

void destroyPoolAllocator(PoolAllocator* allocator) {
    if (allocator == NULL) {
        return;
    }

    for (size_t i = 0; i < allocator->poolSize; ++i) {
        free(allocator->records[i]);
    }

    free(allocator->offsetValues);
    free(allocator->keys);
    free(allocator->records);
    pthread_mutex_destroy(&allocator->mutex);

    free(allocator);
}

void* allocateMemory(PoolAllocator* allocator) {
    if (allocator == NULL) {
        return NULL;
    }

    pthread_mutex_lock(&allocator->mutex);

    for (size_t i = 0; i < allocator->poolSize; ++i) {
        if (allocator->offsetValues[i] == 0) {
            allocator->records[i] = malloc(sizeof(Record));

            if (allocator->records[i] == NULL) {
                pthread_mutex_unlock(&allocator->mutex);
                return NULL;
            }

            allocator->offsetValues[i] = 1;
            pthread_mutex_unlock(&allocator->mutex);

            return allocator->records[i];
        }
    }

    pthread_mutex_unlock(&allocator->mutex);

