['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
    char* string;
    struct record* next;
} Record;

Record *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeRecords(int count, int minValue, int maxValue) {
    // Ensure mutually exclusive access to shared data.
    pthread_mutex_lock(&lock);

    srand(time(0)); // Initialize random seed for values generation.

    head = malloc(sizeof(Record) * count);
    if (head == NULL) {
        printf("Memory allocation failed.\n");
        exit(-1);
    }

    for (int i = 0; i < count; ++i) {
        // Dynamically allocate memory for each record's string.
        head[i].string = malloc(sizeof(char) * 256);
        if (head[i].string == NULL) {
            printf("Memory allocation failed.\n");
            exit(-1);
        }

        // Generate a random value within given range.
        head[i].value = rand() % (maxValue - minValue + 1) + minValue; 

        if (i < count-1) {
            head[i].next = &head[i+1];
        } else {
            head[i].next = NULL;
        }
    }

    pthread_mutex_unlock(&lock); // Release the lock.
}

void traverseForward() {
    Record *node = head;
    while(node != NULL) {
        printf("Value: %d, String: %s\n", node->value, node->string);
        node = node->next;
    }
}

void traverseBackward() {
    Record *node = head;
    while(node != NULL) {
        if (node->next == NULL) {
            break;
        }
        node = node->next;
    }

    while(node != NULL) {
        printf("Value: %d, String: %s\n", node->value, node->string);
        if (node == head) {
            break;
        }
        Record *temp = head;
        while(temp->next != node) {
            temp = temp->next;
        }

        node = temp;
    }
}

void freeRecords() {
    pthread_mutex_lock(&lock); // Ensure mutually exclusive access to shared data.

    Record *node = head;
    while(node != NULL) {
        free(node->string); // Free memory allocated for each string.
        ++node;
    }

    free(head); // Finally, free the entire array of records.
    pthread_mutex_unlock(&lock); // Release the lock.
}
``` 
This C code implements a dynamic allocation and initialization of 'struct record's linked list for each thread in a multi-threaded environment. Memory allocation failures are handled by checking if the allocations were successful or not. The memory management is also synchronized using mutex to prevent data corruption during concurrent access. When done with records, they can be freed safely as well. Linked list traversal is implemented both forward and backward directions.
']

