#include <time.h>

typedef struct {
    int value;
} record;

// Mutex locks for thread safety
pthread_mutex_t lock_offset = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t lock_key = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t lock_record = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(long *offset, int *keys, record **records, size_t arraySize, unsigned int seed) {
    // Initialize random number generator with given seed
    srand(seed);

    // Allocate memory for arrays
    offset = (long*)malloc(arraySize*sizeof(long));
    if(offset == NULL) {
        printf("Memory allocation error for 'offset' array.\n");
        exit(-1);
    }

    keys = (int*)malloc(arraySize*sizeof(int));
    if(keys == NULL) {
        printf("Memory allocation error for 'keys' array.\n");
        free(offset);
        exit(-1);
    }

    records = (record**)malloc(arraySize*sizeof(record*));
    if(records == NULL) {
        printf("Memory allocation error for 'records' array.\n");
        free(offset);
        free(keys);
        exit(-1);
    }

    // Initialize arrays and records with random values within a specified range using locks for thread safety
    pthread_mutex_lock(&lock_offset);
    for(int i=0; i<arraySize; i++) {
        offset[i] = rand(); 
    }
    pthread_mutex_unlock(&lock_offset);

    pthread_mutex_lock(&lock_key);
    for(int i=0; i<arraySize; i++) {
        keys[i] = rand() % 100; // Assuming range is [0, 99]
    }
    pthread_mutex_unlock(&lock_key);

    pthread_mutex_lock(&lock_record);
    for(int i=0; i<arraySize; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if(records[i] == NULL) {
            printf("Memory allocation error for record %d.\n", i);
            // Free previously allocated memory before exiting
            for(--i; i>=0; --i){ 
                free(records[i]);
            }
            free(offset);
            free(keys);
            exit(-1);
        }
        records[i]->value = rand() % 1000; // Assuming range is [0, 999]
    }
    pthread_mutex_unlock(&lock_record);
}
