['Here's a basic implementation in C that handles some of the requirements mentioned above. It uses mutex locks for thread safety. The error handling strategy here is quite simple - if any memory allocation fails or file I/O errors occur, it prints an error message and exits immediately with failure status code. Memory leaks are managed by freeing all allocated memory before exit.

This example assumes a POSIX environment (e.g., Linux, OSX). Adjust as necessary for other platforms:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char *string_ptr;
} record;

void *initialize(FILE *file, size_t max_records) {
    // Initialize mutex for thread safety
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    long* offsets = calloc(max_records, sizeof(long));
    int* keys = calloc(max_records, sizeof(int));
    record** records = calloc(max_records, sizeof(record*));

    if (offsets == NULL || keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int) time(NULL));  // seed random number generator
    char buffer[256];
    for (size_t i = 0; i < max_records; ++i) {
        offsets[i] = ftell(file);  // save current file position as offset

        if (fscanf(file, "%d %255s", &keys[i], buffer) != 2) {  // read a key and string from the file
            fprintf(stderr, "Error reading from file\n");
            exit(EXIT_FAILURE);
        }

        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        }

        // Set record value to random int within a given range.
        records[i]->value = rand() % 100;
        records[i]->string_ptr = malloc(strlen(buffer) + 1);
        if (records[i]->string_ptr == NULL) {
            fprintf(stderr, "Memory allocation error\n");
            exit(EXIT_FAILURE);
        }

        strcpy(records[i]->string_ptr, buffer);  // copy string from buffer to record's pointer
    }

    pthread_mutex_lock(&lock);  // lock mutex before memory cleanup
    for (size_t i = 0; i < max_records; ++i) {
        free(records[i]->string_ptr);
        free(records[i]);
    }

    pthread_mutex_unlock(&lock);  // unlock mutex post memory cleanup
    free(offsets);
    free(keys);
    free(records);
}
```
Please note that this code does not handle null pointers or invalid file descriptors. It's also advisable to use a more robust error handling strategy in production level code. This includes error checking at various points throughout the function, especially after calls to `malloc` and other memory allocation functions. Additionally, you may need to adjust this code based on your specific requirements.
