unsigned char* calculateSHA256(const char* filename){
  FILE *file = fopen (filename, "rb");
  if(file == NULL) return NULL; // error in opening the file. Handle it properly

  unsigned char *hash = malloc(sizeof(char)*(SHA256_DIGEST_LENGTH + 1));

  SHA256_CTX sha256;
  SHA256_Init(&sha256);
  const int bufSize = 32768; // define a reasonable buffer size to read file chunk by chunk
  unsigned char *buffer = malloc(bufSize);
  if (buffer == NULL) return NULL; // error in allocation memory. Handle it properly

  int bytesRead = 0;
  while((bytesRead = fread(buffer, 1, bufSize, file))) {
      SHA256_Update(&sha256, buffer, bytesRead);
  }

  SHA256_Final(hash, &sha256);

  free(buffer); // don't forget to free the allocated memory
  fclose (file);

  return hash;
}
