#include <fcntl.h>
#include <time.h>

typedef struct {
    int value;
    char *str_ptr;
} record;

typedef struct {
    int fd;
    size_t buffer_size;
} file_info;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* processFiles(void *arg) {
    char **files = (char**) arg;
    long *offsets = malloc(sizeof(*offsets));
    int *keys = malloc(sizeof(*keys));
    record *records = malloc(sizeof(*records));
    file_info *fileInfos = malloc(sizeof(*fileInfos));

    srand(time(NULL));   // Initialization, should only be called once.

    for (int i = 0; files[i] != NULL; ++i) {
        int fd = open(files[i], O_RDONLY);

        if (fd == -1) {
            perror("Error opening file");
            continue;
        }

        struct stat st;
        if (fstat(fd, &st) != 0) {
            close(fd);
            perror("Failed to get file status");
            continue;
        }

        size_t bufferSize = (size_t) st.st_size + 1;  // +1 for the null terminator
        char *buffer = malloc(bufferSize);

        if (!buffer) {
            close(fd);
            perror("Failed to allocate memory");
            continue;
        }

        ssize_t bytesRead = read(fd, buffer, bufferSize - 1);
        if (bytesRead < 0) {
            free(buffer);
            close(fd);
            perror("Error reading from file");
            continue;
        }

        buffer[bytesRead] = '\0';  // Null-terminate the string.

        pthread_mutex_lock(&mutex);

        offsets[i] = ftell(fd);
        keys[i] = rand() % 100;   // Set a random key within range 0 - 99

        records[i].value = rand();    // Random int value
        records[i].str_ptr = buffer;

        fileInfos[i].fd = fd;
        fileInfos[i].buffer_size = bufferSize;

        pthread_mutex_unlock(&mutex);
    }

    // Handle memory deallocation...

    return NULL;
}
```

