void* allocateAndInitialize(size_t size, int range) {
    // Lock the mutex to prevent simultaneous access from multiple threads
    pthread_mutex_lock(&lock);

    srand((unsigned int) time(NULL)); 
    double* arr1 = (double*) malloc(size * sizeof(double));
    if (!arr1) {
        // Error handling for memory allocation failure.
        fprintf(stderr, "Memory allocation failed!\n");
        pthread_mutex_unlock(&lock); 
        return NULL;
    }

    Point* arr2 = (Point*) malloc(size * sizeof(Point));
    if (!arr2) {
        // Error handling for memory allocation failure.
        fprintf(stderr, "Memory allocation failed!\n");
        free(arr1); 
        pthread_mutex_unlock(&lock); 
        return NULL;
    }

    Rectangle* arr3 = (Rectangle*) malloc(size * sizeof(Rectangle));
    if (!arr3) {
        // Error handling for memory allocation failure.
        fprintf(stderr, "Memory allocation failed!\n");
        free(arr1); 
        free(arr2);
        pthread_mutex_unlock(&lock); 
        return NULL;
    }

    // Initialize arrays with random values within the specified range.
    for (size_t i = 0; i < size; ++i) {
