```python
class MemoryPool:
    def __init__(self):
        self.memory = {}

    def allocate(self, size):
        free_blocks = [i for i in range(len(self.memory)) if not self.memory[i]]
        if not free_blocks or len(free_blocks) < size:
            new_block = len(self.memory)
            self.memory[new_block] = True
        else:
            new_block = free_blocks[:size]
            for i in new_block:
                self.memory[i] = True
        return new_block
```

