Part 2: C function for calculating MD5 hash and storing in linked list:
```c
#include <openssl/md5.h>
#include <stdio.h>

typedef struct FileHash {
    char* filePath;
    unsigned char md5[MD5_DIGEST_LENGTH];
    struct FileHash* next;
} FileHash;

void calculateAndStoreMD5(char** filePaths, int count) {
    // Allocate memory for head of linked list
    FileHash* head = malloc(sizeof(*head));
    if (head == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    FileHash* currentNode = head;
    for (int i = 0; i < count; ++i) {
        FILE* file = fopen(filePaths[i], "rb");  // Open file in binary mode

        if (file == NULL) {
            printf("Failed to open file: %s\n", filePaths[i]);
            continue;
        }

        unsigned char* buffer = malloc(1024);
        MD5_CTX context;
        MD5_Init(&context);

        // Read file in chunks and update hash
        int bytesRead;
        while ((bytesRead = fread(buffer, 1, 1024, file)) != 0) {
            MD5_Update(&context, buffer, bytesRead);
        }

        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5_Final(md5, &context);

        // Store hash in linked list node
        currentNode->filePath = filePaths[i];
        memcpy(currentNode->md5, md5, MD5_DIGEST_LENGTH);

        free(buffer);  // Free memory allocated for buffer
        fclose(file);  // Close the file

        if (i < count - 1) {
            // Allocate and link next node in linked list
            currentNode->next = malloc(sizeof(*currentNode));

            if (currentNode->next == NULL) {
                printf("Memory allocation failed.\n");
                exit(EXIT_FAILURE);
            }

            currentNode = currentNode->next;
        } else {
            // Mark end of linked list
            currentNode->next = NULL;
        }
    }

    // Further processing of the linked list...

    // Free allocated memory when it's no longer needed
    while (head != NULL) {
        FileHash* temp = head;
        head = head->next;
        free(temp);
    }
}
```
Part 3: Java function for calculating disjoint pairs in an array using Union-Find data structure:
```java
import java.util.*;

public class Main {
    private static int[] parents, rank;

    public static void main(String[] args) {
        int[] arr = new int[]{1, 2, 3, 4, 5};  // Example array
        System.out.println("Number of disjoint pairs: " + calculateDisjointPairs(arr));
    }

    public static int calculateDisjointPairs(int[] arr) {
        initUnionFind(arr.length);

        Map<Integer, List<Integer>> map = new HashMap<>();
        for (int i = 0; i < arr.length; ++i) {
            if (!map.containsKey(arr[i])) {
                map.put(arr[i], new ArrayList<>());
            }

            map.get(arr[i]).add(i);
        }

        for (List<Integer> indices : map.values()) {
            for (int i = 1; i < indices.size(); ++i) {
                union(indices.get(i), indices.get(0));
            }
        }

        Map<Integer, Integer> parentCounts = new HashMap<>();
        for (int i : arr) {
            int parent = find(map.get(i).get(0));  // Find representative of set

            if (!parentCounts.containsKey(parent)) {
                parentCounts.put(parent, 0);
            }

            parentCounts.put(parent, parentCounts.get(parent) + 1);
        }

        int pairs = 0;
        for (int count : parentCounts.values()) {
            pairs += count * (count - 1) / 2;  // Calculate number of pairs from combinations
        }

        return pairs;
    }

    private static void initUnionFind(int n) {
        parents = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; ++i) {
            parents[i] = i;
            rank[i] = 0;
        }
    }

    private static void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parents[rootY] = rootX;
            } else {
                parents[rootX] = rootY;

                if (rank[rootX] == rank[rootY]) {
                    rank[rootY]++;
                }
            }
        }
    }

    private static int find(int x) {
        if (parents[x] != x) {
            parents[x] = find(parents[x]);  // Path compression
        }

        return parents[x];
    }
}
```
