void* allocate_and_init(size_t num_offsets, size_t num_keys, size_t num_records) {
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0) {
        printf("Error: Invalid sizes\n");
        return NULL;
    }

    long* offsets = malloc(sizeof(long) * num_offsets);
    if (offsets == NULL) {
        printf("Error: Allocation failed for offsets\n");
        return NULL;
    }

    int* keys = calloc(num_keys, sizeof(int)); // To ensure that all values are initially 0.
    if (keys == NULL) {
        printf("Error: Allocation failed for keys\n");
        free(offsets);
        return NULL;
    }

    Record* records = malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        printf("Error: Allocation failed for records\n");
        free(keys);
        free(offsets);
        return NULL;
    }

    srand((unsigned int)time(NULL)); // For random number generation.

    // Initialization of offsets array.
    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = i;
    }

    // Initialization of keys array with unique random values.
    int usedKeys[1001] = { 0 }; // For keeping track of used key values.
    for (size_t i = 0; i < num_keys; ++i) {
        while (1) {
            int randKey = rand() % 1001; // Generate a random value within the specified range (0 to 1000).

            if (!usedKeys[randKey]) {
                keys[i] = randKey;
                usedKeys[randKey] = 1;
                break;
            }
        }
