}

Record* createRecords(int num, int limit){
    srand(time(0));
    Record *recs = malloc(sizeof(Record) * num);
    if (recs == NULL) exit(-1); // handle memory allocation failure

    for (int i = 0; i < num; ++i) {
        recs[i].intValue = rand() % limit + 1;

        int strLen = rand() % 11 + 10; // string length between 10 and 20
        recs[i].strPtr = malloc(sizeof(char) * (strLen+1)); // add room for null terminator
        if (recs[i].strPtr == NULL) exit(-1); // handle memory allocation failure

        memset(recs[i].strPtr, 'a' + rand() % 26, strLen); // fill with random chars
        recs[i].strPtr[strLen] = '\0'; // null terminate string
    }

    return recs;
}

void freeRecords(Record *recs, int num) {
    for (int i = 0; i < num; ++i){
