typedef struct {
    int PRODUCT_ID;
    float PRICE;
    int STOCK_QUANTITY;
} PRODUCT_T;

float readFloats(float **numbers, size_t *len) {
    float max = 0.0f;
    size_t capacity = 1024;
    *len = 0;
    *numbers = malloc(capacity * sizeof(**numbers));

    if (*numbers == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    float num;
    while (scanf("%f", &num) == 1) {
        if (*len >= capacity) {
            capacity *= 2;
            *numbers = realloc(*numbers, capacity * sizeof(**numbers));
            if (*numbers == NULL) {
                perror("realloc failed");
                exit(EXIT_FAILURE);
            }
        }

        (*numbers)[(*len)++] = num;
        max = (num > max)? num : max;
    }

    return max;
}

PRODUCT_T *readProducts(size_t *n, size_t limit) {
    PRODUCT_T *products = malloc(limit * sizeof(*products));

    if (products == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    for (*n = 0; *n < limit; ++*n) {
        if (scanf("%d %f %d", &products[*n].PRODUCT_ID, &products[*n].PRICE, &products[*n].STOCK_QUANTITY) != 3) {
            perror("Invalid input");
            exit(EXIT_FAILURE);
        }
    }

    return products;
}

int main(int argc, char *argv[]) {
    sem_t *sem = sem_open("/mySemaphore", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return EXIT_FAILURE;
    }

    size_t n = 0, limit = atoi(argv[1]);
    if (limit <= 0) {
        printf("Invalid argument\n");
        return EXIT_FAILURE;
    }

    float *numbers = NULL;
    size_t len;

    sem_wait(sem);
    float max = readFloats(&numbers, &len);
    printf("The largest number is %.2f\n", max);
    free(numbers);
    sem_post(sem);
    sem_close(sem);

    PRODUCT_T *products = NULL;

    sem_wait(sem);
    products = readProducts(&n, limit);
    for (size_t i = 0; i < n; ++i) {
        printf("PRODUCT ID: %d PRICE: %.2f STOCK QUANTITY: %d\n", 
               products[i].PRODUCT_ID, products[i].PRICE, products[i].STOCK_QUANTITY);
    }
    free(products);
    sem_post(sem);

    return EXIT_SUCCESS;
}
