    free(offsets);  // Free offsets array
    free(keys);     // Free keys array
    free(records);  // Free records array of pointers
}

FileHash* calculateMD5HashOfFiles() {

    char filePath[1024];
    FileHash *head = NULL;

    while (fgets(filePath, sizeof(filePath), stdin) != NULL) {  // Read paths from standard input
        FILE *file = fopen(filePath, "rb");  // Open file in binary mode

        if (file == NULL) continue;  // Skip invalid files

        unsigned char md5[MD5_DIGEST_LENGTH];

        MD5_CTX context;
        MD5_Init(&context);

        int bytes;
        unsigned char data[1024];

        while ((bytes = fread(data, 1, 1024, file)) != 0) {
            MD5_Update(&context, data, bytes);
        }

        MD5_Final(md5, &context);

        FileHash *newNode = malloc(sizeof(FileHash));

        if (newNode == NULL) continue;  // Skip invalid files

        newNode->filePath = strdup(filePath);
        memcpy(newNode->md5, md5, MD5_DIGEST_LENGTH);

        newNode->next = head;
        head = newNode;  // Add at the beginning of linked list

        fclose(file);  // Close file
    }

    return head;  // Return head of linked list
}
