} Record;

typedef struct {
    long* offsets; // array of offset values
    int* keys;     // array of unique keys for each record
    Record** records;// dynamic 2D array of Records where each row is a dataset and columns are records in that set
} DataSet;

DataSet* createDataSets(int numDataSets, int dataSetSize) {
    srand(time(NULL)); // initialize random number generator for 'random' values within record range

    // Allocate memory for the main struct which contains all datasets
    DataSet* data = malloc(numDataSets * sizeof(DataSet));
    if (!data) {
        return NULL; // failed to allocate main memory, return error
    }

    // For each dataset...
    for (int i = 0; i < numDataSets; ++i) {
        data[i].offsets = malloc(dataSetSize * sizeof(long));
        data[i].keys = malloc(dataSetSize * sizeof(int));
        data[i].records = malloc(dataSetSize * sizeof(Record*));

        if (!data[i].offsets || !data[i].keys || !data[i].records) {
            // free previously allocated memory for this dataset before returning error
            freeDataset(&data[i]); 
            free(data);
            return NULL;
        }

        // For each record in the dataset...
        for (int j = 0; j < dataSetSize; ++j) {
            // Allocate memory for this record
            Record* record = malloc(sizeof(Record)); 

            if (!record) {
                // free previously allocated memory and return error
                for (int k = j - 1; k >= 0; --k) {
                    free(data[i].records[k]);
                }

                freeDataset(&data[i]); 
                free(data);
                return NULL;
            }

            data[i].offsets[j] = 0L; // set offset to default value (could be randomized based on your requirements)
            data[i].keys[j] = j + 1; // unique key for each record, could be hashed from content in future iterations

            record->value = rand() % 2001 - 1000; // set random value within [-1000, 1000] range
            data[i].records[j] = record;
        }
    }

    return data;
}

void freeDataset(DataSet* dataset) {
    for (int i = 0; i < sizeof(*dataset->records); ++i) {
       if (dataset->records[i]) {
           free(dataset->records[i]); // free each record in this dataset
       }
    }

    // free remaining arrays in the dataset
    free(dataset->offsets); 
    free(dataset->keys);
    free(dataset->records);
}
```
