#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "MQTTClient.h"
#define MAX_CONNECTIONS 5
#define MAX_SENSORS 1000

typedef struct {
    double value;
    char id[64];
} SensorData;

typedef struct {
    bool isConnected;
    int timeout;
    MQTTClient client;
} MqttConnection;

SensorData *allocateAndInitializeSensors(int num_sensors) {
    if (num_sensors > MAX_SENSORS || num_sensors <= 0) return NULL;

    SensorData *sensorArray = malloc(sizeof(SensorData) * num_sensors);
    for (int i = 0; i < num_sensors; ++i) {
        strncpy(sensorArray[i].id, "DefaultId", sizeof(sensorArray[i].id));
        sensorArray[i].value = 0.0;
    }

    return sensorArray;
}

MqttConnection *establishMqttConnection(char* broker_address) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    MqttConnection *mqttConn = malloc(sizeof(MqttConnection));
    if (mqttConn == NULL) return NULL;

    int rc = 0;
    if ((rc = MQTTClient_create(&(mqttConn->client), broker_address, "sensor_data", MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        printf("Failed to create client, return code %d\n", rc);
        free(mqttConn);
        return NULL;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    if ((rc = MQTTClient_connect(mqttConn->client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        printf("Failed to connect, return code %d\n", rc);
        free(mqttConn);
        return NULL;
    }

    mqttConn->isConnected = true;
    return mqttConn;
}

void logEvent(const char* message) {
    FILE *logFile = fopen("systemLog.txt", "a");
    if (logFile == NULL) {
        printf("Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(logFile, "%d-%02d-%02d %02d:%02d:%02d - %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, 
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);

    fclose(logFile);
}

void freeAllocatedMemory(SensorData* sensors) {
    if (sensors != NULL) free(sensors);
}
```
