// Define a simple logger class
class Logger {
public:
    enum Level {
        Debug,
        Release
    };

    static void log(Level level, const std::string& message) {
        if (level == Level::Debug && !debugMode) return;

        std::lock_guard<std::mutex> lock(mtx);
        std::cout << message << '\n';
    }

    static bool debugMode;
private:
    static std::mutex mtx; // mutex for critical section
};

// Static member initialization
bool Logger::debugMode = true;
std::mutex Logger::mtx;

class Item { /* Implement your item class here */ };

int main() {
    int numItems, numThreads;
    std::cout << "Enter number of items and threads: ";
    std::cin >> numItems >> numThreads;

    // Create a vector to hold our items. This will be thread-safe due to the use of locks in our logging mechanism.
    std::vector<Item> items(numItems);
    std::mutex itemMutex[numItems];

    auto process = [&](int id, int start, int end) {
        for (int i = start; i < end; ++i) {
            std::lock_guard<std::mutex> lock(itemMutex[i]); // thread-safe access to individual items

            std::stringstream ss;
            ss << "Thread " << id << " is processing item " << i;
            Logger::log(Logger::Debug, ss.str());
        }
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i) {
        int start = i * numItems / numThreads;
        int end = (i+1) * numItems / numThreads;

        // Create and run the thread. Note that we're passing arguments by value, not reference.
        threads.push_back(std::thread(process, i, start, end)); 
    }

    for (auto& thread : threads) {
        thread.join(); // wait for all threads to finish
    }

    return 0;
}
```
