```C
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>
#include <time.h>
#include <stdlib.h>

typedef struct {
    int value;
    char *str;
} item;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocateAndInit(const char* filename, double** doubles, char** keys, item** items) {
    FILE* fp = fopen(filename, "r");

    if (fp == NULL) {
        perror("Error opening file: ");
        return NULL;
    }

    json_object *jobj = json_object_from_file(filename);  // load JSON object from file

    int size = json_object_array_length(jobj);           // get length of JSON array

    pthread_mutex_lock(&lock);                            // lock mutex to avoid data race

    *doubles = malloc(size * sizeof(double));              // allocate memory for double array
    if (*doubles == NULL) {
        perror("Error allocating memory for doubles: ");
        pthread_mutex_unlock(&lock);                     // unlock mutex before return
        return NULL;
    }

    *keys = malloc(size * sizeof(char));                  // allocate memory for char array
    if (*keys == NULL) {
        perror("Error allocating memory for keys: ");
        free(*doubles);                                  // clean up allocated memory before return
        pthread_mutex_unlock(&lock);                      // unlock mutex before return
        return NULL;
    }

    *items = malloc(size * sizeof(item));                 // allocate memory for struct item array
    if (*items == NULL) {
        perror("Error allocating memory for items: ");
        free(*doubles);                                  // clean up allocated memory before return
        free(*keys);                                      // clean up allocated memory before return
        pthread_mutex_unlock(&lock);                      // unlock mutex before return
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        json_object *jitem = json_object_array_get_idx(jobj, i);  // get JSON object at index i

        (*doubles)[i] = json_object_get_double(json_object_object_get(jitem, "double"));  // extract double value
        (*keys)[i] = *json_object_get_string(json_object_object_get(jitem, "key"));         // extract char key
        srand(time(0));                                                      // seed random number generator with current time
        (*items)[i].value = rand() % 100;                                   // assign a random value to item's int field
        (*items)[i].str = strdup(json_object_get_string(jitem, "str"));       // duplicate string from JSON data and assign it
    }

    pthread_mutex_unlock(&lock);                        // unlock mutex after allocation and initialization

    return NULL;                                         // return void pointer for compatibility with pthread API
}

void cleanup(double* doubles, char* keys, item* items) { 
    free(doubles);                                      // clean up allocated memory
    free(keys);
    free(items);
}
