```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

typedef struct Record {
    int value;
    char* str;
} Record;

int allocate_memory(long offset[], int keys[], Record records[], char *strings[], size_t n) {
    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < n; ++i) {
        // Allocate memory
        offset[i] = rand() % 100;
        keys[i] = rand() % 100;

        records[i].value = rand() % 100;
        records[i].str = (char*)malloc(10 * sizeof(char)); // Allocate memory for string

        if (!records[i].str) {
            return -1;
        }

        for (size_t j = 0; j < 9; ++j) { // Generate a random alphanumeric string
            int r = rand() % (26 + 26 + 10);

            if (r < 26) {
                records[i].str[j] = 'a' + r;
            } else if (r < (26 + 26)) {
                records[i].str[j] = 'A' + r - 26;
            } else {
                records[i].str[j] = '0' + r - 26 - 26;
            }
        }

        records[i].str[9] = '\0';
    }

    return 0;
}

void free_memory(long offset[], int keys[], Record records[], char *strings[], size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (records[i].str) {
            free(records[i].str); // Free string memory
        }
    }

    free(offset);
    free(keys);
    free(records);
}

void* thread_func(void *args) {
    long offset;
    int key;
    Record record;
    char *string;

    // Thread safe allocation of memory
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    int err = allocate_memory(&offset, &key, &record, &string, 1);
    pthread_mutex_unlock(&mutex);

    if (err != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Handle the record's value here...

    free_memory(&offset, &key, &record, &string, 1);
}
```
This code snippet creates a thread-safe function to allocate memory and generate a random alphanumeric string. The `pthread_mutex` object is used for controlling access to the shared resources from multiple threads. The `allocate_memory` function uses a loop to set the value of each record's int field to a random value within a given range.
